window.JASTROW_CHUNKS[20]={"8000":{"h":"*הַלְטָאָה","r":"E00547","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"לְטָאָה\">לְטָאָה</a>, a species of <i>lizard</i>. <span class=\"citation\">Pes. 88ᵇ</span> <span dir=\"rtl\">נמצאת ה׳</span> a lizard was found. <span class=\"citation\">Ḥull. 122ᵇ</span> <span dir=\"rtl\">גישתא דה׳</span> the touch of the skin of &amp;c. [In Mishn., Tosefta a. Sifra <a href=\"#\" data-headword=\"לְטָאָה\">לטאה</a>, with defin. article <a href=\"#\" data-headword=\"ה\">ה</a>.]</div>","alt":[]},"8001":{"h":"הַלְטָתָא","r":"E00548","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Lev. XI, 30</span> (ed. Berl. <a href=\"#\" data-headword=\"חַלְּטָתָא\">חַלְּטָתָא</a>, Var. <a href=\"#\" data-headword=\"חוּלְטֵיתָא\">חוּלְטֵיתָא</a>, v. Berl. Targ. O. II, p. 34).</div>","alt":[]},"8002":{"h":"הֲלִי","r":"E00549","html":"<div class=\"sense\"> (synon. with <a href=\"#\" data-headword=\"לאי\">לאי</a>, <a href=\"#\" data-headword=\"לְהִי\">להי</a>) <i>to be faint, to labor</i>. <span class=\"citation\">Targ. Is. XLII, 4</span> ed. Lag. (ed. <span dir=\"rtl\">ילהי</span>). <span class=\"citation\">Ib. LXV, 23</span> <span dir=\"rtl\">יהלון</span> (some ed. <span dir=\"rtl\">יח׳</span>; ed. Lag. <span dir=\"rtl\">ילהון</span>). <span class=\"citation\">Targ. Jer. LI, 58</span>.</div><div class=\"sense\"><b>Af. אַהֲלֵי</b> <div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"הֲלִי\">הַלֵּי</a> <i>to fatigue</i>. <span class=\"citation\">Targ. Is. VII, 13</span> <span dir=\"rtl\">מַהֲלָן</span> (Buxt. <span dir=\"rtl\">מְהַלָּן</span>).</div></div>","alt":["הֲלָא"]},"8003":{"h":"הִלְיוֹנִי","r":"E00550","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִלְכְתָא\">הִילְ׳</a></div>","alt":[]},"8004":{"h":"הִלְיַיסְטוֹן","r":"E00551","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלְיַסְטוֹן\">אִלְיַסְטוֹן</a></div>","alt":[]},"8005":{"h":"הֲלִיךְ","r":"E00552","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲלַךְ\">הֲלַךְ</a></div>","alt":[]},"8006":{"h":"הֲלִיכָה","r":"E00553","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>going, going away; walking; run</i>. <span class=\"citation\">Pes. 8ᵇ</span> <span dir=\"rtl\">בהֲלִיכָתָן</span> on their going (opp. <a href=\"#\" data-headword=\"חֲזִירָה I\">חזירה</a>, return). <span class=\"citation\">Keth. 111ᵃ</span> <span dir=\"rtl\">אל תרבה בה׳</span> do not walk too much. <span class=\"citation\">Sot. 12ᵇ</span> <span dir=\"rtl\">אין ה׳ זו וכ׳</span> this ‘going’ (<span class=\"citation\">Ex. II, 5</span>) means death. <span class=\"citation\">Ḥull. I, 2</span> <span dir=\"rtl\">בדרך הֲלִיכָתָהּ</span> in the direction in which its indentations run (not against them); a. fr.—[<span class=\"citation\">Y. B. Kam. X, 7ᵇ</span> bot. <span dir=\"rtl\">שגְזֵלוֹ מן הה׳</span>, read: <a href=\"#\" data-headword=\"הֲלָכָה\">ההֲלָכָה</a>, v. <span class=\"citation\">Y. Keth. II, end, 27ᵃ</span>.]—Pl. <span dir=\"rtl\">הֲלִיכוֹת</span>. <span class=\"citation\">Meg. 28ᵇ</span>; <span class=\"citation\">Nidd. 73ᵃ</span>, v. <a href=\"#\" data-headword=\"הֲלָכָה\">הֲלָכָה</a>.</div>","alt":[]},"8007":{"h":"הֲלִיכְתָּא","r":"E00554","html":"<div class=\"sense\"> constr. <a href=\"#\" data-headword=\"הֲלִיכָה\">הֲלִיכָת</a>. <span class=\"citation\">Targ. Ps. LXVIII, 25</span>. [Ib. <span dir=\"rtl\">הְלִיכוֹת</span>, corr. acc.]</div>","alt":[]},"8008":{"h":"הַלֵּילָא","r":"E00555","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַלֵּלָא\">הלֵּלָא</a></div>","alt":[]},"8009":{"h":"הליס","r":"E00556","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"וָולִיס\">וָולִיס</a></div>","alt":[]},"8010":{"h":"הליסטיון","r":"E00557","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"הִלְיַיסְטוֹן\">הִלְיַיסְטוֹן</a>.</div>","alt":[]},"8011":{"h":"הֵלֵךְ","r":"E00558","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֵילֵךְ\">הֵילֵךְ</a></div>","alt":[]},"8012":{"h":"הָלֵין","r":"E00559","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (contract. of <span dir=\"rtl\">הָאִילֵּין</span>) <i>these, those, these things</i>. <span class=\"citation\">Targ. Prov. XXIV, 23</span>. <span class=\"citation\">Ib. XXXI, 8</span>.—<span class=\"citation\">Ned. 91ᵇ</span>. <span class=\"citation\">Ib. 79ᵇ</span> <span dir=\"rtl\">ה׳ וה׳</span> both; a. fr.—<span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">הֵילֵין תאיניא</span> (<span class=\"citation\">Koh. R. to II, 20</span> <span dir=\"rtl\">הלין</span>) these figs here.</div>","alt":[]},"8013":{"h":"הִלֵּין","r":"E00560","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"הַיְילֵין\">הַיְילֵין</a>) <i>which? what?</i> <span class=\"citation\">Targ. Y. Ex. I, 10</span> <span dir=\"rtl\">בה׳ דינין</span> by what laws.</div>","alt":[]},"8014":{"h":"הָלַךְ","r":"E00561","html":"<div class=\"sense\"> (b. h.) <i>to go, go away; to walk</i>. <span class=\"citation\">Yeb. 84ᵃ</span> <span dir=\"rtl\">כשהָלַכְתִּי וכ׳</span> when I left home to study with &amp;c. <span class=\"citation\">Macc. 10ᵇ</span>, a. e. <span dir=\"rtl\">בדרך שאדם רוצה לֵילֵךְ בה מוֹלִיכִין אותו</span> whatever way one desires to go, one is led; a. v. fr.—<span dir=\"rtl\">הוֹלְכֵי מדברות</span> travellers through the desert. <span class=\"citation\">Taan. 27ᵇ</span>; a. e.—<span class=\"citation\">Y. Kidd. I, 61ᵈ</span> <span dir=\"rtl\">כהולכים בתורת ד׳</span> (not <span dir=\"rtl\">בה׳</span>) as though they did walk in the law &amp;c.—Imper. <a href=\"#\" data-headword=\"לֵךְ\">לֵךְ</a>, <a href=\"#\" data-headword=\"לְכָה\">לְכָה</a>, v. <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a> <i>Pi.</i>, a. <a href=\"#\" data-headword=\"כַּלֵּךְ\">כַּלֵּךְ</a>.</div><div class=\"sense\"><b>Pi. הִילֵּךְ  הִלֵּךְ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"הִלֵּין\">same</a>, <a href=\"#\" data-headword=\"הִלֵּין\">same</a>, <i>to walk, tread upon</i>. <span class=\"citation\">Ḥull. IX, 2</span> (<span class=\"citation\">122ᵃ</span>) <span dir=\"rtl\">או שהי׳ בהן</span> (Mish. ed. <span dir=\"rtl\">שהלך</span>) or trod upon them for tanning purposes. <span class=\"citation\">Erub. 100ᵇ</span> <span dir=\"rtl\">שיְהַלֵּךְ ע&quot;ג וכ׳</span> to tread upon plants. <span class=\"citation\">Gen. R. s. 39</span> <span dir=\"rtl\">מְהַלֵּךְ בארם וכ׳</span> travelling through Aram &amp;c.—<span class=\"citation\">Keth. 60ᵃ</span>; <span class=\"citation\">Ker. 22ᵃ</span> <span dir=\"rtl\">מְהַלְּכֵי שתים</span> walking on two legs (human beings); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cause opening of the bowels</i>. Y. Kil. I, 27ᵃ top <span dir=\"rtl\">מְהַלֶּכֶת את בני מיעים</span>; cmp. <a href=\"#\" data-headword=\"הִילּוּךְ\">הִילּוּךְ</a>. [Y. Keth. XII, 35ᵇ top <span dir=\"rtl\">מהלך לפניהן אל הארץ</span>, v. <a href=\"#\" data-headword=\"חֲלַד\">חָלַד</a>.]</div></div><div class=\"sense\"><b>Hif. הוֹלִיךְ</b> <div class=\"sense\"><b>1)</b> <i>to lead; to carry</i>. <span class=\"citation\">Macc. 10ᵇ</span>, v. supra. <span class=\"citation\">Gitt. 4ᵃ</span> <span dir=\"rtl\">המוֹלִיךְ וכ׳</span> he who carries abroad a letter of divorce, contrad. to <span dir=\"rtl\">המביא</span> he who brings a letter from abroad. <span class=\"citation\">Ab. Zar. III, 9</span> <span dir=\"rtl\">יוֹלִיךְ הנאה וכ׳</span> let him cast the profit (one loaf’s value) into the Sea. <span class=\"citation\">Gitt. VI, 1</span> <span dir=\"rtl\">הוֹלֵךְ גט וכ׳</span> carry this letter of divorce (as a messenger). <span class=\"citation\">Ib. 63ᵃ</span> sq. (distinction between <span dir=\"rtl\">הילך</span>, here is the letter of divorce, i.e. take possession of it in behalf of my wife, and <span dir=\"rtl\">הולך</span> carry it, i.e. be my messenger). <span class=\"citation\">Ib. 64ᵃ</span>, a. e. <span dir=\"rtl\">הולך כזכי דמי</span> ‘carry’ (the letter of divorce) is equal to ‘take possession’ (in behalf of her who authorized thee); a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְהַלֵּךְ</b> <div class=\"sense\"><i>to go away, withdraw</i>. <span class=\"citation\">Cant. R. to V, 1</span>; <span class=\"citation\">Gen. R. s. 19</span> (ref. to <span class=\"citation\">Gen. III, 8</span>) <span dir=\"rtl\">מְהַלֵּךְ … אלא מִתְהַלֵּךְ וכ׳</span> it does not say <i>m’hallekh</i> (walking) but <i>mith-hallekh</i>, He hastened and went upward. Ib. <span dir=\"rtl\">מתהלך לו</span> (ed. <span dir=\"rtl\">מת הלך</span>, corr. acc., v. Matt. K.) is he (Adam) going away (from God)?, v. <a href=\"#\" data-headword=\"אֶתְמְהָא\">אתמהא</a>.</div></div>","alt":[]},"8015":{"h":"הֲלַךְ","r":"E00562","html":"<div class=\"sense\">, <i>to walk</i>. <span class=\"citation\">Targ. Ps. CXXVI, 6</span> (Ms. <i>Pa</i>.). <span class=\"citation\">Targ. Y. II, Gen. XXII, 8</span> <span dir=\"rtl\">הֲלִיכוּ</span> (some ed. <a href=\"#\" data-headword=\"חֶלְמוֹן\">הַלִ׳</a>). Contr. <span dir=\"rtl\">יְהָךְ</span>, <span dir=\"rtl\">מְהָךְ</span>, v. <span dir=\"rtl\">הך</span>.</div><div class=\"sense\"><b>Pa. הַלִּיךְ  הַלֵּיךְ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"הָלַךְ\">same</a>. <span class=\"citation\">Targ. O. Gen. V, 22</span>. <span class=\"citation\">Targ. I Sam. XXX, 31</span>; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִתְהַלֵּךְ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"הָלַךְ\">same</a>. <span class=\"citation\">Targ. Ps. CI, 2</span>. <span class=\"citation\">Ib. CXVI, 9</span>.</div></div>","alt":["הֲלִיךְ"]},"8016":{"h":"הֲלָךְ","r":"E00563","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span class=\"citation\">Ezra IV, 13</span>) name of <i>atax</i>, prob. <i>sustenance of marching troops</i>. <span class=\"citation\">B. Bath. 8ᵃ</span>; <span class=\"citation\">Ned. 62ᵇ</span> expl. as <a href=\"#\" data-headword=\"אַרְנוֹן II\">אַרְנוֹנָא</a>. <span class=\"citation\">Gen. R. s. 64</span>, a. e., v. <a href=\"#\" data-headword=\"אַנְגַּרְיָא\">אַנְגַּרְיָא</a>.</div>","alt":[]},"8017":{"h":"הֵלֶךְ","r":"E00564","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>traveller</i>. <span class=\"citation\">Succ. 52ᵇ</span> (ref. to <span class=\"citation\">II Sam. XII, 4</span>) <span dir=\"rtl\">מתחלה קראו ה׳ וכ׳</span></div>","alt":[]},"8018":{"h":"הָלְכָא","r":"E00565","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"הֵילֵךְ\">הֵילֵךְ</a>, <i>hither, thither</i>. <span class=\"citation\">Targ. O. Ex. III, 5</span> (h. text <a href=\"#\" data-headword=\"הָלַם\">הֲלֹם</a>). <span class=\"citation\">Targ. Jud. XIV, 15</span> (h. text <span dir=\"rtl\">הְלֹא</span>, v. <a href=\"#\" data-headword=\"הָלָא\">הָלָא</a>). <span class=\"citation\">Targ. Y. Num. XXI, 35</span>; a. e.</div>","alt":["הַלְכָא"]},"8019":{"h":"הֲלָכָה","r":"E00566","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">הלך</span>) </div><div class=\"sense\"><b>1)</b>  (cmp. <a href=\"#\" data-headword=\"מִנְהָג\">מִנְהָג</a>) <i>practice, adopted opinion, rule</i>.—<span dir=\"rtl\">ה׳ כ־</span> in practice, the opinion of … is the rule. <span class=\"citation\">Keth. 77ᵃ</span> <span dir=\"rtl\">ה׳ כמותו</span>; a. v. fr.—<span dir=\"rtl\">ה׳ למשה מסיני</span> a usage dating from Moses as delivered from Sinai, i.e. <i>a traditional law</i> or <i>a traditional interpretation of a written law</i>. <span class=\"citation\">Kidd. 38ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  in gen. <i>traditional law, tradition, custom.</i> <span class=\"citation\">Orl. III, 9</span> <span dir=\"rtl\">הערלה ה׳</span> the application of the laws of Orlah (v. <a href=\"#\" data-headword=\"עָרְלָה\">עָרְלָה</a>) outside of Palestine is traditional or a custom (<span dir=\"rtl\">הילכות מדינה</span>, v. <span class=\"citation\">Kidd. 38ᵇ</span>).—<span class=\"citation\">Y. Bets. II, 61ᵇ</span> top <span dir=\"rtl\">לה׳</span> as a traditional opinion (of a teacher), opp. <span dir=\"rtl\">לעובדא</span> as his own decision for practice. <span class=\"citation\">Y. Dem. III, 23ᶜ</span> bot., sq. <span dir=\"rtl\">מה׳</span> according to a custom. <span class=\"citation\">Ker. 13ᵇ</span> ‘which the Lord has spoken’ (<span class=\"citation\">Lev. X, 11</span>) <span dir=\"rtl\">זו ה׳</span> that means traditional interpretations. Ib. III, 9 (15ᵇ) <span dir=\"rtl\">אם ה׳ נקבל אם לדין וכ׳</span> if it is a tradition, we must accept it, but if it is a logical inference, there may be an objection to it.</div><div class=\"sense\"><b>—3)</b> <i>law</i>, contrad. to <a href=\"#\" data-headword=\"אַגָּדָה\">אֲגָדָה</a>. <span class=\"citation\">Ber. 31ᵃ</span> <span dir=\"rtl\">מתוך דבר ה׳</span> from discussion about a law, opp. <span dir=\"rtl\">ה׳ פסוקה</span> a decision arrived at after discussion. <span class=\"citation\">Ib. 47ᵇ</span> <span dir=\"rtl\">המחדדין … בה׳</span> who whet each other’s wits in legal discussion. <span class=\"citation\">Snh. 82ᵃ</span> <span dir=\"rtl\">נתעלמה ממנו ה׳</span> the law had escaped his memory. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ראה … ונזכר ה׳</span> he saw an act and recalled the law; a. v. fr.—Pl. <a href=\"#\" data-headword=\"הִלְכוּת\">הֲלָכוֹת</a>, constr. <a href=\"#\" data-headword=\"הִלְכוּת\">הִלְכוֹת</a>, <a href=\"#\" data-headword=\"הִלְכְתָא\">הִילְ׳</a>. Kidd. l. c. <span dir=\"rtl\">הי׳ מדינה</span> (v. R. S. to <span class=\"citation\">Orl. III, 9</span>; ed. <span dir=\"rtl\">הלכתא מדינה</span>, corr. acc.) the usages of the country (outside of Palestine). <span class=\"citation\">Y. Hor. III, end, 48ᶜ</span> <span dir=\"rtl\">אילו ה׳</span> that means the collections of laws (Mishnah). <span class=\"citation\">Tem. 14ᵇ</span> <span dir=\"rtl\">כותבי ה׳</span> those who reduce traditions (oral law) to writing. <span class=\"citation\">Snh. 67ᵇ</span> <span dir=\"rtl\">הי׳ כשפים</span> the laws concerning the punishment of witchcraft. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הלְ׳ יצירה</span> mystic practices. <span class=\"citation\">Sabb. 32ᵃ</span>; <span class=\"citation\">Tosef. ib. II, 10</span>; a. v. fr.—[<a href=\"#\" data-headword=\"הֲלָכָה\">הלכה</a> in Talmud Y., heading of <i>Mishnah</i>, in Talm. Bab. <span dir=\"rtl\">מתני׳</span>.]</div>","alt":[]},"8020":{"h":"הִלְכוּת","r":"E00567","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִלְכְתָא\">הִלְכְתָא</a></div>","alt":["הֲלַכְוָותָא"]},"8021":{"h":"הִלְכָךְ","r":"E00568","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִלְכְתָא\">הִילְ׳</a></div>","alt":[]},"8022":{"h":"*הַלְכְּשִׁישׁ","r":"E00569","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (redupl. of <a href=\"#\" data-headword=\"לֶכֶשׁ\">לכש</a>, cmp. <a href=\"#\" data-headword=\"לֶכֶשׁ\">לֶכֶשׁ</a>) <i>swelling, bruise, sore</i>. <span class=\"citation\">Targ. Y. Ex. XXI, 25</span> (ed. Amst. <span dir=\"rtl\">הֵלְכְ׳</span>; h. text <a href=\"#\" data-headword=\"חַבּוּרָה\">חַבּוּרָה</a>).—Pl. <span dir=\"rtl\">הַלְכְּשׁוּשִׁין</span>, constr. <a href=\"#\" data-headword=\"*הַלְכְּשִׁישׁ\">הַלְכְּשׁוּשֵׁי</a>. <span class=\"citation\">Targ. Ps. XXII, 18</span> (ed. <span dir=\"rtl\">הַלְבְּ׳</span>); <span class=\"citation\">ib. XXXVIII, 6</span> (ed. <span dir=\"rtl\">הלב׳</span>, Ms. <span dir=\"rtl\">הלפ׳</span>, h. text <span dir=\"rtl\">חַבּוּרֹת־</span>). <span class=\"citation\">Targ. Job IX, 17</span> (ed. <span dir=\"rtl\">הלב׳</span>; h. text <span dir=\"rtl\">פְּצָע־</span>).</div>","alt":["הַלְכְּשׁוּשׁ"]},"8023":{"h":"הִלְכְתָא","r":"E00570","html":"<div class=\"sense\"> ch. f. (v. <a href=\"#\" data-headword=\"הֲלָכָה\">הֲלָכָה</a> a. <a href=\"#\" data-headword=\"הֲלִיכָה\"><a href=\"#\" data-headword=\"הֲלִיכָה\">הֲלִיכָה</a>)</a></div><div class=\"sense\"><b>1)</b> <i>step</i>. <span class=\"citation\">Targ. Prov. XVI, 9</span>.—Pl. <span dir=\"rtl\">הִלְכָאתָא</span>, <a href=\"#\" data-headword=\"הִילְכָן\">הִילְכָתָא</a>. <span class=\"citation\">Ib. XXVI, 7</span> (ed. Wil. <a href=\"#\" data-headword=\"הִלְכְתָא\">הַלְכְתָא</a>). <span class=\"citation\">Ib. XXIX, 5</span>; a. e.—<span class=\"citation\">Targ. Ps. XXIII, 3</span> הִלְכְוָותָא ד־ Ms. (ed. Lag. <span dir=\"rtl\">הִילְכְוָת צ׳</span>, ed. Wil. <span dir=\"rtl\">הִלְכַת</span>).</div><div class=\"sense\"><b>—2)</b> <i>custom, habit</i>. <span class=\"citation\">Targ. II Kings XI, 14</span>. <span class=\"citation\">Targ. Y. Gen. XLIII, 33</span>.</div><div class=\"sense\"><b>—3)</b> <i>law, rule</i>. <span class=\"citation\">Targ. Y. Ex. XII, 6</span>; a. e.—<span class=\"citation\">Snh. 51ᵇ</span> <span dir=\"rtl\">ה׳ למשיחא</span> it is a <i>halakhah</i> for the Messianic days (without present application). <span class=\"citation\">Erub. 65ᵃ</span> <span dir=\"rtl\">הי׳ בעיא וכ׳</span>, v. <a href=\"#\" data-headword=\"אִסְתָּן\">אִסְתָּנָא</a>; a. fr.—<span class=\"citation\">Pes. 64ᵃ</span>, a. fr. <span dir=\"rtl\">למאי ה׳</span> for what practical issue &amp;c.?—Pl. <a href=\"#\" data-headword=\"הִלְכְתָא\">הִלְכָתָא</a>. <span class=\"citation\">Ber. 31ᵃ</span>, v. <a href=\"#\" data-headword=\"גִּיבַּר\">גִּיבַּר</a>; a. fr.—<span class=\"citation\">Targ. Koh. XII, 11</span> <span dir=\"rtl\">הִילְכְתִין</span>.—<span class=\"citation\">Lev. R. s. 3</span>, beg. <span dir=\"rtl\">בר הִילְכָן</span> (fr. <a href=\"#\" data-headword=\"הִילְכָא\">הִילְכָא</a>) a scholar.</div>","alt":["הִילְ׳"]},"8024":{"h":"הִלֵּל","r":"E00571","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Hillel</i>, </div><div class=\"sense\"><b>1)</b>  H. the Babylonian (<span dir=\"rtl\">הבבלי</span>) or Senior <span dir=\"rtl\">(הזקן</span>). <span class=\"citation\">Pes. 66ᵃ</span>. <span class=\"citation\">Tosef. Snh. VII, 11</span>. <span class=\"citation\">Yoma 35ᵇ</span> <span dir=\"rtl\">ה׳ מחייב וכ׳</span> the example of Hillel condemns the poor (who plead poverty as an excuse for not studying the Law); a. v. fr.—בֵּית ה׳ <i>Beth-Hillel, the School of H., the Hillelites</i>. <span class=\"citation\">Bets. I, 1</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  H., son of Rabban Gamliel. <span class=\"citation\">Pes. 51ᵃ</span>; <span class=\"citation\">Tosef. M. Kat. II, 16</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  R. H., son of <a href=\"#\" data-headword=\"אָלָס\">אָלָס</a> or <a href=\"#\" data-headword=\"וָולִיס\">וָולָס</a>, an Amora. <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> top. <span class=\"citation\">Gitt. 59ᵃ</span>; a. fr.—[<span class=\"citation\">Y. Bets. V, 63ᵃ</span> bot. <span dir=\"rtl\">ר׳ ליל</span>, prob. a corrupt. or abbrev. of H.]</div><div class=\"sense\"><b>—4)</b>  name of several Amoraim. <span class=\"citation\">Y. Ber. II, 5ᵃ</span> bot.; a. fr. V. Frank. M’bo p. 76ᵃ</div><div class=\"sense\"><b>—5)</b>  one Rabbi H. <span class=\"citation\">Snh. 98ᵇ</span>, sq.</div>","alt":["הִילֵּ׳"]},"8025":{"h":"הָלַל","r":"E00572","html":"<div class=\"sense\"> (b. h.) <i>to be bright, shine.</i> <i>—Pi.</i> הִלֵּל <i>to praise</i>. <span class=\"citation\">Pes. X, 5</span> <span dir=\"rtl\">לְהַלֵּל</span>. <span class=\"citation\">Midr. Till. to Ps. CXIII</span> <span dir=\"rtl\">צריכים אתם להַ׳ לו</span> you must give praise to Him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מנין הַלְלוּ</span> the numerical value of <i>hal’lu</i> (71).</div><div class=\"sense\"><b>Hithpa. הִתְהַלֵּל</b> <div class=\"sense\"><i>to praise one’s self, boast</i>. <span class=\"citation\">Yalk. Jer. 284</span>.</div></div>","alt":[]},"8026":{"h":"הַלֵּל","r":"E00573","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָלַל\">preced.</a>) <i>Hallel</i> (Praise), recitations for Holy Days, consisting of <span class=\"citation\">Ps. CXIII</span> to CXVIII, called <span dir=\"rtl\">ה׳ המצרי</span> Egyptian H. (with ref. to <span class=\"citation\">Ps. CXIV</span>), contrad. to <span dir=\"rtl\">ה׳ הגדול</span> the Large H. (v. differ. opinions <span class=\"citation\">Pes. 118ᵃ</span>). <span class=\"citation\">Pes. X, 7</span>, v. <a href=\"#\" data-headword=\"גָּמַר I\">גָּמַר</a>. <span class=\"citation\">Taan. 28ᵇ</span>; a. fr.</div>","alt":[]},"8027":{"h":"הַלֵּלָא","r":"E00574","html":"<div class=\"sense\"> <span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">ה׳ מצראה</span> (Ms. M. <span dir=\"rtl\">הלי׳ דמצראי</span>) Egyptian Hallel, v. preced.—<span class=\"citation\">Cant. R. to II, 14</span>; <span class=\"citation\">Pes. 85ᵇ</span> bot.; Y. ib. VII, 35ᵇ bot., v. <a href=\"#\" data-headword=\"זֵיתָא I\"><span dir=\"rtl\">זֵיתָא</span> I</a>.—<span class=\"citation\">Taan. 28ᵇ</span> <span dir=\"rtl\">ה׳ דבריש ירחא</span> (Ms. M. <span dir=\"rtl\">הלל דר&quot;ח</span>) the recitation of Hallel on the New Moon Day. <span class=\"citation\">Meg. 14ᵃ</span> <span dir=\"rtl\">קרייתא זו ה׳</span> the reading of the <i>M’gillah</i> takes the place of Hallel; a. e.</div>","alt":["הַלֵּילָא","הַלֵּילָה"]},"8028":{"h":"הָלַם","r":"E00575","html":"<div class=\"sense\"> a. Arab. ḫilm <i>friend;</i> v. Fl. to Levy Talm. Dict. I, p. 558ᵃ) </div><div class=\"sense\"><b>1)</b> <i>to join, weld</i>. <span class=\"citation\">Gen. R. s. 44</span> (ref. to <span dir=\"rtl\">הוֹלֶם פעם</span> <span class=\"citation\">Is. XLI, 7</span>) <span dir=\"rtl\">וה׳ את כל וכ׳</span> and welded all mankind to follow one road to the Lord; Yalk. ib. 76; <span class=\"citation\">Yalk. Is. 313</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be attached, fit closely</i>. <span class=\"citation\">Ab. Zar. 44ᵃ</span> מתנשא שביקש להוֹלְמוֹ ולא הוֹלַמְתּוֹ Ms. M. (ed. <span dir=\"rtl\">שמתנשא לה׳</span>, corr. acc.) ‘he exalted himself’ (<span class=\"citation\">I Kings I, 5</span>) means that he attempted to fasten (the crown to his head), but it would not fit him; <span class=\"citation\">Yalk. Kings 166</span>; <span class=\"citation\">Snh. 21ᵇ</span>.—[<span class=\"citation\">Tosef. Bekh. IV, 13</span> <span dir=\"rtl\">מוהלמות</span>, read: <span dir=\"rtl\">מְבוּלָּמוֹת</span>, v. <a href=\"#\" data-headword=\"בָּלַם I\">בָּלַם</a>.]</div><div class=\"sense\"><b>Hif. הֶהֱלִים</b> <div class=\"sense\"><i>to attach closely, paste on</i>. Y. Ter. X, 47ᵃ bot. <span dir=\"rtl\">מַהֲלִימִין היו</span> they made the pastry adhere to the mouth of the vessel.</div></div>","alt":[]},"8029":{"h":"הַלְמָה","r":"E00576","html":"<div class=\"sense\">, v. <span dir=\"rtl\">חל׳</span></div>","alt":["הֶלְמוֹן"]},"8030":{"h":"הַלְמִי","r":"E00577","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִילְמִי\">הִילְמִי</a></div>","alt":[]},"8031":{"h":"הַלָּן","r":"E00578","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"הָלָא\">הָלָא</a>) <i>there</i>, opp. <a href=\"#\" data-headword=\"כַּאַן\">כַּאן</a>. <span class=\"citation\">Y. Keth. IV, 28ᵈ</span> bot.; <span class=\"citation\">Y. Gitt. V, 46ᵈ</span> bot. <span dir=\"rtl\">בני בנים של כאן בני בנים של ה׳</span> the ‘grandchildren’ here (with reference to maintenance) are legally the same as the ‘grandchildren’ there (with reference to the duty of propagation, i.e. ‘grandchildren are like children’). <span class=\"citation\">Lev. R. s. 10</span> <span dir=\"rtl\">ה׳ תבא לקיחה של כאן … של</span> (ed. Wilno <span dir=\"rtl\">שֶלְּהַלָּן</span>, v. infra) the ‘taking’ here (<span class=\"citation\">Lev. VIII, 2</span>) shall atone for the ‘taking’ there (<span class=\"citation\">Ex. XXXII, 4</span>).—Mostly <a href=\"#\" data-headword=\"להל\">לְהַלָּן</a> <i>there</i>. <span class=\"citation\">B. Kam. 84ᵃ</span> <span dir=\"rtl\">מה לה׳ ממון אף כאן ממון</span> as below (<span class=\"citation\">Ex. XXI, 36</span>) <i>taḥath</i> means pecuniary compensation, so here (ib. 24) &amp;c. <span class=\"citation\">Sot. 38ᵃ</span> <span dir=\"rtl\">נאמר כאן … ונאמר לה׳</span> here (<span class=\"citation\">Num. VI, 27</span>) the expression <i>sum shem</i> is used, and there (<span class=\"citation\">Deut. XII, 5</span>) &amp;c.; a. fr.—<span class=\"citation\">Gen. R. s. 50</span> (expl. <span dir=\"rtl\">גש הלאה</span>, <span class=\"citation\">Gen. XIX, 9</span>) <span dir=\"rtl\">קרב לה׳</span> get nearer there (go away).</div>","alt":["הָלָן"]},"8032":{"h":"הֲלָנָה","r":"E00579","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (לוּן I) <i>leaving over night, undue delay over night</i>. <span class=\"citation\">Meïl. 4ᵇ</span> <span dir=\"rtl\">ה׳ דקעביד בידים</span> the illegal delay of the sprinkling of the blood, an offence which he commits with his hands (omission of an act), opp. to <a href=\"#\" data-headword=\"מַחֲשָׁבָה\">מחשבה</a> undue thought.—<span dir=\"rtl\">הֲלָנַת דין</span> the reserving of the verdict for the next morning. <span class=\"citation\">Snh. 17ᵃ</span>; <span class=\"citation\">34ᵃ</span>; <span class=\"citation\">35ᵃ</span></div>","alt":[]},"8033":{"h":"הַלָּנָה","r":"E00580","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (לוּן II) <i>murmuring, rebellion</i>. <span class=\"citation\">Ex. R. s. 25</span> <span dir=\"rtl\">ומה ה׳ וכ׳</span> what cause was there for rebellion?</div>","alt":[]},"8034":{"h":"הִלְנִי","r":"E00581","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִילְנִי I\">הִילְנִי</a></div>","alt":[]},"8035":{"h":"הַלְעָטָה","r":"E00582","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לָעַט\">לָעַט</a>) <i>stuffing</i>. <span class=\"citation\">Sabb. 155ᵇ</span> <span dir=\"rtl\">ה׳ למקום שיכולה להחזיר</span> by <i>halatah</i> is meant a stuffing to a point of the throat from which the animal can bring it back again to the mouth, opp. <a href=\"#\" data-headword=\"הַמְרָאָה I\">הַמְרָאָה</a> pushing far down the gullet.</div>","alt":[]},"8036":{"h":"הלפשיש","r":"E00583","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*הַלְכְּשִׁישׁ\">הַלְכְּשִׁישׁ</a></div>","alt":[]},"8037":{"h":"הֶלְקֵט","r":"E00584","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">היל׳</span>.</div>","alt":["הִלְקֵט","הִלְקְטִי"]},"8038":{"h":"הַלְקֵיט","r":"E00585","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 156ᵃ</span> <span dir=\"rtl\">מהלקיטין</span>, v. <a href=\"#\" data-headword=\"לְקַט\">לְקַט</a></div>","alt":[]},"8039":{"h":"הַלְקָשָׁה","r":"E00586","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לָקַשׁ\">לָקַשׁ</a>) <i>doing late, procrastination</i>. <span class=\"citation\">Num. R. s. 1</span>, beg. (interpret. <a href=\"#\" data-headword=\"מַאְפֵּלְיָה\">מאפליה</a>, <span class=\"citation\">Jer. II, 31</span>) <span dir=\"rtl\">לשון ה׳</span> it means procrastination; ib. s. 23; Tanḥ. Masé 9; a. e.</div>","alt":[]},"8040":{"h":"הֵם","r":"E00587","html":"<div class=\"sense\"> m. pl. of <a href=\"#\" data-headword=\"הוּא\">הוּא</a>.</div>","alt":[]},"8041":{"h":"הֲמָא","r":"E00588","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"המי\">הֲמִי</a></div>","alt":[]},"8042":{"h":"הֵמַג","r":"E00589","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, only in <a href=\"#\" data-headword=\"הֲדָיָא II\">בַּר ה׳</a> <i>Bar-Hemag</i>, a subspecies of <i>abratha</i> (hyssop). <span class=\"citation\">Sabb. 109ᵇ</span> (defining h. <a href=\"#\" data-headword=\"אֵזוֹב\">אֵזוֹב</a>), v. <a href=\"#\" data-headword=\"אַבְרָתָא\">אַבְרָתָא</a>.</div>","alt":["הֵימַג"]},"8043":{"h":"הַמְגַּנְיָא","r":"E00590","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Beth-Hamgania.</i> <span class=\"citation\">Kil. VI, 4</span> (v. Rabb. D. S. a. l. note).</div>","alt":["הַמְגַּנְיָיה","בֵּית ה׳"]},"8044":{"h":"הַמְדַּאי","r":"E00591","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַמְדָּן\">הַמְדָּן</a></div>","alt":[]},"8045":{"h":"הַמְדּוּדֵי","r":"E00592","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bar-Hamdudé</i> (Var. <span dir=\"rtl\">בר הַמְדּוּרֵי</span> <i>Bar-Hamduré</i>). <span class=\"citation\">Yoma 87ᵇ</span> (v. Rabb. D. S. a. l. note 8). <span class=\"citation\">Sabb. 107ᵇ</span>; <span class=\"citation\">125ᵃ</span> (<span dir=\"rtl\">מר</span>)<span dir=\"rtl\">בר המדורי</span> ed. (Ms. … <span dir=\"rtl\">די</span>, … <a href=\"#\" data-headword=\"דָּא I\">דא</a>). <span class=\"citation\">Yeb. 83ᵇ</span> רי … <span class=\"citation\">Men. 38ᵇ</span> (v. Rabb. D. S. a. l. note 40).</div>","alt":["בַּר ה׳"]},"8046":{"h":"הַמְדּוּרֵי","r":"E00593","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַמְדּוּדֵי\">preced.</a></div>","alt":["בר ה׳"]},"8047":{"h":"המדך","r":"E00594","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַרְמֵיךְ\">הַרְמֵיךְ</a></div>","alt":[]},"8048":{"h":"הַמְדָּן","r":"E00595","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Hamdan</i> (<i>Hamadân</i>, v. Schr. KAT<sup>2</sup> p. 378), <i>Ekbatana</i>, capital of Media, v. <a href=\"#\" data-headword=\"אַחְמְתָא\">אַחְמְתָא</a>. <span class=\"citation\">Kidd. 72ᵃ</span> (ed. <a href=\"#\" data-headword=\"חַמְדָּן\">חַמְדָּן</a>).—[<span class=\"citation\">Targ. I Chr. I, 5</span> Var. in ed. Rahmer <a href=\"#\" data-headword=\"הַמְדָּן\">המדן</a> (ed. <a href=\"#\" data-headword=\"הַמְדַּאי\">הַמְדַּאי</a>, <a href=\"#\" data-headword=\"הַדְיֵיב\">חַ׳</a>, not … <a href=\"#\" data-headword=\"דָּאוֵי\">דָּאֵי</a>); <span class=\"citation\">Targ. Y. Gen. X, 2</span> <a href=\"#\" data-headword=\"הַמְדַּאי\">הַמְדַּיי</a> (not … <a href=\"#\" data-headword=\"דַּיי\">דִּיִי</a>).]</div>","alt":[]},"8049":{"h":"הָמָה","r":"E00596","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"המי\">המי</a></div>","alt":[]},"8050":{"h":"הָמוֹן","r":"E00597","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הָמָה\">preced.</a>) <i>noise, tumult; multitude</i>. <span class=\"citation\">Yoma 20ᵇ</span> קול הֲמוֹנָהּ של רומי Ms. M. (ed. <a href=\"#\" data-headword=\"עוּר I\">העיר</a>); <span class=\"citation\">Lam. R. to V, 18</span>; <span class=\"citation\">Macc. 24ᵃ</span> קול ה׳ של רומי Ms. Ms. (ed. <a href=\"#\" data-headword=\"בָּבֶל\">בבל</a>); <span class=\"citation\">Yalk. Is. 278</span> <span dir=\"rtl\">המוני של כרך גדול</span> (read: <span dir=\"rtl\">הֲמוֹנוֹ</span>), the din of the city of Rome, v. <a href=\"#\" data-headword=\"פּוּטְיוֹלִין\">פּוֹטְיוֹלִין</a>. <span class=\"citation\">Macc. 10ᵃ</span> (ref. to <span class=\"citation\">Koh. V, 9</span>) <span dir=\"rtl\">ללמד בה׳</span> to teach before large crowds; (<span class=\"citation\">Yalk. Koh. 971</span> <span dir=\"rtl\">ללמוד בה׳</span> to study among a crowd of students).—Pl. <a href=\"#\" data-headword=\"הֲמוֹנוּת\">הֲמוֹנִים</a>. <span class=\"citation\">Ex. R. s. 11</span> <span dir=\"rtl\">אתם עשיתם ה׳ ה׳ וכ׳</span> you arranged troops against my children &amp;c.—<span class=\"citation\">Cant. R. to VIII, 11</span> (play on <a href=\"#\" data-headword=\"הָמוֹן\">המון</a>, <span class=\"citation\">ib.</span> <span dir=\"rtl\">באו עליהן המונות</span> (read: <span dir=\"rtl\">המונים</span>) hordes came against them. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שהמו אחריהם הֲמוֹנֵי מלאכים</span> (not <span dir=\"rtl\">מלכים</span>) troops of angels rushed for them (to prevent them from receiving the Law, v. <a href=\"#\" data-headword=\"דדי\">דָּדָה</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שהמו אחר המוני המוניות</span>, read: <span dir=\"rtl\">שהמו אחריהם המוניות</span>, v. <a href=\"#\" data-headword=\"הֲמוֹנוּת\">הְמוֹנוּת</a>.</div>","alt":[]},"8051":{"h":"הָמוֹן ²","r":"E00598","html":"<div class=\"sense\">, <i>multitude</i>. <span class=\"citation\">Targ. Is. XIII, 4</span>. <span class=\"citation\">Targ. II Kings XXV, 11</span>; a. e.</div>","alt":["הֲמוֹנָא"]},"8052":{"h":"הֲמוֹנוּת","r":"E00599","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"הָמוֹן ²\">preced.</a> wds.) <i>troops, crowds</i>. <span class=\"citation\">Cant. R. to VIII, 11</span> (v. <a href=\"#\" data-headword=\"הָמוֹן\">הָמוֹן</a>, end) <span dir=\"rtl\">שהמו אחריהם ה׳ דמלכוותא</span> the hosts of kingdoms were greedy for them (to have a foothold in their country). <span class=\"citation\">Lam. R. to I, 17</span> formerly I used to go up to the Temple <span dir=\"rtl\">ה׳ ה׳ של חגיגה</span> in (singing) troops of pilgrimage. <span class=\"citation\">Lev. R. s. 33</span> <span dir=\"rtl\">הייתם נעשים הומניות הו׳ לע&quot;ז</span> (corr. <span dir=\"rtl\">המו׳</span>) ye used to form troops (noisy processions) for idolatry; v. <a href=\"#\" data-headword=\"*דִּיאוֹנִיסִין\">דִּיאוֹנִיסִין</a>.</div>","alt":["הֲמוֹנִית","הֲמוֹנִיּוֹת"]},"8053":{"h":"המונייא","r":"E00600","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to V, 14</span>, read: <span dir=\"rtl\">חֲמוּנֵיה</span> (v. <a href=\"#\" data-headword=\"חֲמִי\">חמי</a>); v. Pesik. B’shall. p. 90ᵇ</div>","alt":[]},"8054":{"h":"הֵמְטַלְיָא","r":"E00601","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (a popular corrupt. of ἡπατόριον, v. Sm. Ant. s. v. Eupatorium) <i>liver-wort</i>, in gen. <i>herbs used for cooling the blood</i> (cmp. <a href=\"#\" data-headword=\"חוּמְצָן\">חוּמְצָן</a>). <span class=\"citation\">Y. Ned. VII, beg. 40ᵇ</span> <span dir=\"rtl\">במיני אפומליא וכ׳</span> (read: <span dir=\"rtl\">אפוטליא</span> or <span dir=\"rtl\">אימט׳</span>) the various kinds of <i>hepatoria</i>, e.g. Napu, Melissophylon and Colocasia.—<span class=\"citation\">Tosef. Maasr. III, 7</span> <span dir=\"rtl\">אמיטל׳ נהגו בה וכ׳</span> (Var. <span dir=\"rtl\">המטל׳</span>) for <i>hepatoria</i> the scholars allowed no exemption &amp;c. <span class=\"citation\">Tosef. Ab. Zar. IV</span> (<span class=\"citation\">V), 11</span> <span dir=\"rtl\">המיטליא וכ׳</span> (Var. <span dir=\"rtl\">המוט׳</span>) <i>hep</i>. &amp;c. prepared by gentiles; Y. ib. II, 41ᵈ, <span class=\"citation\">Y. Sabb. I, 3ᶜ</span> bot. <span dir=\"rtl\">הרי מוט׳</span> (read: <span dir=\"rtl\">ההֵימ׳</span>); <span class=\"citation\">Ab. Zar. 38ᵇ</span> החמטליא Ms. M. (ed. <span dir=\"rtl\">המט׳</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">היא ה׳ וכ׳</span> ed. (Ms. M. <a href=\"#\" data-headword=\"ח׳\">ח׳</a>) <i>hemtalia</i> is (legally) the same as &amp;c., v. <a href=\"#\" data-headword=\"פְּסִילְיָא\">פְּסִילְיָא</a>. Cmp. <a href=\"#\" data-headword=\"חוּמְטַרְיָא\">חוּמְטַרְיָא</a>.</div>","alt":[]},"8055":{"h":"המי","r":"E00602","html":"<div class=\"sense\"><i>to be noisy, excited, </i>with <span dir=\"rtl\">אחר</span> <i>to rush after, be greedy, envious</i> &amp;c.—<span class=\"citation\">Cant. R. to VIII, 11</span> <span dir=\"rtl\">הָמוּ</span>, v. <a href=\"#\" data-headword=\"הָמוֹן\">הָמוֹן</a> a. <a href=\"#\" data-headword=\"הֲמוֹנוּת\">הֲמוֹנוּת</a>. Part. <span dir=\"rtl\">הוֹמֶה</span>, v. infra; fem. <span dir=\"rtl\">הוֹמִיָּה</span>. Y. M. Kat. III, beg. 81ᶜ (in a riddle) <span dir=\"rtl\">ה׳ בירכתי ביתה</span> she (the soul?) is restless in the corners of her house. <span class=\"citation\">Midr. Till. to Ps. LXXVII</span> <span dir=\"rtl\">הוֹמִים</span> are in commotion.</div><div class=\"sense\"><b>Pi. הִמָּה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"הֵמְטַלְיָא\">same</a>, <i>to covet</i> (with <span dir=\"rtl\">אחר</span>). <span class=\"citation\">Lev. R. s. 22</span> (ref. to <span dir=\"rtl\">אוהב בהמון</span>, <span class=\"citation\">Koh. V, 9</span>) <span dir=\"rtl\">כל מי שהומה ומְהַמֶּה אחר הממון</span> whosoever is greedy and covetous for money; ib. <span dir=\"rtl\">הומה ומה׳ אחר תורה</span> ambitious to accumulate learning; a. e.—<i>Part. pass</i>. f. <a href=\"#\" data-headword=\"מְהוּמָה\">מְהוּמָּת</a> <i>anxious</i>. <span class=\"citation\">Nidd. 5ᵃ</span>, v. <a href=\"#\" data-headword=\"בַּיִת\">בַּיִת</a>.—Denom. <a href=\"#\" data-headword=\"מָמוֹן\">מָמוֹן</a>.</div></div>","alt":["הָמָה"]},"8056":{"h":"המי ²","r":"E00603","html":"<div class=\"sense\">, <i>to be excited, to roar, rumble</i>. <span class=\"citation\">Targ. Jer. IV, 19</span>. <span class=\"citation\">Ib. V, 22</span>; a. e.—[<span class=\"citation\">Targ. Prov. XXVIII, 27</span> מהמי Ar., v. <a href=\"#\" data-headword=\"חֲמָא\">חֲמָא</a>.]</div>","alt":["הֲמָא"]},"8057":{"h":"הֶמְיָה","r":"E00604","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"המי ²\">preced.</a>) = <a href=\"#\" data-headword=\"הָמוֹן\">הָמוֹן</a>, <i>din </i>of a large city. <span class=\"citation\">Sifré Deut. 43</span> [read:] <span dir=\"rtl\">קול ה׳ של רומי מפוטיולין</span>, v. <a href=\"#\" data-headword=\"הָמוֹן\">הָמוֹן</a> a. <a href=\"#\" data-headword=\"פּוּטְיוֹלִין\">פּוּטְיוֹלִין</a>.</div>","alt":["הֶמְיָיה"]},"8058":{"h":"הֵמְיוֹנָס","r":"E00605","html":"<div class=\"sense\"> (corr. <a href=\"#\" data-headword=\"הֵמְיוֹנָס\">הֵמְיוֹנוֹס</a>) m. (ἡμίονος) <i>mule</i> whose sire is an ass. <span class=\"citation\">Gen. R. s. 82</span>, end; <span class=\"citation\">Y. Ber. VIII, 12ᵇ</span> top (expl. <a href=\"#\" data-headword=\"יְמָם\">יִמִם</a>, <span class=\"citation\">Gen. XXXVI, 24</span>); v. <a href=\"#\" data-headword=\"*הֵמְיִיפּוֹס\">הֵמְיִיפּוֹס</a>.</div>","alt":[]},"8059":{"h":"הֶמְיָיה","r":"E00606","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶמְיָה\">הֶמְיָה</a></div>","alt":[]},"8060":{"h":"הֶמְיָין","r":"E00607","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. <i>hemyân</i>, Fl. in Levy Targ. Dict. s. v. <a href=\"#\" data-headword=\"הִמְיָנָא\">הֶמְיָנָא</a>) <i>belt</i>, <i>girdle</i>. <span class=\"citation\">Erub. X, 15</span> (<span class=\"citation\">104ᵇ</span>).—Pl. <span dir=\"rtl\">הֶמְיָינִין</span>. <span class=\"citation\">Succ. V, 3</span> (<span class=\"citation\">51ᵃ</span>) <span dir=\"rtl\">ומהֶמְיָינֵיהֶן היו מפקיעין</span> ed. Y. a. Ms. M. (v. Rabb. D. S. a. l. note) out of their (old) belts they made wicks.</div>","alt":[]},"8061":{"h":"הִמְיָינָא","r":"E00608","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XXXIX, 29</span> (ed. Berl.; oth. ed. <a href=\"#\" data-headword=\"הִימְנוֹן\">הֶמְ׳</a>); a. fr.—<span class=\"citation\">Erub. 94ᵃ</span> שקילו הִמְיָינֵיה וכ׳ Ms. M. (ed. <a href=\"#\" data-headword=\"הימני׳\">הימני׳</a>, corr. acc.) take his belt and tie &amp;c. <span class=\"citation\">Meg. 27ᵇ</span> משבנתיה להִמְיָינָאִי I pawned my belt. <span class=\"citation\">Zeb. 19ᵃ</span> <span dir=\"rtl\">הוה מִדְּלֵי לי המיינאי וכ׳</span> (Ms. M. <a href=\"#\" data-headword=\"הִימְיָנָא\">הִימְיָנָאִי</a>) my belt had slipped upward and he himself pulled it down.—<span class=\"citation\">Sabb. 59ᵇ</span> <a href=\"#\" data-headword=\"הִימְיָנָא\">הִימְיָינָא</a>.—Pl. <span dir=\"rtl\">הִמְיָינִין</span>, <span dir=\"rtl\">הִמְיָ׳</span>, <span dir=\"rtl\">הִמְיָינֵי</span>, <a href=\"#\" data-headword=\"הָדַר\">הִי׳</a>. <span class=\"citation\">Targ. O. Ex. XXVIII, 4</span> (ed. Berl.; oth. ed. <span dir=\"rtl\">הֶ׳</span>).—Sabb. l. c., v. <a href=\"#\" data-headword=\"קַמְרָא\">קַמְרָא</a>.</div>","alt":["הִמְיָנָא","הִימְ׳"]},"8062":{"h":"המיינטון","r":"E00609","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span> top, v. <a href=\"#\" data-headword=\"אַמְיַינְטוֹן\">אַמְיַינְטוֹן</a></div>","alt":[]},"8063":{"h":"*הֵמְיִיפּוֹס","r":"E00610","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἡμίιππος, S.) <i>half-horse, a mule whose sire is a horse</i>. <span class=\"citation\">Gen. R. s. 82</span>, end (expl. <a href=\"#\" data-headword=\"יְמָם\">יֵמִם</a>, <span class=\"citation\">Gen. XXXVI, 24</span>) <a href=\"#\" data-headword=\"המיסו\">המיסו</a> (corr. acc., in oppos. to <a href=\"#\" data-headword=\"הֵמְיוֹנָס\">המיונס</a>); <span class=\"citation\">Y. Ber. VIII, 12ᵇ</span> top <span dir=\"rtl\">ורבנן אמרין היימים</span> (corr. acc.).</div>","alt":["הֵמִיפּוֹס"]},"8064":{"h":"הָמִים","r":"E00611","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָמַם\">המם</a>) <i>confused in mind, delirious</i>. <span class=\"citation\">Y. Gitt. VII, beg. 48ᶜ</span>, expl. <a href=\"#\" data-headword=\"קוּרְדְּיָיקוֹס\">קורדייקוס</a>.</div>","alt":[]},"8065":{"h":"הִמִין","r":"E00612","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֵימ־\">הֵימ׳</a></div>","alt":[]},"8066":{"h":"הִמְיָנָא","r":"E00613","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִמְיָינָא\">הִמְיָינָא</a></div>","alt":[]},"8067":{"h":"הֵמִינָא","r":"E00614","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἡμίνα, hemina) <i>hemina</i>, a liquid measure, half a sextarius (nearly half a pint English).—Pl. <span dir=\"rtl\">הֵמִינִין</span>. Targ. II Esth. I, 8 (ed. Lag. <span dir=\"rtl\">המינון</span>, corr. acc.).</div>","alt":[]},"8068":{"h":"המיסו","r":"E00615","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*הֵמְיִיפּוֹס\">הֵמְיִיפּוֹס</a></div>","alt":[]},"8069":{"h":"הֲמִיצְתָּא","r":"E00616","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִימּוּצָתָא\">חִימוּצָתָא</a></div>","alt":[]},"8070":{"h":"המירום","r":"E00617","html":"<div class=\"sense\">, v. next. w.</div>","alt":["המירוס"]},"8071":{"h":"הֲמִירָם","r":"E00618","html":"<div class=\"sense\"> (prob.) pr. n. m. <i>Hămiram</i>, a person from whom certain secular books are named: <span dir=\"rtl\">ספרי ה׳</span> (cmp. <span dir=\"rtl\">בן סִירָא</span>, <span dir=\"rtl\">בן לַעֲנָה</span>, <span dir=\"rtl\">בן תַּגְלָא</span>). <span class=\"citation\">Yad. IV, 6</span> (comment. <a href=\"#\" data-headword=\"מִירָם\">מִירָס</a>, <a href=\"#\" data-headword=\"מִירָם\">מִירָם</a>); <span class=\"citation\">Y. Snh. X, 28ᵃ</span> top <span dir=\"rtl\">ספרי ה׳</span> (contrad. to <span dir=\"rtl\">ספרים החיצונים</span>). <span class=\"citation\">Ḥull. 60ᵇ</span> worth to be burnt <span dir=\"rtl\">כספרי מירון</span> Ar. ed. Koh. s. v. <a href=\"#\" data-headword=\"מרום\">מרום</a> (Var. <a href=\"#\" data-headword=\"מֵרוֹן\">מרון</a>, <a href=\"#\" data-headword=\"המירום\">המירוס</a>, missing in ed.). [Conjectures: <i>Homeros</i> (Homer); Ἡμερησία (βίβλια) <i>diaries;</i> symbolical name = ‘the Lord remove them’. V. Koh. Ar. Compl. s. v. <a href=\"#\" data-headword=\"מרום\">מרום</a>.]</div>","alt":[]},"8072":{"h":"המירס","r":"E00619","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲמִירָם\">preced.</a></div>","alt":[]},"8073":{"h":"הַמְלְטָא","r":"E00620","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*הִימְלְטָא\">הִימְלְכָא</a></div>","alt":[]},"8074":{"h":"הֲמַלְתָּא","r":"E00621","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִימַלְתָּא\">הִימַלְתָּא</a></div>","alt":[]},"8075":{"h":"הָמַם","r":"E00622","html":"<div class=\"sense\"><b>1)</b> <i>to confound</i>. Tanḥ. Vayera 22 הֲמָמוֹ והלך וכ׳ He confounded him (took him by surprise), and thus he (Abraham) went to sacrifice his son; <span class=\"citation\">Gen. R. s. 55</span>.—Mekh. B’shall. s. 5 (ref. to <span class=\"citation\">Ex. XIV, 24</span>) <span dir=\"rtl\">הֲמָמָן ערבבן</span> He confounded them, He brought confusion into their ranks; ib. s. 2; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to stir up, sweep</i> (v. <a href=\"#\" data-headword=\"הֲמַם I\">next w.</a>). Lam. R. introd. (R. Abbahu 2) (expl. <a href=\"#\" data-headword=\"כָּבֵד I\">הכביד</a>, <span class=\"citation\">Is. VIII, 23</span>, and ref. to <span class=\"citation\">Targ. Is. XIV, 23</span>) <span dir=\"rtl\">הֲמָמָם כבמכביד</span> he swept them as with a broom (<span class=\"citation\">Num. R. s. 23</span>, end, a. e. <span dir=\"rtl\">הכבידן</span>, v. <a href=\"#\" data-headword=\"כָּבֵד I\">כָּבַד</a>); <span class=\"citation\">Yalk. Is. 282</span> <span dir=\"rtl\">ה׳ במכבד</span>. [<a href=\"#\" data-headword=\"הוּמָם\">הוּמָם</a>, denom. of <a href=\"#\" data-headword=\"מוּם\">מוּם</a> q. v.]</div>","alt":[]},"8076":{"h":"הֲמַם I","r":"E00623","html":"<div class=\"sense\">; <i>Pa</i>. <a href=\"#\" data-headword=\"הָמַם\">הַמֵּם</a>, or <i>Af</i>. <span dir=\"rtl\">אַהֲמֵם</span> <i>to sweep</i>. <span class=\"citation\">Targ. Is. XIV, 23</span> (h. text <span dir=\"rtl\">טאטא</span>).</div>","alt":[]},"8077":{"h":"הֲמַם II","r":"E00624","html":"<div class=\"sense\"><i>Ithpa.</i> <span dir=\"rtl\">אִתְהָמַם</span> (denom. of <a href=\"#\" data-headword=\"מוּם\">מוּם</a>) <i>to mutilate one’s self</i> (h. <a href=\"#\" data-headword=\"גָּדַד I\">הִתְגּוֹדֵד</a>). <span class=\"citation\">Targ. O. Deut. XIV, 1</span> (ed. Berl. <span dir=\"rtl\">תתח׳</span>, v. Berl. Massor. p. 90). <span class=\"citation\">Targ. I Kings XVIII, 28</span> Kimḥi (some ed. <span dir=\"rtl\">אתח׳</span>); a. e.—Part. <span dir=\"rtl\">מִתְהָמַם</span> <i>mutilated</i>. <span class=\"citation\">Targ. Jer. XLI, 5</span>; <span class=\"citation\">XLVIII, 37</span> (some ed. <span dir=\"rtl\">מתח׳</span>).</div>","alt":[]},"8078":{"h":"הֲמָמָא","r":"E00625","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, constr. <span dir=\"rtl\">הַמְמַת</span> (הֲמַם I) <i>sweepings, refuse</i>. <span class=\"citation\">Targ. Amos VIII, 6</span> <span dir=\"rtl\">הממת</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">מֵהַ׳</span>, h. text <span dir=\"rtl\">מַפַּל</span>).</div>","alt":[]},"8079":{"h":"הֲמָמָה","r":"E00626","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָמַם\">המם</a>) <i>confusion, perplexity</i>. Mekh. B’shall. s. 5 <span dir=\"rtl\">אין ה׳ אלא מגפה</span> the word <i>hamam</i> (<span class=\"citation\">Ex. XIV, 24</span>) means pestilence.</div>","alt":[]},"8080":{"h":"הָמָן","r":"E00627","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Haman</i>. <span class=\"citation\">Snh. 61ᵃ</span> <span dir=\"rtl\">נעבד כה׳</span> worshipped as H. wanted to be. <span class=\"citation\">Ḥull. 139ᵇ</span> <span dir=\"rtl\">ה׳ מן התורה מנין</span> where is Haman alluded to in the Pentateuch?—<span class=\"citation\">Meg. 10ᵇ</span> <span dir=\"rtl\">ה׳ הרשע</span>; a. fr.</div>","alt":[]},"8081":{"h":"הִמְנוֹן","r":"E00628","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִימְנוֹן\">הִימְנוֹן</a></div>","alt":[]},"8082":{"h":"המנוכא","r":"E00629","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַמְנִיכָא\">הַמְנִיכָא</a></div>","alt":[]},"8083":{"h":"הַמְנוּנָא","r":"E00630","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Hamnuna</i>, name of several Amoraim. <span class=\"citation\">Y. Taan. IV, 68ᵃ</span> רב ה׳ דבבל R. H. of Babylonia.—<span class=\"citation\">Y. Hor. III, 47ᶜ</span> top. <span class=\"citation\">Shebu. 34ᵇ</span>; a. fr.—Y. B. Bath. VI, end, 15ᶜ רב ה׳ ספרא R. H., the scribe.</div>","alt":[]},"8084":{"h":"הַמְנִיכָא","r":"E00631","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מני\">מני</a>, with format. <a href=\"#\" data-headword=\"כ\">ך</a>, cmp. <a href=\"#\" data-headword=\"בָּזִיךְ\">בָּזִיךְ</a>) [<i>emblem of appointment to office</i>,] <i>necklace.</i> <span class=\"citation\">Dan. V, 7</span>, a. e. (Kethib: <a href=\"#\" data-headword=\"המנוכא\">המנוכא</a>, <span dir=\"rtl\">המינכא</span>).—<span class=\"citation\">Targ. Prov. I, 9</span> (some ed. <span dir=\"rtl\">המניכה</span>).—Pl. <span dir=\"rtl\">הַמְנִיכִין</span>. <span class=\"citation\">Targ. Esth. II, 9</span>.—V. <a href=\"#\" data-headword=\"מָנִיכָא\">מְנִיכָא</a>. [Greek transformation μανιάκης, fr. which <a href=\"#\" data-headword=\"מוּנְיָיק\">מוּנְיָיק</a>.]</div>","alt":[]},"8085":{"h":"*הַמְנֵיק","r":"E00632","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a sort of spoon</i> or <i>fork</i>, with one end pointed and the other broad (similar to the <i>cochlear</i>, v. <a href=\"#\" data-headword=\"כּוֹכְלִיאָר\">כּוֹכְלִיאָר</a>). <span class=\"citation\">B. Mets. 25ᵇ</span> <span dir=\"rtl\">סכיני וה׳</span> (Ms. R. <span dir=\"rtl\">המנק</span>) knives and fork (which may have been cast on the dunghill inadvertently). <span class=\"citation\">Succ. 32ᵃ</span> <span dir=\"rtl\">דעביד כהימנק</span> (Ms. M. <span dir=\"rtl\">והוא דעביד לה כי הימניק</span>) when the palm-branch is formed like a <i>himnek</i> (Rashi: like the top of the stylus).</div>","alt":["הִימְ׳"]},"8086":{"h":"המסי","r":"E00633","html":"<div class=\"sense\">, <i>Ithp</i>. <span dir=\"rtl\">אִתְהַמְסִי</span>, v. <a href=\"#\" data-headword=\"מְסִבְּתָא\">מְסִי</a>.</div>","alt":[]},"8087":{"h":"הֶמְסֵיסָא","r":"E00634","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶמְסֵסָא\">הֶמְסֵסָא</a></div>","alt":[]},"8088":{"h":"הֲמַסְמָסָה","r":"E00635","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִסְמֵס I\">מִסְמֵס</a>) <i>melting, softening</i> of the brain or spinal column. <span class=\"citation\">Ḥull. 45ᵇ</span> <span dir=\"rtl\">איזוהי … ואיזוהי ה׳</span> which (of the defects) is <i>hamrakhah</i>, and which <i>hămas-masah?</i> Answ. <span dir=\"rtl\">מַסְמָסָה כל שאינו יכול לעמוד וכ׳</span> when the column does not remain upright (when held in the hand). <span class=\"citation\">Ib. 53ᵇ</span> המ׳ <i>decayed flesh</i></div>","alt":["מַסְמָסָה"]},"8089":{"h":"הֶמְסֵס","r":"E00636","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָסַס\">מָסַס</a>) [<i>the dissolving</i> (<i>digesting</i>) <i>receptacle</i>,] <i>the first stomach of ruminants</i>, cmp. <a href=\"#\" data-headword=\"הַבְלִילָא\">הַבְלִילָא</a>. <span class=\"citation\">Ḥull. III, 1</span> <a href=\"#\" data-headword=\"הֶמְסֵס\">המסס</a> (= <span dir=\"rtl\">הַהֶ׳</span>, or <a href=\"#\" data-headword=\"הֶמְסֵס\">הַמָּסָס</a>). <span class=\"citation\">Lev. R. s. 4</span>; <span class=\"citation\">Midr. Till. to Ps. CIII</span>, beg. <span dir=\"rtl\">המ׳ לטחון</span> the first stomach has the function of grinding (the food). <span class=\"citation\">Lev. R. s. 18</span>; <span class=\"citation\">Koh. R. to XII, 3</span> ‘the grinders’ (ib.) <span dir=\"rtl\">זו ה׳</span> that is the stomach. [From later usage, e.g. Tur Yoré Deah 49, and from its Chald. equivalent it would seem that our w. is <a href=\"#\" data-headword=\"הֶמְסֵס\">הֶמְסֵס</a>, and the definite article fused with the <a href=\"#\" data-headword=\"ה\">ה</a> of the noun.]</div>","alt":["מָסָס"]},"8090":{"h":"הֶמְסֵסָא","r":"E00637","html":"<div class=\"sense\"><span class=\"citation\">Lev. R. s. 3</span>; <span class=\"citation\">Koh. R. to VII, 19</span> <span dir=\"rtl\">המסי׳</span>; <span class=\"citation\">Yalk. Koh. 976</span> <span dir=\"rtl\">המסס׳</span>.</div>","alt":["הֶמְסֵיסָא"]},"8091":{"h":"הַמְעִיסָה","r":"E00638","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְעִיסָה\">מְעִיסָה</a></div>","alt":["הַמְעָסָה"]},"8092":{"h":"*הֲמַר","r":"E00639","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> constr. (<a href=\"#\" data-headword=\"מוּר I\">מור</a>) <i>substitute</i>. <span class=\"citation\">Ḥull. 112ᵃ</span> Ar., ed. <span dir=\"rtl\">חמר</span>, v. <a href=\"#\" data-headword=\"חֲמַר III\"><span dir=\"rtl\">חַמְרָא</span> I</a>.</div>","alt":[]},"8093":{"h":"הַמְרָאָה I","r":"E00640","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מרי I) <i>stuffing food down the throat of an animal</i>. <span class=\"citation\">Sabb. 155ᵇ</span>, v. <a href=\"#\" data-headword=\"הַלְעָטָה\">הַלְעָטָה</a>.</div>","alt":[]},"8094":{"h":"הַמְרָאָה II","r":"E00641","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מרי II) <i>rebelliousness, rebellion; contempt of court</i>, v. <a href=\"#\" data-headword=\"מַמְרֵא II\"><span dir=\"rtl\">מַמְרֵא</span> II</a>. <span class=\"citation\">Snh. 16ᵃ</span> <span dir=\"rtl\">מהַמְרָאָתוֹ</span> from the Scriptural text treating of his (the elder’s) rebellion. <span class=\"citation\">Ib. 14ᵇ</span> <span dir=\"rtl\">המראתו ה׳</span> his rebellion is legally punishable; a. fr.—Pl. <span dir=\"rtl\">הַמְרָיוֹת</span>. <span class=\"citation\">Midr. Till. to Ps. CVI, 7</span>; <span class=\"citation\">Yalk. ib. 864</span> <span dir=\"rtl\">שתי ה׳ המרו וכ׳</span> they rebelled twice.</div>","alt":["הַמְרָיָה"]},"8095":{"h":"הֲמָרָה","r":"E00642","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּר I\">מור</a>) <i>change</i>, <span dir=\"rtl\">הֲמָרַת הַדָּת</span>, <i>change of religion, apostasy</i>. <span class=\"citation\">Pes. 96ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"מְשׁוּמָּדוּת\">משומדות</a>); <span class=\"citation\">Yeb. 71ᵃ</span> top.</div>","alt":[]},"8096":{"h":"הַמְרָיָה","r":"E00643","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַמְרָאָה II\"><span dir=\"rtl\">הַמְרָאָה</span> II</a></div>","alt":[]},"8097":{"h":"הַמְרָכָה","r":"E00644","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָאַךְ\">מָיַךְ</a>) <i>softening</i> of the brain or the spinal column into a liquid state, contrad. to <a href=\"#\" data-headword=\"הֲמַסְמָסָה\">הֲמַסְמָסָה</a>, into a cohesive, pulpy substance. <span class=\"citation\">Ḥull. 45ᵇ</span></div>","alt":[]},"8098":{"h":"הַמְשָׁכָה","r":"E00645","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשַׁךְ I\">מָשַׁךְ</a>) <i>conducting water through a channel</i>. <span class=\"citation\">Tem. 12ᵇ</span></div>","alt":[]},"8099":{"h":"הַמְתָא","r":"E00646","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Hamtha</i>. Targ. O. a. Y. I <span class=\"citation\">Gen. XIV, 5</span> (h. text <a href=\"#\" data-headword=\"הֵם\">הָם</a>).</div>","alt":["(הֶמְתָּא)"]},"8100":{"h":"המתגרה","r":"E00647","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to III, 14</span>, read: <span dir=\"rtl\">חֲמַת גֶּדֶר</span>.</div>","alt":[]},"8101":{"h":"הֵן","r":"E00648","html":"<div class=\"sense\"><i>they</i>, pl. of <a href=\"#\" data-headword=\"הוּא\">הוּא</a>, <a href=\"#\" data-headword=\"הִיא\">הִיא</a>.</div>","alt":[]},"8102":{"h":"הֵן ²","r":"E00649","html":"<div class=\"sense\"> (b. h. <a href=\"#\" data-headword=\"הֵן\">הֵן</a>) </div><div class=\"sense\"><b>1)</b> <i>here is, behold</i>. <a href=\"#\" data-headword=\"הִינָּם I\">הִינָּם</a>, <a href=\"#\" data-headword=\"הִינוּן\">הִינָּן</a> <i>behold, they are</i>. <span class=\"citation\">Ned. V, 6</span> (<span class=\"citation\">48ᵃ</span>) <span dir=\"rtl\">והי׳ לפניך אלא וכ׳</span> Bab. ed. (Mish. <span dir=\"rtl\">ואינן</span>; Y. ed. <span dir=\"rtl\">והן בפניך עד</span></div><div class=\"sense\"><b>—2)</b>  (introducing a question or exclamation) <i>how?, indeed!</i> <span class=\"citation\">Y. Shek. I, 45ᵈ</span> bot. <span dir=\"rtl\">הן נקרא ולא וכ׳</span> can we, indeed, read this and not feel ashamed? (Bab. ed. <span dir=\"rtl\">הניקרא</span>, marginal correct. Ms. M. <span dir=\"rtl\">הן נק׳</span>).</div><div class=\"sense\"><b>—3)</b> <i>if.</i> <span class=\"citation\">Dan. II, 5</span>, sq.; a. fr.—<span dir=\"rtl\">הן</span>—הן <i>whether</i>—<i>or.</i> <span class=\"citation\">Ezra VII, 26</span>.—<span class=\"citation\">B. Bath. VII, 2</span> <span dir=\"rtl\">הן חסר הן יתר</span> whether it be less (than a Beth Kor) or more. <span class=\"citation\">Ib. 3</span>; a. e.</div><div class=\"sense\"><b>—4)</b> <i>yes</i> (cmp. <a href=\"#\" data-headword=\"אִין I\"><span dir=\"rtl\">אִין</span> I</a>). <span class=\"citation\">B. Mets. 49ᵃ</span>, v. <a href=\"#\" data-headword=\"*הִין I\">הִין</a> II Mekh. Yithro s. 4 answer <span dir=\"rtl\">על לאו לאו ועל הן הן</span> <i>no</i> to a prohibition and <i>yes</i> to a positive command. Ib. s. 5 <span dir=\"rtl\">ה׳ וה׳</span> yes, indeed; a fr.—<span class=\"citation\">Ned. 11ᵃ</span>, a. fr. <span dir=\"rtl\">מכלל לאו אתה שומע הן</span> from the negative we derive the affirmative by implication; Y. ib. I, end, 37ᵃ, a. e. <span dir=\"rtl\">ממשמע לאו וכ׳</span>. <span class=\"citation\">Men. X, 3</span> (<span class=\"citation\">65ᵃ</span>).</div>","alt":["הֵין"]},"8103":{"h":"הָן","r":"E00650","html":"<div class=\"sense\"><b>1)</b>  ה׳ ד־ <i>he who</i>. <span class=\"citation\">Targ. Prov. XIX, 1</span>, a. fr. in Ms., ed. Lag. <a href=\"#\" data-headword=\"הֲווֹ\">הֲווֹ</a> q. v.—Pesik. Aḥaré, p. 169ᵇ, v. <a href=\"#\" data-headword=\"דְּחוּכָא\">דְּחוּכָא</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>this one, that one</i>. <span class=\"citation\">Y. Meg. I, 72ᵃ</span> <span dir=\"rtl\">היך … להן וכ׳</span> (<span class=\"citation\">Y. Succ. III, 54ᵃ</span> top <span dir=\"rtl\">לדין</span>), v. <a href=\"#\" data-headword=\"הֵיךְ\">הֵיךְ</a>. <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> top [read:] <span dir=\"rtl\">מה הן שאל להן וכ׳</span>; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> top <span dir=\"rtl\">מה הין דשאיל להון</span> (corr. acc.) from all that this one asked that one &amp;c.; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>what?</i> Y. B. Mets. II, 8ᶜ <a href=\"#\" data-headword=\"לָהֵן\">לְהָן</a>, v. <a href=\"#\" data-headword=\"אֲהָן\">אֲהָן</a>.</div><div class=\"sense\"><b>—4)</b> <i>where</i> (relat.), <i>where?</i> <span class=\"citation\">Esth. R. to I, 12</span> [read:] <span dir=\"rtl\">הן דליסטאה מקפח וכ׳</span> where the robber waylays, there he is executed. <span class=\"citation\">Y. Snh. I, 19ᵃ</span> top; <span class=\"citation\">Y. Ned. VI, 40ᵃ</span> bot. <span dir=\"rtl\">הן דמטא מטא</span> where he came to, he came to (and his order was obeyed). <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot. [read:] <span dir=\"rtl\">להן דאשתלחית מינסבינן</span> to the place whither I was sent to take them; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> <span dir=\"rtl\">להון דשלחית</span> (read <span dir=\"rtl\">דאשתלחית</span>). <span class=\"citation\">Gen. R. s. 78</span>, v. <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a>. <span class=\"citation\">Y. Ber. II, 5ᶜ</span> bot. <span dir=\"rtl\">להן ייזיל</span> whither shall he go? Ib. II, 5ᵃ top <span dir=\"rtl\">מן הן הוא</span> where is he from?; a. fr.—Pl. <a href=\"#\" data-headword=\"הַנְהוּ\">הַנְהוּ</a>, <span dir=\"rtl\">הַנֵּי</span>, <a href=\"#\" data-headword=\"הַנָּךְ\">הַנָּךְ</a> <i>those, these.</i> <span class=\"citation\">Targ. Esth. I, 10</span>; a. e.—<span class=\"citation\">Tam. 32ᵇ</span>. <span class=\"citation\">B. Mets. 117ᵃ</span>, v. <a href=\"#\" data-headword=\"הַהוּא\">הַהוּא</a>.—<span class=\"citation\">Gitt. 6ᵃ</span> <span dir=\"rtl\">הנך … דהני והני בדהנך וכ׳</span> those (the inhabitants of Ctesiphon) know the signatures of these (of Ardshir), but the latter do not know &amp;c. <span class=\"citation\">Bets. 10ᵇ</span>; a. v. fr.—*<i>Fem. </i> pl. <a href=\"#\" data-headword=\"הַנָּן\">הַנָּן</a>. <span class=\"citation\">Y. Bets. V, 63ᵇ</span> top <span dir=\"rtl\">רבנין … מפרשין לה׳</span> the Rabbis of Cæsarea report these (controversies) more explicitly (stating the opinion of each by name; <span class=\"citation\">Y. Pes. VIII, 36ᵃ</span> top <span dir=\"rtl\">מפרשין להון</span>).—<span dir=\"rtl\">הני מילי</span> (abbrev. <span dir=\"rtl\">הנ&quot;מ</span>) these words (have been said), i.e. <i>this is the case only</i> &amp;c. <span class=\"citation\">Ber. 21ᵃ</span> bot. (<span dir=\"rtl\">הוה אמינא</span>) <span dir=\"rtl\">הנ&quot;מ יחיד ויחיד</span> I might have thought this refers only to &amp;c.—<span class=\"citation\">Ib. 15ᵃ</span> <span dir=\"rtl\">והנ&quot;מ לק&quot;ש</span> but this applies only to &amp;c.; a. v. fr.—<span dir=\"rtl\">מנא הני מילי</span>, v. <a href=\"#\" data-headword=\"מְנָא II\"><span dir=\"rtl\">מְנָא</span> II</a>.—Emphatic. <span dir=\"rtl\">הַנָּא</span>, <a href=\"#\" data-headword=\"הַנָּה\">הַנָּה</a>. <span class=\"citation\">Gen. R. s. 87</span> <span dir=\"rtl\">הנה טבא וכ׳</span> is this (slave) good? Is the omen favorable?; <span class=\"citation\">Yalk. ib. 145</span> <span dir=\"rtl\">הא טב וכ׳</span> (corr. acc.).</div>","alt":["(הוֹן)"]},"8104":{"h":"הֲנָא","r":"E00651","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲנִי\">הֲנִי</a></div>","alt":[]},"8105":{"h":"הֲנָאָה I","r":"E00652","html":"<div class=\"sense\"><i>enjoyment</i>, v. <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנָיָיה</a>.</div>","alt":[]},"8106":{"h":"הֲנָאָה II","r":"E00653","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"נוֹי\">נוא</a>, Hif. <span dir=\"rtl\">הֵנִיא</span>) <i>intervention, objection</i>. <span class=\"citation\">Sifré Num. 153</span> (ref. to <span dir=\"rtl\">הניא</span>, <span class=\"citation\">Num. XXX, 6</span>) <span dir=\"rtl\">ה׳ זו מה היא</span> what this ‘objection’ means; v. <a href=\"#\" data-headword=\"הֲפָרָה\">הֲפָרָה</a>.</div>","alt":[]},"8107":{"h":"הֵנַג","r":"E00654","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"הֵמַג\">הֵמַג</a>) <i>Bar-Henag</i>, surname of a species of <i>abrathah</i> <a href=\"#\" data-headword=\"אַבְרָתָא\">(אַבְרָתָה</a>). <span class=\"citation\">Sabb. 109ᵇ</span> (defin. h. <span dir=\"rtl\">אזוב יון</span>).—[Pl. <a href=\"#\" data-headword=\"נָגַב\">הִנְגִּין</a>, <a href=\"#\" data-headword=\"הִינְדְּוִוי\">הִינְ׳</a>, v. <a href=\"#\" data-headword=\"הֵיגְתָא\">הֵיגְתָא</a>.]</div>","alt":["הֵינַג","בַּר ה׳"]},"8108":{"h":"הִנְדָּאָה","r":"E00655","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִינְדָּוָא\">הִינְדְּוָאָה</a></div>","alt":[]},"8109":{"h":"הִנְדְּבִי","r":"E00656","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַנְטוּבִּין\">אַנְטוּבִּין</a></div>","alt":[]},"8110":{"h":"הִנְדְּוָאָה","r":"E00657","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִינְדְּוִוי\">הִינְ׳</a></div>","alt":["הִנְדְּוִוי","הִנְדְּוִי"]},"8111":{"h":"הַנְדֵּז","r":"E00658","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"הָדַס\">הָדַס</a>, <i>Pi</i>.) <i>to mark by means of incisions</i> (cmp. <a href=\"#\" data-headword=\"כָּסַס\">כָּסַס</a>). <span class=\"citation\">B. Bath. 89ᵇ</span> באתרא דמְהַנְדְּזֵי Ms. (ed. <span dir=\"rtl\">דמְהַנְדְּסֵי</span>) in a place where the authorities mark vessels used for measuring. <span class=\"citation\">Ib.</span> (<span dir=\"rtl\">כל</span>) <span dir=\"rtl\">כמה דלא מהנדזי לא שקיל</span> Ar. (Ms. H. <span dir=\"rtl\">כל כמה דלא חזי הינדזא</span>; ed. only <span dir=\"rtl\">לית לן בה</span>) what is beyond the mark of the vessel the purchaser will not accept (merely on the faith of the seller as to the quantity).</div><div class=\"sense\"><b>Ithpe. אִיהַנְדֵּז</b> <div class=\"sense\"><i>to be incised</i>. <span class=\"citation\">Ḥull. 43ᵃ</span> <span dir=\"rtl\">זימנין דמִיהַנְּדְּזִין וכ׳</span> at times (when the animal stretches its neck) the perforations in the two skins of the oesophagus may just exactly cover each other.</div></div>","alt":["הַנְדֵּס"]},"8112":{"h":"הַנְדְּזָא","r":"E00659","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הַנְדֵּז\">preced.</a>) <i>mark; calculation of proportions</i>. <span class=\"citation\">B. Bath. 89ᵇ</span>, v. <a href=\"#\" data-headword=\"הַנְדֵּז\">preced.</a> <span class=\"citation\">Gitt. 60ᵇ</span> <span dir=\"rtl\">ואשקי בה׳</span> and use the water in proportion (as much as is due to thy share). [Later Hebr. <span dir=\"rtl\">הַנְדָּסָה</span> <i>geometry</i>.]</div>","alt":["הִינְדְּזָא"]},"8113":{"h":"הנדיוסין","r":"E00660","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. XVII</span>; <span class=\"citation\">Yalk. Ps. 670</span>, read: <a href=\"#\" data-headword=\"קִירְיוֹסִים\">קיּרְיוֹסִין</a>; v. <a href=\"#\" data-headword=\"אַפֹּופְסִין\">אַפּוֹפְסִין</a></div>","alt":[]},"8114":{"h":"הנדוקא","r":"E00661","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִנְדְּקָא\">הִנְדְּקָא</a></div>","alt":[]},"8115":{"h":"הִנְדִּיקִי","r":"E00662","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִינְדִּיקִי\">הִינְדִּיקִי</a></div>","alt":[]},"8116":{"h":"הִנְדִּית","r":"E00663","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הִנְדִּיקִי\">preced.</a>) <i>Indian</i>. <span class=\"citation\">Midr. Till. to Ps. VI</span> <span dir=\"rtl\">חרב ה׳</span> an Indian sword.</div>","alt":[]},"8117":{"h":"הִנְדְּקָא","r":"E00664","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. <a href=\"#\" data-headword=\"הִנְדְּקָאֵי\">הִנְדְּקָאֵי</a> pl., v. <span dir=\"rtl\">הינ׳</span>) <i>Indian</i>. <span dir=\"rtl\">נהמא דה׳</span> <i>Indian bread</i>, a dough roasted on the spit and poured over with oil, or eggs and oil. <span class=\"citation\">Ber. 37ᵇ</span> (Asheri <span dir=\"rtl\">דהנדוקא</span>).</div>","alt":[]},"8118":{"h":"הִנְדְּקָאֵי","r":"E00665","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִינְדְּוִוי\">הִינְ׳</a></div>","alt":[]},"8119":{"h":"הִנְדְּקוֹקֵי","r":"E00666","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">דקק</span>, with prefixed <a href=\"#\" data-headword=\"ה\">ה</a> a. <a href=\"#\" data-headword=\"נ\">נ</a> inserted; corresp. to h. <a href=\"#\" data-headword=\"גַּדְגַּדְנִיּוֹת\">גַּדְגַּדְנִיּוֹת</a>) <i>melilot</i>, a kind of clover used as a relish.—<span class=\"citation\">Erub. 28ᵃ</span> ה׳ מדאי Median Melilot. Y. ib. III, 20ᵈ top; <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> top.</div>","alt":[]},"8120":{"h":"הַנָּה","r":"E00667","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הָן\">הָן</a></div>","alt":[]},"8121":{"h":"הִנֵּה","r":"E00668","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"הֵן\">הֵן</a>) <i>behold, here is</i>. <span class=\"citation\">Koh. R. to V, 6</span> <span dir=\"rtl\">ה׳ של בו&quot;ד</span> the ‘here is’ of a human being (<span class=\"citation\">Esth. VIII, 7</span>), <span dir=\"rtl\">ה׳ של הק&quot;בה</span> the ‘here is’ of the Lord (<span class=\"citation\">Zech. XIV, 1</span>).—<span dir=\"rtl\">הִנֵּנִי</span> here am I. <span class=\"citation\">Gen. R. s. 55</span> ה׳ לכהונה I am ready for priesthood; a. fr.</div>","alt":[]},"8122":{"h":"הָנָה","r":"E00669","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הני\">הני</a></div>","alt":[]},"8123":{"h":"הַנְהָגָה","r":"E00670","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָהַג\">נָהַג</a>) <i>driving</i> an animal, a form of taking possession. <span class=\"citation\">B. Mets. 9ᵃ</span>, v. <a href=\"#\" data-headword=\"מְשִׁיכָה\">מְשִׁיכָה</a>.</div>","alt":[]},"8124":{"h":"הַנְהוּ","r":"E00671","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הָן\">הָן</a></div>","alt":[]},"8125":{"h":"הֲנָחָה","r":"E00672","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rest, ease, relief</i>. <span class=\"citation\">Gen. R. s. 87</span>, beg. (ref. to <span class=\"citation\">Ps. CXXV, 3</span>) <span dir=\"rtl\">אין לו ה׳ וכ׳</span> finds no ease in the company of &amp;c.—הֲנָחַת רוח <i>peace of mind, appeasement</i>. Y. Dem. VII, beg. 26ᵃ (interch. with <span dir=\"rtl\">נחת רוח</span>). <span class=\"citation\">Y. Peah I, 15ᶜ</span> bot.; Y. Kidd. I, 61ᵃ bot. <span dir=\"rtl\">בעושה ה׳ רותו וכ׳</span> when he gives his father ease of mind (by obeying his wishes).</div>","alt":[]},"8126":{"h":"הַנָּחָה","r":"E00673","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (נוּחַ <i>Hif.</i>) <i>putting down, depositing, laying down</i> (v. <a href=\"#\" data-headword=\"הֵינוּחַ\">הֵינוּחַ</a>). <span class=\"citation\">Sabb. 22ᵇ</span>, sq. <span dir=\"rtl\">ה׳ עושה מצוה</span> the real religious ceremony consists in putting the lights in their appropriate place. <span class=\"citation\">Ib. 4ᵃ</span>, a. e. <span dir=\"rtl\">עקירה וה׳</span> the lifting up (of a burden on the Sabbath) and the putting down.—<span class=\"citation\">Kel. VIII, 8</span> <span dir=\"rtl\">מקום הַנָּחַת העצים</span> the place (in the oven) where the wood is placed. <span class=\"citation\">Ib. XXII, 1</span> <span dir=\"rtl\">מקום הנחת וכ׳</span> enough (left of the side board) to set down the cups; enough … to set down portions of meat; Y. Ab. Zar. II, end, 42ᵃ <span dir=\"rtl\">היא מקים ה׳ הכוסות וכ׳</span> (not <a href=\"#\" data-headword=\"תַּחַת\">תחת</a>) both terms mean the same. <span class=\"citation\">Taan. 2ᵇ</span>; <span class=\"citation\">4ᵃ</span> <span dir=\"rtl\">משעת הַנָּחָתוֹ</span> from the time it (the Lulab) is stored away (the seventh day of Succoth).</div>","alt":[]},"8127":{"h":"הַנֵּי","r":"E00674","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הָן\">הָן</a></div>","alt":[]},"8128":{"h":"הני","r":"E00675","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנָאָה</a>), <i>Nif</i>. <span dir=\"rtl\">נֶהֱנֶה</span> (= <a href=\"#\" data-headword=\"נֵאוֹת\">נֵאוֹת</a>, v. <a href=\"#\" data-headword=\"אוֹת I\"><span dir=\"rtl\">אוֹת</span> I</a>) </div><div class=\"sense\"><b>1)</b> <i>to be pleased, to enjoy, to profit</i>. <span class=\"citation\">B. Kam. 20ᵃ</span>, a. fr. <span dir=\"rtl\">זה נה׳</span> the one is benefitted &amp;c., opp. <a href=\"#\" data-headword=\"חָסֵר\">חָסֵר</a>. <span class=\"citation\">Ib. II, 2</span> <span dir=\"rtl\">משלם מה שנֶהֱנֵית</span> he must pay for what the animal has enjoyed (eaten or drunk), contrad. to <span dir=\"rtl\">מה שהזיקה</span> what she has damaged. <span class=\"citation\">Ber. 10ᵇ</span> <span dir=\"rtl\">הרוצה לֵהָנוֹת יהָנֶה וכ׳</span> (Rashi <span dir=\"rtl\">לֵיהָ׳</span>) he who desires to make use (of people’s hospitalities), may do so following the example of Elisha. <span class=\"citation\">R. Hash. 28ᵃ</span>, a. fr. <span dir=\"rtl\">מצות לא ליהנות ניתנו</span> religious ceremonies are not considered an enjoyment (as regards the use of sacred property &amp;c.); a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be enjoyed</i>. <span class=\"citation\">Ber. 35ᵃ</span> <span dir=\"rtl\">דבר שנ׳</span></div><div class=\"sense\"><b>Pi. הִנָּה</b> <div class=\"sense\"><i>to benefit, to entertain, to cause to share</i>. <span class=\"citation\">Snh. 92ᵃ</span> <span dir=\"rtl\">אינו מְהַנֶּה ת&quot;ח וכ׳</span> allows no scholar to share his wealth. <span class=\"citation\">Ber. 63ᵇ</span> bot. <span dir=\"rtl\">ומְהַנֵּהוּ וכ׳</span> and invites him to partake of his wealth. <span class=\"citation\">Yad. IV, 3</span> <span dir=\"rtl\">הרי אתה כמְהַנָּן וכ׳</span> you appear to benefit them pecuniarily, but &amp;c. <span class=\"citation\">Ab. Zar. 16ᵇ</span> sq. <span dir=\"rtl\">שמא דבר מינית … והִנָּאֲךָ</span> (v. Rabb. D. S. a. l. note 20) perhaps a heretical idea was communicated to thee and it pleased thee; <span class=\"citation\">Yalk. Prov. 937</span>; a. fr. [<span class=\"citation\">Snh. 102ᵇ</span> הֶהֱנָה <i>Hif.</i>, marginal note <span dir=\"rtl\">היה מְהַנֶּה</span>; v. <span class=\"citation\">Yalk. Kings 207</span>.]</div></div>","alt":["הָנָה"]},"8129":{"h":"הֲנִי","r":"E00676","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"הני\">preced.</a>) <i>to please, to profit</i>. <span class=\"citation\">Targ. Jer. XXXI, 25</span> <span dir=\"rtl\">הֲנַתְנִי</span> ed. Lag. (oth. ed. <span dir=\"rtl\">הֲנָאַתְנִי</span>). <span class=\"citation\">Targ. Is. XLIV, 10</span> <span dir=\"rtl\">לַהֲנָאָה</span> (h. text <a href=\"#\" data-headword=\"*יָעַל\">הוֹעִיל</a>); a. e.—<i>Part.</i> <span dir=\"rtl\">הָנֵי</span>. <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">עביד מה דה׳ לך</span> do what pleases thee.—Pl. <span dir=\"rtl\">הַנְיָין</span>. <span class=\"citation\">Gen. R. s. 3</span>; <span class=\"citation\">s. 9</span> <span dir=\"rtl\">דין ה׳ לי יתהון לא ה׳ לי</span> these (worlds) please me, those did not &amp;c.; <span class=\"citation\">Midr. Till. to Ps. XXXIV</span>; <span class=\"citation\">Koh. R. to III, 11</span>, v. <a href=\"#\" data-headword=\"דֵּן\">דֵּן</a>.</div><div class=\"sense\"><b>Af. אַהֲנִי</b> <div class=\"sense\"><b>1)</b> <i>to please, do good, benefit</i>. Targ. <span class=\"citation\">Hab. II, 18</span>; a. fr.—<span class=\"citation\">Snh. 99ᵇ</span> bot. <span dir=\"rtl\">מאי אַהֲנוּ לן רבנן</span> (not <a href=\"#\" data-headword=\"הֲנִי\">אהני</a>) what good have the Rabbis done us? <span class=\"citation\">Ab. Zar. 14ᵇ</span> אַהֲנָאִי לכון וכ׳ I did you good inasmuch &amp;c. Y. Ber. I, 4ᵇ bot. <span dir=\"rtl\">ומה מְהַנְיָא ליה</span> (ed. Krot. <span dir=\"rtl\">ומה</span> missing) what good will it do him?; Y. M. Kat. III, 83ᶜ bot. <span dir=\"rtl\">ומה אנים ליה</span> (corr. acc.); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to take effect, be legal</i>. <span class=\"citation\">Tem. 4ᵇ</span> <span dir=\"rtl\">אי עביד מַהֲנֵי</span> if (what the law forbids) has been done, the act has its legal effect. <span class=\"citation\">Ber. 43ᵃ</span> <span dir=\"rtl\">מְהַנְיָא ליה הסבה</span> the lying down of a company for a meal has an influence (in that one says the benediction in behalf of all); a. fr.</div></div><div class=\"sense\"><b>Ithpe. אִתְהֲנֵי</b> </div><div class=\"sense\"><b>Ithpa. אִתְהַנֵּי</b> <div class=\"sense\"><i>to profit, enjoy, be gratified</i>. <span class=\"citation\">Targ. Y. Deut. I, 6</span> <span dir=\"rtl\">א׳ לכון</span> it benefitted you (v. <span class=\"citation\">Sifré Deut. 5</span>). <span class=\"citation\">Targ. O. Gen. XXXVII, 26</span>.—<span class=\"citation\">Targ. II Sam. XVII, 16</span> <span dir=\"rtl\">דלמא יִתְהֲנִי וכ׳</span> (ed. Wil. <span dir=\"rtl\">יִתַּהֲנִי</span>) perhaps it will please the king (h. text <span dir=\"rtl\">יְבֻלַּע</span>). <span class=\"citation\">Targ. Ez. XVI, 31</span>; a. e.—<span class=\"citation\">Ned. 50ᵃ</span> <span dir=\"rtl\">דאִיתְהֲנִי וכ׳</span> that I should enjoy this world’s goods. <span class=\"citation\">Ḥag. 15ᵃ</span> <span dir=\"rtl\">לִיתְהֲנֵי וכ׳</span> let him (myself) enjoy the world. <span class=\"citation\">Yeb. 103ᵃ</span> <span dir=\"rtl\">מִתְהַנְיָא מעבירה</span> she derived gratification from a sinful act. Y. Snh. X, 29ᵇ top <span dir=\"rtl\">ובר נש לא מִתְהֲנֵי כלום</span> (not <span dir=\"rtl\">מתהנים</span>) and none were benefitted; a. fr.</div></div>","alt":["הֲנָא"]},"8130":{"h":"הֲנָיָיא","r":"E00677","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנָיָיה</a> ch.</div>","alt":[]},"8131":{"h":"הֲנָיָיה","r":"E00678","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"נֵאוֹת\">נֵאוֹת</a>, v. <a href=\"#\" data-headword=\"אוֹת I\"><span dir=\"rtl\">אוֹת</span> I</a>; cmp. <a href=\"#\" data-headword=\"נָאֶה\">נָאֶה</a>) <i>enjoyment, pleasure, benefit</i>. <span class=\"citation\">Taan. 8ᵃ</span> <span dir=\"rtl\">מאי ה׳ יש לך</span> what does it profit thee (to bite)?—<span class=\"citation\">Sifré Deut. 5</span> (ref. to <a href=\"#\" data-headword=\"רַב\">רב</a>, <span class=\"citation\">Deut. I, 6</span>) <span dir=\"rtl\">ה׳ גדולה וכ׳</span> your dwelling &amp;c. was of great benefit to you; a. v. fr.—<span class=\"citation\">Snh. 26ᵇ</span>, a. fr. <span dir=\"rtl\">בעל ה׳</span> <i>a worldling</i>.—<span dir=\"rtl\">נדר ה׳ מן</span> to vow refusal of any benefit or favor from a person. <span class=\"citation\">Ned. IV, 1</span>, sq.; a. fr.—<span class=\"citation\">Kidd. 41ᵃ</span> <span dir=\"rtl\">דור ה׳ ממנו</span> vow that you will have no favor at his hands. [Sifra B’har ch. III, Par. 3 <span dir=\"rtl\">הניית</span>, v. <a href=\"#\" data-headword=\"הוֹנָיָיה\">הוֹנָיָיה</a>.]</div>","alt":["הֲנָאָה"]},"8132":{"h":"הֲנָיָיה ²","r":"E00679","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. XVI, 19</span>. <span class=\"citation\">Targ. Koh. II, 2</span>; <span class=\"citation\">12</span>.—<span class=\"citation\">Targ. Y. Lev. V, 16</span> <span dir=\"rtl\">הַנְיַית קודשא</span> enjoyment of sacred property. <span class=\"citation\">Targ. Y. Gen. XXXVII, 26</span>; a. fr.—<span class=\"citation\">Ex. R. s. 6</span>, end; Tanḥ. Vaëra 2 (prov.) <span dir=\"rtl\">מן שטייא לית הנייא וכ׳</span> of acacias there is no profit except you cut them down, i.e. a wicked man can be converted by suffering only.—<span class=\"citation\">Taan. 23ᵇ</span> מקרבא הַנְיָיתָהּ Rashi (ed. <a href=\"#\" data-headword=\"הַנְיְיתָא\">הנייתא</a>) what good she does is a direct one (by giving bread); <span dir=\"rtl\">ואנא … ולא מקרבא הנייתיה</span> (read: <span dir=\"rtl\">הַנְיָיתִי</span>) but I give money, and what good I do is indirect; <span class=\"citation\">Keth. 67ᵇ</span> <span dir=\"rtl\">ומקרבן אהנייתי</span> (read: <span dir=\"rtl\">ומקרבא הַנְיָיתִי</span>, or <span dir=\"rtl\">ומקרבן הֲנָיָיתַי</span>, pl.).—Y. B. Bath. V, 16ᵇ bot. <span dir=\"rtl\">בנוי דה׳</span> (cmp. <a href=\"#\" data-headword=\"מַעֲלֵי\">מַעֲלֵי</a>) good, worthy children.—2) <i>loveliness, beauty</i> (cmp. <a href=\"#\" data-headword=\"נָאֶה\">נָאֶה</a>). <span class=\"citation\">Targ. Ps. XXIII, 2</span> <span dir=\"rtl\">הַנְיַית דיתאין</span> loveliness of plants (h. text <a href=\"#\" data-headword=\"נֵאוֹת\">נְאוֹת</a>!).</div>","alt":["הֲנייא","הֲנָאָה"]},"8133":{"h":"הַנְיְיתָא","r":"E00680","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲנָיָיה ²\">preced.</a></div>","alt":[]},"8134":{"h":"הֲנִיפָה","r":"E00681","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲנָפָה\">הֲנָפָה</a></div>","alt":[]},"8135":{"h":"הַנֵּיץ","r":"E00682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַנֵּץ\">הַנֵּץ</a></div>","alt":[]},"8136":{"h":"הַנְיָת","r":"E00683","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנָיָיה</a> ch.</div>","alt":[]},"8137":{"h":"הַנָּךְ","r":"E00684","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הָן\">הָן</a></div>","alt":[]},"8138":{"h":"הַנְכָּיָה","r":"E00685","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נכי\">נכי</a>) <i>deduction, diminution</i>. <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot.; <span class=\"citation\">Y. Sot. V, 20ᶜ</span> bot. [read:] <span dir=\"rtl\">פרוש מן הנ׳ מן מאי דאית לי אנא מנכי עביד מצוה</span> a Pharisee ‘from deduction’ (who says), I take from what is mine (I stint myself) in order to do a good deed.</div>","alt":[]},"8139":{"h":"הִנָּם","r":"E00686","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (homiletically = <a href=\"#\" data-headword=\"חִנָּם\">חִנָּם</a>; v. <a href=\"#\" data-headword=\"ה\">ה&quot;א</a>) <i>gratuitous, purposeless act, vanity</i>. <span class=\"citation\">Erub. 19ᵃ</span> (play on <a href=\"#\" data-headword=\"גֵּיהִינָּם\">גיהנם</a>) <span dir=\"rtl\">גיא … שהכל יורדין בה על עסקי ה׳</span> (v. Rabb. D. S. a. l. note 50) the valley which all enter for affairs of vanity (worldly lusts).</div>","alt":[]},"8140":{"h":"הַנָּן","r":"E00687","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הָן\">הָן</a></div>","alt":[]},"8141":{"h":"הָנֵף","r":"E00688","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"נוּף\">נוּף</a>) <i>waving ceremony</i> in the Temple.—<span dir=\"rtl\">יום ה׳</span> (<span class=\"citation\">Lev. XXIII, 10—12</span>) <i>the second day of Passover</i>. <span class=\"citation\">R. Hash. IV, 3</span>; <span class=\"citation\">Succ. III, 12</span>; <span class=\"citation\">Y. Ḥall. I, 57ᶜ</span> top; a. e.—<span class=\"citation\">Tosef. Arakh. I, 11</span> <span dir=\"rtl\">ביום ה׳</span> on the same week-day as the second day of Passover; <span class=\"citation\">Arakh. 9ᵇ</span>; v. <a href=\"#\" data-headword=\"עִיבּוּר\">עִיבּוּר</a>.</div>","alt":[]},"8142":{"h":"הֲנָפָה","r":"E00689","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"הָנֵף\">same</a>; <i>brandishing, swinging</i>. <span class=\"citation\">Pesik. R. s. 41</span> (ref. to <span dir=\"rtl\">יפה נוף</span> <span class=\"citation\">Ps. XLVIII, 3</span>) <span dir=\"rtl\">היפה בהֲנָפַת העומר שלה</span> who is beautiful when she waves the Omer; <span class=\"citation\">Yalk. Ps. 755</span>; <span class=\"citation\">Yalk. Ex. 417</span> <span dir=\"rtl\">בהֲנִיפָתָהּ</span>.—<span class=\"citation\">Y. Maasr. II, 50ᵃ</span> top <span dir=\"rtl\">הֲנָפַת מגל</span> the swinging of the sickle.</div>","alt":[]},"8143":{"h":"הֶנְפֵּק","r":"E00690","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נפק</span>) <i>producing</i> before court, esp. <i>the legal endorsement of a note, stating that it has been produced in court and found valid</i>. <span class=\"citation\">B. Mets. 7ᵇ</span>; <span class=\"citation\">16ᵇ</span>; a. e.</div>","alt":[]},"8144":{"h":"הַנֵּץ","r":"E00691","html":"<div class=\"sense\"> [<i>the blossom</i>,] name of <i>a coin;</i> pl. (through false analogy, v. ) <a href=\"#\" data-headword=\"הִינְצִין\">הִנְצִין</a>, <a href=\"#\" data-headword=\"הִינְצִין\">הִינְצִין</a>. <span class=\"citation\">Tosef. B. Bath. V</span>, 12ᵃ; <span class=\"citation\">Kidd. 12ᵃ</span>, v. <a href=\"#\" data-headword=\"נֵץ\">נֵץ</a>.</div>","alt":["הַנֵּיץ"]},"8145":{"h":"הָנֵץ","r":"E00692","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"נָצַץ\">נָצַץ</a>) <i>sparkling</i>, <span dir=\"rtl\">ה׳ החמה</span> <i>the first sparklings of the rising sun</i>. <span class=\"citation\">Taan. III, 9</span>. <span class=\"citation\">Ber. I, 2</span>; a. fr.</div>","alt":[]},"8146":{"h":"הֲנָצָה","r":"E00693","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נוץ</span>, v. <a href=\"#\" data-headword=\"הָנֵץ\">preced.</a>) <i>sprouting forth</i>. <span class=\"citation\">Men. 69ᵃ</span> <span dir=\"rtl\">שתי … ה׳ שריין וכ׳</span> (Rashi) does the offering of the two loaves cause the permission to use plants which had sprouted forth at the time of the offering, or is a distinct formation of fruits required?, v. <a href=\"#\" data-headword=\"חֲנָטָה\">חֲנָטָה</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ה׳ דפירא</span> the coming forth of the fruit, <span dir=\"rtl\">ה׳ דעלה</span> of the foliage.</div>","alt":[]},"8147":{"h":"הַנְתּוּכִין","r":"E00694","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"תּוֹךְ I\">תוך</a>, <a href=\"#\" data-headword=\"תְּכָךְ\">תכך</a>, with prefix <span dir=\"rtl\">הנ</span>; cmp. <span dir=\"rtl\">הנדקוקא</span>) <i>pannelled ceiling</i>. <span class=\"citation\">Targ. I Kings VI, 9</span> (h. text <span dir=\"rtl\">גֵּבִים</span>).</div>","alt":[]},"8148":{"h":"הֶסֵּב","r":"E00695","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">סבב</span>, Hif.) <i>placing the divans around the table;</i> in. gen. <i>banquet, meal in company</i> (v. <a href=\"#\" data-headword=\"מֵסֵב\">מֵסֵב</a>). <span class=\"citation\">Y. Maasr. IV, 51ᵇ</span> top <span dir=\"rtl\">עשה הי׳ בשדה</span> if one arranges a meal in company in the field. <span class=\"citation\">Y. B. Bath. IX, 16ᵈ</span> bot. <span dir=\"rtl\">ועשה לו ה׳ וכ׳</span> and he made the wedding meal for him in the <i>triclinium</i>. <span class=\"citation\">Y. Taan. IV, 68ᵃ</span> bot. <span dir=\"rtl\">סדר ה׳</span> the position of couches at a banquet. Ib. the patriarchs lie in the grave <span dir=\"rtl\">דרך ה׳</span> in the same position to one another as at meals (distinction between seniors and juniors; v. Sm. Ant. s. v. Triclinium).</div>","alt":["הֶיסֵּב"]},"8149":{"h":"הֶסֵּבָּה","r":"E00696","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֶסֵּב\">same</a>; <i>lying down for a meal in company</i>. <span class=\"citation\">Ber. 43ᵃ</span>, v. <a href=\"#\" data-headword=\"הֲנִי\">הֲנִי</a>. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"הֶיסֵּב\">היסבה</a> (Ms. M. <a href=\"#\" data-headword=\"הֶסֵּב\">הֶסֵּב</a>), v. <a href=\"#\" data-headword=\"הֶסֵּב\">preced.</a> <span class=\"citation\">Ib. 52ᵇ</span> הֶסֵּבַּת גוים Ms. M. (ed. <a href=\"#\" data-headword=\"מְסִבָּה\">מְסִבַּת</a>) a banqueting of gentiles. <span class=\"citation\">Pes. 108ᵃ</span> <span dir=\"rtl\">הֶסּיבַּת ימין</span> lying on the right side at the Passover meal; a. fr.</div>","alt":["הֶסֵּיבָּה","הֶיסֵּ׳ I"]},"8150":{"h":"הֶסֵּבָּה II","r":"E00697","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">סבב</span>; v. <span class=\"citation\">Num. XXXVI, 7</span>) <i>the transfer of landed property from one tribe to another</i>. <span class=\"citation\">B. Bath. 111ᵇ</span> <span dir=\"rtl\">הֶסֵּבַּת הבעל</span> ed. (Ms. H. a. Rashb. <span dir=\"rtl\">סִבַּת</span>, <span dir=\"rtl\">סִיבַּת</span>) the transfer which would be caused by the husband’s succeding to his wife’s property. <span class=\"citation\">Ib. 112ᵃ</span> ה׳ הבן Ms. R. (ed. <span dir=\"rtl\">סיבת</span>, <span dir=\"rtl\">סבת</span>) the eventual transfer through the son’s succession.</div>","alt":[]},"8151":{"h":"הֶסְגֵּר","r":"E00698","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָגַר\">סָגַר</a>; v. <span class=\"citation\">Lev. XIII, 4</span>, a. e.) <i>locking up</i> the leper for trial; cmp. <a href=\"#\" data-headword=\"הֶחְלֵט\">הֶחֱלֵט</a>. <span class=\"citation\">Y. Meg. I, 71ᵇ</span> <span dir=\"rtl\">מתוך ה׳</span> after being locked up. <span class=\"citation\">Y. M. Kat. III, 82ᶜ</span> bot.; a. fr.</div>","alt":[]},"8152":{"h":"הַסְגָּרָה","r":"E00699","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"הֶסְגֵּר\">same</a>. <span class=\"citation\">Lev. R. s. 17</span> <span dir=\"rtl\">אין ה׳ וכ׳</span> locking up (<span dir=\"rtl\">סגר</span>, <span class=\"citation\">I Sam. XVII, 46</span>) alludes to leprosy.</div>","alt":[]},"8153":{"h":"הָסָה","r":"E00700","html":"<div class=\"sense\"> (b. h.) <i>to be silent</i>. <span class=\"citation\">Num. R. s. 23</span> <span dir=\"rtl\">והָסוּ כל וכ׳</span> and all Israel was silenced before him (to listen to him); Tanḥ. Masé 5 <span dir=\"rtl\">הסבו</span>; ed. Bub. 4 <span dir=\"rtl\">וחסו</span>.</div>","alt":[]},"8154":{"h":"הסוקים","r":"E00701","html":"<div class=\"sense\">, <span class=\"citation\">Y. Snh. VIII, beg. 26ᵃ</span>, read: <span dir=\"rtl\">אכל חסחוסים</span>, v. <a href=\"#\" data-headword=\"הַסְחוּס\">הַסְחוּס</a></div>","alt":[]},"8155":{"h":"הַסְחוּס","r":"E00702","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַסְחוּס\">חַסְחוּס</a></div>","alt":[]},"8156":{"h":"הֶסֵּט","r":"E00703","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶיסֵּט\">הֶיסֵּט</a></div>","alt":[]},"8157":{"h":"*הַסְטָא","r":"E00704","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (hasta) <i>spear</i>. Pesik. R. suppl. (p. 197ᵃ ed. Fr.) <span dir=\"rtl\">עושה להם בסאטה בתוך הארץ</span> (read: <span dir=\"rtl\">שולח להם ה׳ וכ׳</span>; corresp. to <span dir=\"rtl\">ירה חצים</span>, Pesik. Vayhi, p. 66ᵇ) he sends (or throws) a spear into their land (as a declaration of war, v. Sm. Ant. a. Luebker Reallex. s. v. Hasta).</div>","alt":[]},"8158":{"h":"הֶסֵּיבָּה","r":"E00705","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶסֵּבָּה\">הֶסֵּבָּה</a></div>","alt":[]},"8159":{"h":"הֶסֵּיחַ","r":"E00706","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶסֵּבָּה\">הֶיסֵּ׳</a></div>","alt":[]},"8160":{"h":"הֶסֵּיעַ","r":"E00707","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָסַע\">נָסַע</a>) = <a href=\"#\" data-headword=\"הֶסֵּיחַ\">preced. w.</a>, (with or sub. <span dir=\"rtl\">הַדַּעַת</span>) <i>discarding, giving up</i>. <span class=\"citation\">Y. Pes. I, 28ᵇ</span> top <span dir=\"rtl\">ה׳ דבר תורה</span>, v. <a href=\"#\" data-headword=\"הֶיסֵּחַ\">הֶיסֵּחַ</a>. <span class=\"citation\">Y. Shek. VII, beg. 50ᶜ</span> <span dir=\"rtl\">ה׳ דעת טעון וכ׳</span> sacrificial meat whose existence has been forgotten (is unfit and) requires decomposition before it is burnt. <span class=\"citation\">Y. Meg. IV, 75ᶜ</span> top <span dir=\"rtl\">מפני ה׳ ד׳</span> because his attention may be diverted (by looking at the priests); <span class=\"citation\">Y. Taan. IV, beg. 67ᵇ</span> <a href=\"#\" data-headword=\"מסיע\">מסיע</a> (corr. acc.). <span class=\"citation\">Y. Pes. X, 37ᵈ</span> bot. <span dir=\"rtl\">מפני ה׳ הד׳</span> because the thought of eating it has been abandonned.</div>","alt":[]},"8161":{"h":"הֲסַם","r":"E00708","html":"<div class=\"sense\"> Ar., v. <a href=\"#\" data-headword=\"חֲסַם\">חֲסַם</a></div>","alt":[]},"8162":{"h":"הֶסְפֵּד","r":"E00709","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָפַד\">סָפַד</a>) <i>funeral ceremonies, manifestations of mourning, funeral address, eulogy</i> &amp;c. <span class=\"citation\">M. Kat. III, 8</span> <span dir=\"rtl\">שלא להרגיל את הה׳</span> in order not to invite lamentation. <span class=\"citation\">Tosef. ib. II, 17</span> ה׳ על לב <i>hesped</i> means beating on the heart. <span class=\"citation\">Y. Ber. III, 6ᵇ</span> top [read:] <span dir=\"rtl\">הסופד וכל העסוקין בה׳</span> (v. <span class=\"citation\">Tosef. ib. II, 11</span> ed. Zuck., Var.) the leader of the lamentation and all those engaged in it. <span class=\"citation\">Y. Succ. V, 55ᵇ</span> bot. <span dir=\"rtl\">הֶסְפֵּידוֹ של וכ׳</span> the mourning for &amp;c. <span class=\"citation\">Sabb. 153ᵃ</span> <span dir=\"rtl\">מהספדו של אדם וכ׳</span> from the way a person is mourned for you can learn whether he deserves future happiness; a. fr.—קשר ה׳ <i>to compose and arrange a funeral song</i>. <span class=\"citation\">Y. Yeb. XVI, 15ᵈ</span> top <span dir=\"rtl\">מצא ה׳ קשור וכ׳</span> found that lamentations were prepared in his house. <span class=\"citation\">Y. Yoma I, 38ᵇ</span>; Y. Sot. I, end, 17ᵈ. Lam. R. introd. (R. Joh. 1).</div>","alt":[]},"8163":{"h":"הֶסְפֵּדָא","r":"E00710","html":"<div class=\"sense\"><span class=\"citation\">Targ. Lam. I, 18</span>; a. e.—<span class=\"citation\">Ber. 6ᵇ</span>. <span class=\"citation\">Succ. 52ᵃ</span>; a. fr.</div>","alt":["הֶסְפֵּי׳"]},"8164":{"h":"הַסָּתָה","r":"E00711","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*יָסַת\">יָסַת</a> or <a href=\"#\" data-headword=\"סוּת\">סוּת</a>) <i>seduction, enticement</i>. <span class=\"citation\">Yoma 22ᵇ</span> <span dir=\"rtl\">דאוריה ודה׳</span> the sin against Uriah and that of counting the people to which he was enticed (<span class=\"citation\">II Sam. XXIV, 1</span>). <span class=\"citation\">Ḥull. 4ᵇ</span> אין ה׳ בדברים <i>enticing</i> (the verb <a href=\"#\" data-headword=\"*יָסַת\">הסית</a>) never applies to verbal persuasion (but only to sensual influences). <span class=\"citation\">Sifré Deut. 87</span> אין ה׳ אלא טעות <i>enticing</i> means leading astray; <span dir=\"rtl\">אין ה׳ אלא גירוי</span> it means instigation.</div>","alt":[]},"8165":{"h":"הַסְתֵּר","r":"E00712","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Infin. Hif. of <a href=\"#\" data-headword=\"סָתַר I\">סָתַר</a>) <span dir=\"rtl\">ה׳ פנים</span> (from <span class=\"citation\">Deut. XXXI, 18</span>) <i>hiding of face, divine anger, refusal to answer prayer</i>. <span class=\"citation\">Ḥag. 5ᵃ</span> <span dir=\"rtl\">כל שאינו בה׳ פ׳ וכ׳</span> he who is not subject to the hiding of face (who does not suffer under general persecution) is none of them (not of Israelitish descent). <span class=\"citation\">Ib.ᵇ</span></div>","alt":[]},"8166":{"h":"הַעֲבָרָה","r":"E00713","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עָבַר\">עָבַר</a>) </div><div class=\"sense\"><b>1)</b> <i>carrying, bearing</i>. <span class=\"citation\">R. Hash. 27ᵇ</span>, a. e. (ref. to <span dir=\"rtl\">והעברת</span>, <span class=\"citation\">Lev. XXV, 9</span>) <span dir=\"rtl\">דרך הַעֲבָרָתוֹ</span> (leave the horn) in the way in which it was borne by the living animal (in its natural shape).</div><div class=\"sense\"><b>—2)</b>  (= <span dir=\"rtl\">הַעֲבָרַת קול</span>) <i>causing the sound to pass over a certain space, proclamation</i>. Ib. 34ᵃ דיליף ה׳ ה׳ ממשה Ms. M. (ed. <span dir=\"rtl\">דגמר עברה ע׳</span>) we learn the meaning of <a href=\"#\" data-headword=\"עָבַר\">העביר</a> (Lev. l. c.) from the meaning it has in reference to Moses (<span class=\"citation\">Ex. XXXVI, 6</span>). <span class=\"citation\">Sabb. 96ᵇ</span>; <span class=\"citation\">Yalk. Ex. 413</span>.</div><div class=\"sense\"><b>—3)</b> <i>leading across, passing;</i> in gen. <i>use of the stem</i> <a href=\"#\" data-headword=\"עֵבֶר I\">עבר</a>. <span class=\"citation\">Y. Snh. VII, 25ᵇ</span> bot. (interch. with <span dir=\"rtl\">עברה</span>); Sifra K’doshim ch. VIII, Par. 4 <span dir=\"rtl\">מה ה׳ וכ׳</span> as the ‘passing’ there (<span class=\"citation\">Deut. XVIII, 10</span>) means through fire, so does the ‘passing’ here (<span class=\"citation\">Lev. XVIII, 21</span>). <span class=\"citation\">Bekh. 32ᵃ</span> <span dir=\"rtl\">ה׳ ה׳ ממעשר</span> analogy between the first-born and the tithes founded on the use of the stem <a href=\"#\" data-headword=\"עֵבֶר I\">עבר</a> (<span class=\"citation\">Ex. XIII, 12</span>, a. <span class=\"citation\">Lev. XXVII, 32</span>); (<span class=\"citation\">Zeb. 9ᵃ</span>, a. e. <span dir=\"rtl\">עברה</span>).</div><div class=\"sense\"><b>—4)</b>  (from <span class=\"citation\">Num. VIII, 7</span>; <span class=\"citation\">VI, 5</span>, a. e.) <span dir=\"rtl\">הַעֲבָרַת שיער</span> <i>passing the razor over the hair, shaving</i>. <span class=\"citation\">Naz. 58ᵇ</span>, sq. <span dir=\"rtl\">ה׳ ש׳</span> removing the hair of the body. Y. ib. II, end, 52ᵇ <span dir=\"rtl\">לה׳ ש׳</span> for the purpose of removing the hair, opp. <span dir=\"rtl\">גידול שיער</span>.</div>","alt":[]},"8167":{"h":"הַעֲדָאָה","r":"E00714","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  (<a href=\"#\" data-headword=\"עוּד\">עוּד</a>, <i>Hif.</i>) <i>testimony, deposition</i>. <span class=\"citation\">B. Mets. 3ᵃ</span>; <span class=\"citation\">3ᵇ</span> <span dir=\"rtl\">הַעֲדָאַת עדים</span> evidence through witnesses; a. e.</div><div class=\"sense\"><b>—2)</b>  (<a href=\"#\" data-headword=\"יָעַד\">יָעַד</a>) <i>warning given to the owner of a mischievous animal</i> (<span class=\"citation\">Ex. XXI, 29</span>); <i>law concerning damages payable after warning</i>, v. <a href=\"#\" data-headword=\"מוּעָד\">מוּעָד</a>. <span class=\"citation\">B. Kam. 18ᵇ</span> <span dir=\"rtl\">יש ה׳ וכ׳</span> the law &amp;c. applies to &amp;c. (and full damages must be paid). Y. ib. II, beg. 2ᵈ; a. fr.</div>","alt":[]},"8168":{"h":"הַעֲדָפָה","r":"E00715","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עָדַף\">עָדַף</a>) <i>surplus; addition, increase</i>. <span class=\"citation\">Keth. 43ᵃ</span> <span dir=\"rtl\">לה׳</span> concerning the surplus of the value of labor over the cost of sustenance. <span class=\"citation\">Ib. 66ᵃ</span> <span dir=\"rtl\">ה׳ ע&quot;י הדחק</span> a surplus gained through an extraordinary exertion. <span class=\"citation\">B. Kam. 87ᵇ</span>. <span class=\"citation\">Gitt. 12ᵃ</span>; a. e.—<span class=\"citation\">Ib. 12ᵇ</span> <span dir=\"rtl\">לה׳</span> for additional support (not included in the sustenance furnished by the master).</div>","alt":[]},"8169":{"h":"הַעֲלָאָה","r":"E00716","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (עָלָה <i>Hif.</i>) </div><div class=\"sense\"><b>1)</b>  (fr. <span class=\"citation\">Lev. XIX, 19</span>) <i>throwing over one’s shoulders, wrapping</i>, opp. to <a href=\"#\" data-headword=\"לְבִישָׁה\">לבישה</a> putting on of a dress. <span class=\"citation\">Yeb. 4ᵇ</span>. <span class=\"citation\">Yoma 69ᵃ</span></div><div class=\"sense\"><b>—2)</b> <i>bringing up, offering on the altar, placing on the table</i>. <span class=\"citation\">Pesik. R. s. 16</span>, end <span dir=\"rtl\">כדי ה׳ אחת</span> sufficient for one offering; Tanḥ. Ki Thissa 10. <span class=\"citation\">Ḥull. 104ᵃ</span> <span dir=\"rtl\">ואנן נגזר ה׳</span></div><div class=\"sense\"><b>—3)</b>  (v. <span class=\"citation\">Lev. XVI, 9</span>) <i>taking the lot out of the ballot box</i>. <span class=\"citation\">Y. Yoma IV, 41ᶜ</span> top.</div>","alt":["הַעֲלָיָיה"]},"8170":{"h":"הֵעָלֵם","r":"E00717","html":"<div class=\"sense\"> c. (Inf. Nif. of <a href=\"#\" data-headword=\"עָלַם I\">עָלַם</a>) <i>being unknown</i>, esp. (with ref. to <span class=\"citation\">Lev. IV</span> to V) <i>unconsciousness, forgetfulness</i> as the cause of a transgression. <span class=\"citation\">Shebu. 26ᵃ</span> <span dir=\"rtl\">ה׳ שבועה</span> forgetting that he had sworn; <span dir=\"rtl\">ה׳ חפץ</span> forgetting the subject of the oath. <span class=\"citation\">Sabb. 70ᵇ</span> <span dir=\"rtl\">ה׳ שבת</span> unconsciousness of its being the Sabbath day; <span dir=\"rtl\">ה׳ מלאכות</span> of the sinful nature of those labors. Ib. <span dir=\"rtl\">אם עשאן … בה׳ אחד</span> if he did all the forbidden labors in one state of unconsciousness (without being reminded between); Y. ib. III, 9ᵇ top <span dir=\"rtl\">בה׳ אחת</span>. Ib. I, 2ᵇ <span dir=\"rtl\">בעלם אחד</span> (interch. with <span dir=\"rtl\">בהעלם</span>); <span class=\"citation\">B. Bath. 55ᵇ</span> <span dir=\"rtl\">בה׳</span> (Ms. H. <span dir=\"rtl\">בעלם</span>); <span class=\"citation\">Ker. IV, 2</span> (<span class=\"citation\">17ᵇ</span>) <span dir=\"rtl\">בה׳ אחת</span>; <span class=\"citation\">Ker. III, 2</span> <span dir=\"rtl\">בה׳ אחד</span>. Sifra Vayikra, Ḥobah, Par. 1, ch. I; a. fr.—Pl. <span dir=\"rtl\">הֵעָלֵימוֹת</span>. Y. Sabb. l. c. <span dir=\"rtl\">בשני ה׳</span> in two discontinuous states of forgetfulness. Y. Shebu. I, 32ᵈ top <span dir=\"rtl\">כמה ידיעות וה׳</span> many moments of consciousness and intervening forgetfulness. <span class=\"citation\">Y. Snh. VII, 24ᶜ</span> top; a. e.—Usu. <span dir=\"rtl\">הַעֲלָמוֹת</span> (fr. <a href=\"#\" data-headword=\"הַעֲלָמָה\">הַעֲלָמָה</a>, v. <a href=\"#\" data-headword=\"הַעֲלָמָה\">next w.</a>), or <span dir=\"rtl\">הֵעָלֵמוֹת</span>. <span class=\"citation\">Sabb. 80ᵃ</span> <span dir=\"rtl\">בשתי ה׳</span>; <span class=\"citation\">Ker. 17ᵃ</span>; B. Bath. l. c. <span dir=\"rtl\">בשני ה׳</span>. <span class=\"citation\">Tosef. Ker. III, 2</span>; <span class=\"citation\">7</span> <span dir=\"rtl\">בשני ה׳</span>; a. fr.—[<span class=\"citation\">Midr. Till. to Ps. IX, 1</span> <span dir=\"rtl\">הָעֲלָמוֹת</span>, v. <a href=\"#\" data-headword=\"עֶלֶם I\">עֶלֶם</a>.]</div>","alt":[]},"8171":{"h":"הַעֲלָמָה","r":"E00718","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֵעָלֵם\">same</a>. <span class=\"citation\">Shebu. 4ᵃ</span> <span dir=\"rtl\">ה׳ למלקות מאי עבידתיה</span> how can an act committed through forgetfulness be punished with lashes?—<span class=\"citation\">Ib. 14ᵇ</span> <span dir=\"rtl\">ה׳ היא</span> is this to be considered a sin committed through ignorance (not preceded by knowledge)?—Pl. <span dir=\"rtl\">הַעֲלָמוֹת</span>, v. <a href=\"#\" data-headword=\"הֵעָלֵם\">preced.</a></div>","alt":[]},"8172":{"h":"הַעֲמָדָה","r":"E00719","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עָמָד I\">עָמַד</a>) <i>placing, being placed, appearance</i>. <span class=\"citation\">B. Kam. 34ᵃ</span>, a. e. <span dir=\"rtl\">כשעת ה׳ בדין</span> according to the condition of the animal at the time of appearance in court. <span class=\"citation\">Bekh. 32ᵇ</span>, a. e. <span dir=\"rtl\">בעי ה׳ והערכה</span> must be placed (before the priest) and appraised (<span class=\"citation\">Lev. XXVII, 11</span>). Ib. <span dir=\"rtl\">בכלל ה׳ וכ׳</span> subject to the law requiring placing &amp;c. <span class=\"citation\">Yoma 41ᵇ</span> <span dir=\"rtl\">אה׳ קאי</span> does it refer to the placing of the sacrifice (to <span dir=\"rtl\">והעמידו</span>, Mish. ib.)?—Y. Maas. III, 54ᶜ top <span dir=\"rtl\">ה׳ והערכה</span> (interchanging with <a href=\"#\" data-headword=\"עמדה\">עמדה</a>).</div>","alt":[]},"8173":{"h":"הַעֲנֵיק","r":"E00720","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"עָנַק\">עָנַק</a>, with ref. to <span class=\"citation\">Deut. XV, 14</span>) <i>the outfitting of the emancipated slave</i>. <span class=\"citation\">Kidd. 17ᵇ</span> <span dir=\"rtl\">לה׳</span> (‘and also to thy handmaid shalt thou do likewise’, <span class=\"citation\">Deut. XV, 17</span>) refers to the outfit (not to the marking of the ear); Y. ib. I, 59ᶜ bot.; <span class=\"citation\">Sifré Deut. 122</span>.</div>","alt":["הַעֲנֵק"]},"8174":{"h":"הַעֲרָאָה","r":"E00721","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַעֲרָיָיה\">הַעֲרָיָיה</a></div>","alt":[]},"8175":{"h":"הַעֲרֵב","r":"E00722","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"עָרַב I\">עָרַב</a>) <span dir=\"rtl\">ה׳ שמש</span> <i>sunset</i>, required for the unclean person, after purification, to be entirely clean (<span class=\"citation\">Lev. XI, 27</span>; a. fr.). <span class=\"citation\">Yoma 6ᵃ</span> <span dir=\"rtl\">והא בעי ה׳ הש׳</span> does he not require the sunset to pass before he may officiate?; a. fr.</div>","alt":[]},"8176":{"h":"הַעֲרָבָה","r":"E00723","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"עֶרֶב\">עֶרֶב</a>) </div><div class=\"sense\"><b>1)</b> <i>going home in the evening from labor</i> (= <a href=\"#\" data-headword=\"הַכְנָסָה\">הַכְנָסָה</a>), opp. to <a href=\"#\" data-headword=\"הַשְׁכָּמָה\">הַשְׁכָּמָה</a>. Y. B. Mets. VII, beg. 11ᵇ [read:] <span dir=\"rtl\">שתהא השכמה משל בעה&quot;ב וה׳ משל פועלין</span> that the time needed for going out &amp;c., v. <a href=\"#\" data-headword=\"הוֹצָאָה\">הוֹצָאָה</a> 4). Ib. (not <span dir=\"rtl\">ערבית</span>) <span dir=\"rtl\">ובערבי שבתות בין … ה׳ וכ׳</span> on Sabbath eves both are deducted from the employer’s time.</div><div class=\"sense\"><b>—2)</b> <i>night work</i>. <span class=\"citation\">Lev. R. s. 19</span>; Midr. Sam. ch. V <span dir=\"rtl\">דברי תורה צריכין השחרה וה׳ הפרנסה מנין</span> the words of the Law require early and late study, whence shall sustenance come?</div>","alt":[]},"8177":{"h":"הַעֲרָיָיה","r":"E00724","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עָרָה\">עָרָה</a>, v. <span class=\"citation\">Lev. XX, 18</span>) <i>sexual contact, the first stage of sexual connection</i>. <span class=\"citation\">Tosef. Sot. I, 2</span>; Y. ib. I, 16ᶜ bot. <span dir=\"rtl\">כדי ה׳</span> time long enough for arriving at the intimacy of the first stage. <span class=\"citation\">Yeb. 55ᵇ</span>, a. e. <span dir=\"rtl\">ה׳ זו הכנסת וכ׳</span>, v. <a href=\"#\" data-headword=\"הַכְנָסָה\">הַכְנָסָה</a>; a. fr.</div>","alt":["הַעֲרָאָה"]},"8178":{"h":"הַעֲרָכָה","r":"E00725","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עָרַךְ\">עָרַךְ</a>) <i>appraisement</i>. <span class=\"citation\">Bekh. 32ᵇ</span>; a. e., v. <a href=\"#\" data-headword=\"הַעֲמָדָה\">הַעֲמָדָה</a>.</div>","alt":[]},"8179":{"h":"הַעֲרָמָה","r":"E00726","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עָרַם I\">עָרַם</a>) <i>trickery, legal evasion, improper means to avoid a religious duty</i>. Y. Peah V, 19ᵇ bot.; <span class=\"citation\">Y. Ned. IV, end, 38ᵈ</span> <span dir=\"rtl\">לא חשו לה׳</span> the Rabbis did not apprehend an evasion. Ib. V, end, 39ᵇ a donation like that of Beth-Horon (v. Mish. <span class=\"citation\">ib. V, 7</span>) <span dir=\"rtl\">שהיתה בה׳</span> which was made for the sake of circumventing (a vow). <span class=\"citation\">Tosef. B. Mets. IV, 3</span> <span dir=\"rtl\">הַעֲרָמַת ריבית</span> an evasion of the law of usury; <span class=\"citation\">B. Mets. 62ᵇ</span>; Y. ib. V, 10ᵇ top; a. fr.</div>","alt":[]},"8180":{"h":"הֲפוֹךְ","r":"E00727","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲפַךְ\">הֲפַךְ</a></div>","alt":["הָפוּךְ"]},"8181":{"h":"הפות","r":"E00728","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. II, 12</span>, v. <span dir=\"rtl\">חָפוּת</span></div>","alt":[]},"8182":{"h":"הִפּוֹתִּיקִי","r":"E00729","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִפֹּותִּיקִי\">אִפּוֹתִּיקִי</a></div>","alt":["הִפּוֹתִּקִי","הִפּוֹתִּיקָאוֹת"]},"8183":{"h":"הַפְטָרָה","r":"E00730","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּטַר\">פָּטַר</a>, v. <a href=\"#\" data-headword=\"אַפְטָרָה\">אַפְטָרָה</a>) </div><div class=\"sense\"><b>1)</b> <i>farewell-address, toast on parting</i>. <span class=\"citation\">Gen. R. s. 69</span>, end.</div><div class=\"sense\"><b>—2)</b> <i>Haftarah, prophetic lesson</i> read in Synagogue after the reading from the Pentateuch, v. <a href=\"#\" data-headword=\"אַפְטַרְתָּא\">אַפְטַרְתָּא</a>. <span class=\"citation\">Meg. 30ᵇ</span>.—Pl. <span dir=\"rtl\">הַפְטָרוֹת</span>. Ib.; a. e.</div>","alt":[]},"8184":{"h":"הָפְיָא","r":"E00731","html":"<div class=\"sense\"> Ar., v. <a href=\"#\" data-headword=\"חוּפְיָא\">חוּפְיָא</a></div>","alt":[]},"8185":{"h":"הפיטקי","r":"E00732","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִיפָּטִיקוֹס\">הִיפָּטִיקוֹס</a></div>","alt":[]},"8186":{"h":"הָפֵיךְ","r":"E00733","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲפַךְ\">הֲפַךְ</a></div>","alt":[]},"8187":{"h":"הֲפִיךְ","r":"E00734","html":"<div class=\"sense\"> adv., v. <a href=\"#\" data-headword=\"הֲפַךְ\">הֲפַךְ</a>.</div>","alt":[]},"8188":{"h":"הָפִיכָא","r":"E00735","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲפַךְ\">הֲפַךְ</a>) <i>perverse</i>. <span class=\"citation\">Targ. Prov. X, 31</span> Ms. (ed. <span dir=\"rtl\">דהֲפִיכוּ</span>).—Pl. <a href=\"#\" data-headword=\"הֲפֵיכְתָּא\">הֲפִיכָתָא</a> <i>perverse things, perverseness</i>. <span class=\"citation\">Ib. XVI, 30</span>.</div>","alt":[]},"8189":{"h":"הֲפִיכָה","r":"E00736","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָפַךְ\">הָפַךְ</a>) <i>upturning, displacing</i>, as a symbol of possession. <span class=\"citation\">Y. B. Kam. III, 3ᶜ</span> bot., contrad. to <a href=\"#\" data-headword=\"הַגְבָּהָה\">הַגְבָּהָה</a>. [<span dir=\"rtl\">הֲפִיכוֹת</span>, v. <a href=\"#\" data-headword=\"הֲפֵכָה\">הֲפֵכָה</a>.]</div>","alt":[]},"8190":{"h":"הֲפִיכוּ","r":"E00737","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲפַךְ\">הֲפַךְ</a>) <i>perverseness</i>. <span class=\"citation\">Targ. Prov. X, 31</span>, v. <a href=\"#\" data-headword=\"הָפִיכָא\">הָפִיכָא</a>.</div>","alt":[]},"8191":{"h":"הֲפֵיכְתָּא","r":"E00738","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲפֵכְתָּא\">הֲפֶכְתָּא</a></div>","alt":[]},"8192":{"h":"הֵפְיָנוֹס","r":"E00739","html":"<div class=\"sense\"><i>of Haipha</i>(?). <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">יוסי ה׳</span>; v. <a href=\"#\" data-headword=\"*חֵפָנִי\">חֵפָנִי</a>.</div>","alt":["(הפינס)"]},"8193":{"h":"הָפַךְ","r":"E00740","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  (act. verb) <i>to turn; to change; to reverse; to pervert, subvert, destroy</i>. <span class=\"citation\">Ex. R. s. 18</span> <span dir=\"rtl\">הָפְכָה המדינה שעבודה וכ׳</span> a country perverted the rules of forced labor for the captives (treating them inhumanely); <span dir=\"rtl\">ה׳ עליהם את הדין וכ׳</span> he changed the law against them and put them to death by night (against the Jewish law, v. <span class=\"citation\">Snh. IV, 1</span>). Ib. <span dir=\"rtl\">ה׳ סדום</span> He destroyed Sodom. <span class=\"citation\">Ber. 55ᵇ</span> <span dir=\"rtl\">כשם שהָפַכְתָּ וכ׳</span> as thou didst turn the curse … into blessing, <span dir=\"rtl\">כן הֲפוֹךְ וכ׳</span> so do thou turn &amp;c. <span class=\"citation\">B. Kam. III, 3</span> <span dir=\"rtl\">ההוֹפֵךְ את הגלל</span> he who upturns (changes the place of) the dung (taking possession); a. v. fr.—<i>Part. Pass</i>. <a href=\"#\" data-headword=\"הֲפוֹךְ\">הָפוּךְ</a>. <span class=\"citation\">Pes. 50ᵃ</span> עולם ה׳ ראיתי וכ׳ I saw a reversed world, the uppermost below &amp;c. <span class=\"citation\">Sabb. 108ᵇ</span> הֲפוּכָה סדום וכ׳ Sodom is subverted and what is said about it is perverted. Sifra Thazr. Par. 3, ch. III <a href=\"#\" data-headword=\"הֲפוֹךְ\">הפוך</a>, <span dir=\"rtl\">הפוכה</span> when its color is changed; a. v. fr.—<span class=\"citation\">Y. Naz. V, end, 54ᵇ</span> <span dir=\"rtl\">לשון הפוך</span>, v. <a href=\"#\" data-headword=\"הֶפֶךְ\">הֶפֶךְ</a>.</div><div class=\"sense\"><b>—2)</b>  (neut. verb) <i>to change</i>. Sifra ch. IV <span dir=\"rtl\">אי כולי ה׳ לבן</span> if the whole of it has turned white. <span class=\"citation\">Neg. IV, 3</span>; a. fr.</div><div class=\"sense\"><b>Nif. נֶהְפַּךְ</b> <div class=\"sense\"><b>1)</b> <i>to be upturned, destroyed; to be changed</i>. <span class=\"citation\">Yalk. Esth. 1056</span> <span dir=\"rtl\">כשנ׳ סדום</span> when Sodom was subverted. <span class=\"citation\">Gen. R. s. 50</span> <span dir=\"rtl\">ומדינה נֶהְפֶּכֶת</span>, v. <a href=\"#\" data-headword=\"אִדְרַבְלָא\">אִדְרַבְלָא</a>. Tanḥ. Sh’moth 25 <span dir=\"rtl\">נ׳ להם מן וכ׳</span> the voice turned around, as if coming from &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to roll about</i>, v. <i>Hithpa.</i></div></div><div class=\"sense\"><b>Pi. הִיפֵּךְ</b> <div class=\"sense\"><b>1)</b> <i>to reverse, pervert, turn</i>. <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">שהי׳ דברים וכ׳</span> who spoke perversely of the Creator. <span class=\"citation\">Kidd. 59ᵃ</span> <span dir=\"rtl\">עני מְהַפֵּךְ וכ׳</span> a poor man turns the cake, and another comes and takes it, i.e. one who buys away what another is negotiating for.</div><div class=\"sense\"><b>—2)</b> <i>to scheme</i>, v. infra.</div></div><div class=\"sense\"><b>Hithpa. הִתְהַפֵּךְ</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְהַפֵּךְ</span> </div><div class=\"sense\"><b>1)</b> <i>to be changed, disguise one’s self</i>. <span class=\"citation\">Gen. R. s. 21</span> end <span dir=\"rtl\">שהם מִתְהַפְּכִים</span> they (the angels) assume various shapes.</div><div class=\"sense\"><b>—2)</b> <i>to turn one’s self around</i>. Ib. <span dir=\"rtl\">שהיא מִתְהַפֶּכֶת וכ׳</span> for it (the fiery sword) turns around man &amp;c. <span class=\"citation\">Yeb. 35ᵃ</span>; <span class=\"citation\">Keth. 37ᵃ</span> <span dir=\"rtl\">מתהפכת</span> she turns herself (makes violent motions). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נִתְהַפְּכָה</span> (Keth. l. c. <span dir=\"rtl\">נֶהֶפְכָה</span>).—Tanḥ. Vayetsé 11 <span dir=\"rtl\">היה מ׳ עליו</span> prevaricated (changing terms).</div><div class=\"sense\"><b>—3)</b> <i>to scheme</i>. Ruth R. introd. 3 <span dir=\"rtl\">שהוא מִתְהפֵּךְ ובא וכ׳</span> he (Esaw = Rome) schemes and comes against &amp;c.; <span class=\"citation\">Yalk. Prov. 959</span> <span dir=\"rtl\">בא ומְהַפֵּךְ על וכ׳</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שהם מִתְהַפְּכִים וכ׳</span>; Ruth R. l. c. <span dir=\"rtl\">שמְהַפְּכִין</span>.</div></div>","alt":[]},"8194":{"h":"הֲפַךְ","r":"E00741","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"הָפַךְ\">same</a> (v. <a href=\"#\" data-headword=\"אֲפַךְ\">אֲפַךְ</a>) </div><div class=\"sense\"><b>1)</b> <i>to turn, change</i>. <span class=\"citation\">Targ. Ps. CV, 29</span>; a. fr.—<span class=\"citation\">Y. Sabb. XVI, end, 15ᵈ</span> <span dir=\"rtl\">ה׳ אפוי</span> he turned his face off.</div><div class=\"sense\"><b>—2)</b> <i>to overturn, destroy</i>. <span class=\"citation\">Targ. Gen. XIX, 25</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  (neut. verb) <i>to turn around</i>. <span class=\"citation\">Targ. Prov. XXVI, 11</span>; a. e.—<span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">כהדין ברנש … הָפוּךְ לאחוריו</span> like one going down a ladder backwards; <span class=\"citation\">Y. R. Hash. II, 58ᵃ</span> <span dir=\"rtl\">כאילין דסלקין בסולמא הֲפִיךְ</span> like those who ascend a ladder backward; <span class=\"citation\">Yalk. Job 912</span> [read:] <span dir=\"rtl\">כהדין דסלקין בסולמא הפוך</span> (v. Lattes Saggio p. 106).</div><div class=\"sense\"><b>—4)</b>  (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to be engaged in, to handle</i>. <span class=\"citation\">Pes. 113ᵃ</span> (prov.) <span dir=\"rtl\">הֲפוֹךְ בנבילתא ולא תֵיפוֹךְ וכ׳</span> deal in carcasses, but deal not in words (gossip, sophistry &amp;c.). <span class=\"citation\">Y. B. Kam. IV, beg. 4ᵃ</span> אנא הפך ומתהפך בדידי וכ׳ I turn around my stock of goods (selling and buying again), so that I reach thee in profits. <span class=\"citation\">Ab. V, 22</span> <span dir=\"rtl\">הֲפוֹךְ בה וכ׳</span> study it over and again; a. fr.—V. <a href=\"#\" data-headword=\"הָפִיכָא\">הֲפִיכָא</a>.</div><div class=\"sense\"><b>Pa. הַפֵּיךְ</b> <div class=\"sense\"> l) (= h. <a href=\"#\" data-headword=\"שׁוּב I\">הֵשִׁיב</a>) <i>to turn; to bring back, restore; to turn off</i> (wrath), <i>to appease; to give in return, reply</i>. <span class=\"citation\">Targ. Prov. XXV, 13</span>.—<span class=\"citation\">Ib. XXIX, 8</span>.—<span class=\"citation\">Ib. XXIV, 29</span> Ms. (ed. <a href=\"#\" data-headword=\"הֲפַךְ\">אַהֲפֵיךְ</a> <i>Af</i>.).—<span class=\"citation\">Ib. 26</span>.—2) <i>to handle, be engaged in, barter, study</i> (v. Pe. 4). <span class=\"citation\">Kidd. 59ᵃ</span> <span dir=\"rtl\">דוה מְהַפֵּיךְ בההיא וכ׳</span> was negotiating about a field. <span class=\"citation\">Sabb. 119ᵃ</span> <span dir=\"rtl\">כמה דלא מְהַפִּיכְנָא בזכותיה</span> before I study what might be said in his favor. <span class=\"citation\">Pes. 40ᵃ</span> <span dir=\"rtl\">דמְהַפְּכֵי כיפי</span> who handle sheaves; <span dir=\"rtl\">כי מְהַפְּכִיתוּ הַפִּיכוּ וכ׳</span> (Ms. M. <span dir=\"rtl\">הפכיתו</span>) when ye handle (them), handle them with the thought that they will be used for a religious purpose.—<i>Part. pass</i>. <span dir=\"rtl\">מְהַפַּךְ</span>. Y. Maasr. III, end, 51ᵃ <span dir=\"rtl\">היא הפכה והיא מְהַפְּכָה</span> it turns and is turned in all directions (studied over and again), but we can learn nothing from it.</div></div><div class=\"sense\"><b>Af. אַהֲפֵךְ</b> <div class=\"sense\">, v. supra.</div></div><div class=\"sense\"><b>Ithpa. אִתְהַפֵּךְ</b> </div><div class=\"sense\"><b>Ithpe. אִתְהֲפֵיךְ</b> <div class=\"sense\"><b>1)</b> <i>to be turned, changed; to turn about, deal in</i> &amp;c. <span class=\"citation\">Targ. Lev. XIII, 3</span>. <span class=\"citation\">Targ. Job XXX, 21</span>; a. fr.—Y. Maasr. III, end, 51ᵃ, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to roll about</i>. <span class=\"citation\">Targ. Jud. VII, 13</span>; a. e.</div></div>","alt":["הָפֵיךְ","יַהֲפוֹךְ"]},"8195":{"h":"הֶפֶךְ","r":"E00742","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֲפַךְ\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>reverse, opposite</i>. <span dir=\"rtl\">לְשׁוֹן ה׳</span> a phrase which means the reverse (euphemism). <span class=\"citation\">Y. Naz. II, 51ᵈ</span> bot. (ed. Krot. <span dir=\"rtl\">הפר</span>, corr. acc.); ib. V, end, 54ᵇ <span dir=\"rtl\">לָשׁוֹן הָפוּךְ</span>.</div><div class=\"sense\"><b>—2)</b> <i>upturning</i> (a pile), <i>displacing</i>. <span class=\"citation\">B. Kam. 29ᵇ</span> <span dir=\"rtl\">כל ה׳ למטה וכ׳</span> the term ‘upturning’ means a movement within three cubits (Var. v. Rabb. D. S. a. l. note 80).</div>","alt":[]},"8196":{"h":"הֲפֵכָה","r":"E00743","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֶפֶךְ\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b>  (b. h.) <i>destruction</i>.</div><div class=\"sense\"><b>—2)</b> <i>change, turn</i>.—Pl. <span dir=\"rtl\">הֲפֵכוֹת</span>, <a href=\"#\" data-headword=\"הֲפֵכְתָּא\">הֲפֵי׳</a>. <span class=\"citation\">Ber. 55ᵇ</span> <span dir=\"rtl\">שלש ה׳</span> three verses in which <i>change</i> (the expression <span dir=\"rtl\">הפך</span>) occurs.</div>","alt":["הֲפֵיכָה"]},"8197":{"h":"הַפְכָנָא","r":"E00744","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲפֵכָה\">preced.</a> wds.) <i>fickle-minded</i>.—Pl. <span dir=\"rtl\">הַפְכָנִין</span>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 20</span>.</div>","alt":[]},"8198":{"h":"הֲפַכְפָּךְ","r":"E00745","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"הַפְכָנָא\">same</a>. <span class=\"citation\">Yalk. Esth. 1056</span>, v. next w.—Pl. <span dir=\"rtl\">הֲפַכְפָּכִין</span>. Ruth R. introd., 3; <span class=\"citation\">Yalk. Deut. 945</span> (<span class=\"citation\">Sifré Deut. 320</span> <span dir=\"rtl\">הֲפַכְפְּכָנִים</span>, v. <a href=\"#\" data-headword=\"הֲפַכְפְּכָן\">next w.</a>).</div>","alt":[]},"8199":{"h":"הֲפַכְפְּכָן","r":"E00746","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֲפַכְפָּךְ\">same</a>. <span class=\"citation\">Meg. 15ᵇ</span> (<span class=\"citation\">Yalk. Esth. 1056</span>, v. <a href=\"#\" data-headword=\"הֲפַכְפָּךְ\">preced.</a>).—<i>Pl.</i>, v. <a href=\"#\" data-headword=\"הֲפַכְפָּךְ\">preced.</a></div>","alt":[]},"8200":{"h":"הֲפֵכְתָּא","r":"E00747","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲפַךְ\">הֲפַךְ</a>) <i>destruction</i>. <span class=\"citation\">Targ. Gen. XIX, 29</span>. <span class=\"citation\">Targ. O. Deut. XXIX, 20</span> (Ms. <a href=\"#\" data-headword=\"מַהְפֶּיכְתָּא\">מַהֲפֶיכְתָּא</a>); a. e.—Pl. <a href=\"#\" data-headword=\"הֲפֵיכְתָּא\">הֲפֵיכָתָא</a>.—<span class=\"citation\">Targ. Y. II, Gen. XVIII, 2</span>.</div>","alt":["הֲפֵי׳"]},"8201":{"h":"הַפְלָאָה","r":"E00748","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּלָא\">פָּלָא</a>) </div><div class=\"sense\"><b>1)</b> <i>distinction, peculiarity, use of the word</i> <span dir=\"rtl\">פלא</span>. <span class=\"citation\">Sabb. 138ᵇ</span> <span dir=\"rtl\">ה׳ זו וכ׳</span> this peculiarity of punishment (<span class=\"citation\">Deut. XXVIII, 59</span>) &amp;c.; <span dir=\"rtl\">ה׳ זו תורה</span> it means the Law (afflictions causing the Law to be forgotten, ref. to <span class=\"citation\">Is. XXIX, 14</span>).</div><div class=\"sense\"><b>—2)</b> <i>distinct and solemn specification of a vow</i> (from <span class=\"citation\">Lev. XXVII, 2</span>; <span class=\"citation\">Num. VI, 2</span>; v. <a href=\"#\" data-headword=\"*אִסְפְּלִיאָה\">אִיסְפְּלִיאָה</a>). <span class=\"citation\">Tosef. Naz. III, 19</span> <span dir=\"rtl\">לא ניתנה נזירות אלא לה׳</span> the law of the <i>nazir’s</i> vow applies only to distinct utterance (where there is no doubt); <span class=\"citation\">Naz. 34ᵃ</span>; a. e.—<span class=\"citation\">Ib. 62ᵃ</span> of the two <i>ki yafli</i> (Lev. l. c. Num. l. c.) <span dir=\"rtl\">אחד ה׳ לאיסור ואחד ה׳ וכ׳</span> one intimates a distinct binding expression, and one a distinctness which opens the way to absolution (v. <span dir=\"rtl\">הֲָטָה</span>); <span class=\"citation\">Ḥag. 10ᵃ</span> <span dir=\"rtl\">אחת ה׳ וכ׳</span>.</div>","alt":[]},"8202":{"h":"הֶפְלֵג","r":"E00749","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּלַג\">פָּלַג</a>) </div><div class=\"sense\"><b>1)</b> <i>separation, interruption, interval</i>. <span class=\"citation\">Y. B. Kam. II, end, 3ᵃ</span> <span dir=\"rtl\">בה׳ נגיחות</span> it refers to gorings at intervals (not in three consecutive days). <span class=\"citation\">Y. Yoma III, 40ᵇ</span> bot. <span dir=\"rtl\">אם להפליג</span> if the conversation lasted long enough to be considered a discontinuation of the services, opp. <span dir=\"rtl\">לשעה</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עשו אותה כה׳</span> they declared it (the going out for easing one’s self, v. <a href=\"#\" data-headword=\"*מְסִיכָּה\">מסיכה</a>) to be like a discontinuation.</div><div class=\"sense\"><b>—2)</b> <i>digression</i>. <span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> bot. <span dir=\"rtl\">תשובת ה׳ השיבו</span> he made a reply only to divert his mind (Bab. <span class=\"citation\">ib. 44ᵇ</span> <span dir=\"rtl\">תשובה גנובה</span>, v. <a href=\"#\" data-headword=\"גָּנַב\">גָּנַב</a>).</div>","alt":["הֶפְלֵיג"]},"8203":{"h":"הַפְלָגָה","r":"E00750","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֶפְלֵג\">preced.</a>) <i>separation</i>, <span dir=\"rtl\">דּוֹר ה׳</span>, v. <a href=\"#\" data-headword=\"דּוֹר\">דּוֹר</a>. <span class=\"citation\">Snh. X, 3</span>; a. fr.</div>","alt":[]},"8204":{"h":"הֶפְלֵיג","r":"E00751","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶפְלֵג\">הֶפְלֵג</a></div>","alt":[]},"8205":{"h":"הֶפְסֵד","r":"E00752","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">פסד</span>) <i>decrease, loss; injury; disadvantage; waste</i>. <span class=\"citation\">Pes. 15ᵇ</span> <span dir=\"rtl\">ה׳ חולין</span> an unnecessary destruction of &amp;c.—Ib., a. fr. <span dir=\"rtl\">ה׳ מרובה</span> a considerable loss, opp. <span dir=\"rtl\">ה׳ מועט</span>. <span class=\"citation\">Ab. II, 1</span> <span dir=\"rtl\">ה׳ מצוה</span> the loss (inconvenience, sacrifice) connected with the performance of a good deed. <span class=\"citation\">Ib. V, 11</span>, sq. <span dir=\"rtl\">וצא שכרו בהֶפְסֵדוֹ</span> his advantage is set off by his disadvantage. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">הֶפְסֵדָהּ</span> the disadvantage of (punishment for) neglecting it, opp. <span dir=\"rtl\">שכרה</span> reward for observing it. <span class=\"citation\">B. Kam. 115ᵇ</span> <span dir=\"rtl\">מפני ה׳ כהן</span> because it is an injury to the priest (entitled to it). <span class=\"citation\">Sabb. 147ᵇ</span> <span dir=\"rtl\">ה׳ אוכלין</span> a waste of eatables; a. fr.</div>","alt":[]},"8206":{"h":"הֶפְסֵדָא","r":"E00753","html":"<div class=\"sense\"><span class=\"citation\">B. Kam. 115ᵇ</span> <span dir=\"rtl\">דאיכא ה׳</span> (ed. <span dir=\"rtl\">הפסדה</span>, corr. acc., Ms. R. a. F. <a href=\"#\" data-headword=\"הֶפְסֵד\">הפסד</a>). v. <a href=\"#\" data-headword=\"פְּסִידָא\">פְּסֵידָא</a></div>","alt":[]},"8207":{"h":"הֶפְסֵק","r":"E00754","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">פסק</span>) <i>interruption, suspension, end</i>. <span class=\"citation\">Erub. 54ᵃ</span> <span dir=\"rtl\">און לו ה׳ וכ׳</span> there is no end to it for all eternity. Y. Ber. XI, 10ᵃ bot. <span dir=\"rtl\">ה׳ ברכה</span> an unlawful interruption between the blessing and the partaking of food. Ib. II, 5ᵇ top <span dir=\"rtl\">ימי ה׳</span> intervening days during which menstruation ceased. Ib. IX, 13ᶜ bot.; <span class=\"citation\">Midr. Till. to Ps. CIV, 32</span> <span dir=\"rtl\">ה׳ מלכות</span> interregnum, anarchy. <span class=\"citation\">Y. Yeb. II, 3ᵈ</span> bot. <span dir=\"rtl\">שניות אין להן ה׳</span> the secondary degrees of forbidden marriages have no limitation; a. fr.</div>","alt":[]},"8208":{"h":"הַפְסָקָה","r":"E00755","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֶפְסֵק\">preced.</a>) <i>ceasing, interruption, interval</i>. <span class=\"citation\">Gen. R. s. 33</span> Sivan, the seventh month <span dir=\"rtl\">להַפְסָקַת וכ׳</span> counting from the time the rains ceased (<span class=\"citation\">Yalk. ib. 59</span> <span dir=\"rtl\">לירידת</span>). <span class=\"citation\">Taan. 4ᵇ</span> <span dir=\"rtl\">לה׳</span> with reference to ceasing to insert the mention of rain in the prayers. <span class=\"citation\">Lev. R. s. 1</span>, end <span dir=\"rtl\">אין כאן ה׳</span> there is nothing intervening (between <a href=\"#\" data-headword=\"וַיִּקְרָא\">ויקרא</a> a. <a href=\"#\" data-headword=\"וַיְדַבֵּר\">וידבר</a>, <span class=\"citation\">Lev. I, 1</span>); a. fr.—Pl. <span dir=\"rtl\">הַפְסָקוֹת</span>. <span class=\"citation\">Num. R. s. 14</span>, end <a href=\"#\" data-headword=\"ה׳\">ה׳</a> the intervals in revelations, i.e. passages in the Pentateuch not introduced by <i>vayikra</i> and <i>vaydabber</i>.—Esp. <i>Hafsakah</i>, the Sabbath intervening between the four Sabbaths on which the sections of the Torah, <i>Sh’kalim, Zakhor, Parah</i> and <i>Haḥodesh</i> are severally read, v. <a href=\"#\" data-headword=\"פָּרָשָׁה I\">פָּרָשָׁה</a>. <span class=\"citation\">Meg. 30ᵃ</span> שנייה לה׳ ‘the second Sabbath’ means that following the Hafsakah.</div>","alt":[]},"8209":{"h":"הַפְצָא","r":"E00756","html":"<div class=\"sense\"> Ar., v. <a href=\"#\" data-headword=\"חַפְצָא\">חַפְצָא</a></div>","alt":[]},"8210":{"h":"הֶפְקֵירָא","r":"E00757","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶפְקֵרָא\">הֶפְקֵרָא</a></div>","alt":[]},"8211":{"h":"הַפְקָעָה","r":"E00758","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּקַע\">פָּקַע</a>; cmp. <a href=\"#\" data-headword=\"אַפְקַעְתָּא\">אַפְקַעְתָּא</a>) <i>cancellation, release from debt.</i> <span class=\"citation\">B. Kam. 113ᵇ</span> <span dir=\"rtl\">הַפְקָעַת הלואתו</span> the cancellation of his (the gentile’s) loan.</div>","alt":[]},"8212":{"h":"הֶפְקֵר","r":"E00759","html":"<div class=\"sense\"> (Y. dial. <a href=\"#\" data-headword=\"הֶבְקֵר\">הֶבְקֵר</a>) m. (<a href=\"#\" data-headword=\"פָּקַר\">פָּקַר</a>) <i>declaring free, renunciation of ownership</i> in favor of whosoever would take possession of the object renounced; <i>confiscation; public property.</i> <span class=\"citation\">Eduy. IV, 3</span> הפ׳ לעניים הפ׳ Ms. M. (ed. <span dir=\"rtl\">הב׳</span>, v. Rabb. D. S. a. l. note) renunciation of ownership (of the standing crop) in favor of the poor is valid (exempting from tithes); (oth. opin.) <span dir=\"rtl\">אינו ה׳ עד שיפקיר וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">שיובקר</span>) it is not valid unless the owner makes it free for the rich, too; <span class=\"citation\">Peah IV, 1</span> (v. Rabb. D. S. a. l.); <span class=\"citation\">B. Mets. 30ᵇ</span> <a href=\"#\" data-headword=\"פְּקוֹלִי\">הפ׳</a>. <span class=\"citation\">Yeb. 89ᵇ</span>; <span class=\"citation\">Gitt. 36ᵇ</span> <span dir=\"rtl\">ה׳ ב&quot;ד ה׳</span> the confiscation by the court (disposing of private property by the process of law) is valid; Y. Shek. I, 46ᵃ bot. <span dir=\"rtl\">הב׳</span>. <span class=\"citation\">Peah I, 6</span> <span dir=\"rtl\">ונותן משום ה׳</span> or he may set aside a portion of his crop as public property. Y. ib. III, 17ᶜ bot. <span dir=\"rtl\">וה׳ חייב בפיאה</span> is public property ever subject to the laws of <i>Peah?</i> Ib. V, 19ᵇ <span dir=\"rtl\">אין הֶבְקֵירוֹ ה׳</span> his renunciation is ineffectual. Ib. <span dir=\"rtl\">אין ה׳ יוצא … אלא בזכייה</span> renounced property does not go out of the owner’s possession, until somebody takes possession of it; <span class=\"citation\">Y. Ned. IV, 38ᵈ</span> (corr. acc.). <span class=\"citation\">Y. Snh. VI, 23ᵇ</span>, beg. <span dir=\"rtl\">ה׳ טעות הוא</span> it is a confiscation under an erroneous presumption (and invalid); a. fr.—<span class=\"citation\">Gen. R. s. 80</span>, end <span dir=\"rtl\">בני אדם של ה׳</span> <i>outlaws</i>. <span class=\"citation\">Yeb. 66ᵃ</span> <span dir=\"rtl\">מנהג ה׳ נהגו בה</span> people took liberties with her (because she had neither the legal status of a freed woman nor that of a slave).</div>","alt":[]},"8213":{"h":"הֶפְקֵרָא","r":"E00760","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">פקר</span>, cmp. <a href=\"#\" data-headword=\"אַפְקָרוּתָא\">אַפְקָרוּתָא</a>) </div><div class=\"sense\"><b>1)</b> <i>unbridled lust, lawlessness</i>. <span class=\"citation\">Gitt. 13ᵃ</span> <span dir=\"rtl\">עבדא בה׳ ניחא ליה</span> a slave prefers the dissolute life with a slave (to regular marriage with a free woman); <span class=\"citation\">Keth. 11ᵃ</span></div><div class=\"sense\"><b>—2)</b>  as <a href=\"#\" data-headword=\"הֶפְקֵר\">preced.</a> word. <span class=\"citation\">B. Kam. 115ᵇ</span> <span dir=\"rtl\">מה׳ קא זכינא</span> (in securing the honey from a broken vessel on the road) I took possession of renounced goods.—<span class=\"citation\">Targ. Y. Deut. XXV, 5</span> <a href=\"#\" data-headword=\"הֶפְקֵרָא\">הֶפְקֵרָא</a> (<a href=\"#\" data-headword=\"הֶפְקֵרָא\">הֶפְקְרָא</a>) <i>an unprotected woman</i></div>","alt":["הֶפְקֵירָא"]},"8214":{"h":"הָפֵר","r":"E00761","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"פָּרַר\">פָּרַר</a>, <a href=\"#\" data-headword=\"פּוּר\">פּוּר</a>; fr. <span class=\"citation\">Num. XXX</span>, esp. verse 13) <i>the law of ‘hafer’, the husband’s</i> (or <i>father’s</i>) <i>right</i> of declaring void his wife’s (or <i>daughter’s</i>)<i> vow, invalidation</i>. <span class=\"citation\">Ned. X, 7</span>, a. fr. <span dir=\"rtl\">את שבא לכלל הקם בא לכלל ה׳</span> whatever comes under the law of <i>hakem</i> (confirmation), comes under the law of <i>hafer</i> (invalidation), i.e. as you cannot confirm a vow before it has been made, so you cannot invalidate a vow in advance. <span class=\"citation\">Ib. 69ᵃ</span>; <span class=\"citation\">79ᵃ</span> <span dir=\"rtl\">על הה׳</span> in a case where the right of invalidation might have been exercised. <span class=\"citation\">Tosef. ib. VII, 5</span> <span dir=\"rtl\">חומר בהקם שאינו בה׳</span> there are restrictions in the law of confirmation which do not apply to the law of invalidation &amp;c. Y. ib. X, 42ᵃ bot. <span dir=\"rtl\">ה׳ נדרים מעת לעת</span>, v. <a href=\"#\" data-headword=\"הֲפָרָה\">next w.</a>; a. fr. [In comment. our w. is spelled <span dir=\"rtl\">הפר</span> and <a href=\"#\" data-headword=\"הֵיפֵר\">הֵיפֵר</a> indiscriminately, which would intimate that it is pronounced <a href=\"#\" data-headword=\"פָּרַר\">הֵפֵר</a>, fr. <span class=\"citation\">Num. XXX, 9</span>.]</div>","alt":[]},"8215":{"h":"הֲפָרָה","r":"E00762","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָפֵר\">preced.</a>) <i>invalidation, declaring void;</i> also <i>absolution for cause</i> (v. <a href=\"#\" data-headword=\"הַתָּרָה\">הַתָּרָה</a>). <span class=\"citation\">Ned. X, 8</span> <span dir=\"rtl\">הֲפָרַת נדרים כל היום</span> the right (of the father or the husband) to declare a vow void lasts the whole day on which it came to his notice (to sunset); Y. ib. 42ᵃ bot. <span dir=\"rtl\">הפר נדרים מעת לעת</span> twenty four hours; <span class=\"citation\">Tosef. ib. VI, 1</span>; <span class=\"citation\">Sabb. 157ᵃ</span>.—<span class=\"citation\">Ned. 87ᵇ</span> <span dir=\"rtl\">מה הקמה ממנו אף ה׳ ממנו</span> as the confirmation may be partial, so may the invalidation &amp;c.; a. fr.—<span class=\"citation\">Gitt. 36ᵃ</span> <span dir=\"rtl\">אין לו ה׳</span> cannot be absolved from. <span class=\"citation\">Shebu. 29ᵇ</span> top <span dir=\"rtl\">כי היכי … ה׳</span> in order to make absolution impossible.</div>","alt":[]},"8216":{"h":"הִפַּרְכָא","r":"E00763","html":"<div class=\"sense\"> (not <a href=\"#\" data-headword=\"פְּקוֹלִי\">הַפַּ׳</a>) m. (ὕπαρχος) </div><div class=\"sense\"><b>1)</b> <i>governor, lieutenant</i>.—Pl. <span dir=\"rtl\">הִפַּרְכִין</span>, <span dir=\"rtl\">הִפַּרְכֵי</span>, <a href=\"#\" data-headword=\"הָדַר\">הִי׳</a>. <span class=\"citation\">Targ. Esth. III, 12</span>.—<span class=\"citation\">Ab. Zar. 8ᵇ</span></div><div class=\"sense\"><b>—2)</b> <i>subject</i> (<i>land</i>), <i>colony</i>. <span class=\"citation\">Targ. Esth. X, 1</span> <span dir=\"rtl\">הִפַּרְכֵי ימא</span> (h. text <span dir=\"rtl\">אִיֵי הים</span>); <span class=\"citation\">Targ. Y. Gen. XLIX, 13</span>.</div>","alt":["הִיפַּ׳"]},"8217":{"h":"הִפַּרְכוֹס","r":"E00764","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הִפַּרְכָא\">same</a>, <i>lieutenant</i>. <span class=\"citation\">Ex. R. s. 18</span>, beg. <span class=\"citation\">Yalk. Ps. 875</span> (to <span class=\"citation\">Ps. CXVI, 15</span>) [read:] <span dir=\"rtl\">משל למלך ששלח ה׳</span> (v. Midr. Till. to Ps. l. c.); a. e. [Ib. <span dir=\"rtl\">ה׳ אחרת</span>, read <a href=\"#\" data-headword=\"הִפַּרְכְיָא\">הפרכיא</a> (v. <a href=\"#\" data-headword=\"הִפַּרְכְיָא\">next w.</a>).—<span class=\"citation\">Midr. Till. to Ps. XVII</span> <span dir=\"rtl\">בהפרכוס</span>, some ed. <span dir=\"rtl\">בא ה׳</span>, v. <a href=\"#\" data-headword=\"אַפֹּופְסִין\">אַפּוֹפְסִין</a>.]—Pl. <span dir=\"rtl\">הִפַּרְכִין</span>, <a href=\"#\" data-headword=\"הָדַר\">הִי׳</a>. Tosef. Gitt. VIII (VI), 3 <span dir=\"rtl\">לשום היפרכון</span> (corr. acc.). V. <a href=\"#\" data-headword=\"אִיפַּרְכוֹס\">אִיפַּרְכוֹס</a>.</div>","alt":["הִי׳"]},"8218":{"h":"הִפַּרְכְיָא","r":"E00765","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ὑπαρχία) <i>lieutenancy, provincial government, province</i>. <span class=\"citation\">Sifré Deut. 330</span>; <span class=\"citation\">Yalk. ib. 946</span> [read:] <span dir=\"rtl\">היפטיקוס נכנס לתוך ה׳ שלו אם יכול ליפרע מכל הוא נפרע ואם לאו וכ׳</span> a consul enters his province; if he is able to collect (taxes) from all &amp;c. <span class=\"citation\">Yalk. Ps. 875</span> <span dir=\"rtl\">הפרכוס אחרת</span> (corr. acc.; v. <a href=\"#\" data-headword=\"הִפַּרְכוֹס\">preced.</a>)—Pl. <span dir=\"rtl\">הִפַּרְכִיּוֹת</span>, <a href=\"#\" data-headword=\"הָדַר\">הִי׳</a>. Tosef. Gitt. VIII (VI), 3 ed. Zuck. (v. <a href=\"#\" data-headword=\"הורכיינוס\">הורכיינוס</a>).</div>","alt":["הִפַּרְכְיָה","הִי׳"]},"8219":{"h":"הפרניא","r":"E00766","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַרְפַּנְיָא\">הַרְפַּנְיָא</a></div>","alt":[]},"8220":{"h":"הֶפְרֵשׁ","r":"E00767","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a>) <i>difference</i>. <span class=\"citation\">Sabb. 155ᵇ</span> <span dir=\"rtl\">ומה ה׳ בין וכ׳</span> and what is the difference between the two? <span class=\"citation\">Pes. 27ᵇ</span> <span dir=\"rtl\">אמר להן ה׳</span> said he to them, There is a difference; a. fr.</div>","alt":[]},"8221":{"h":"הַפְרָשָׁה","r":"E00768","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפְרָשָׁה\">אַפְרָשָׁה</a></div>","alt":[]},"8222":{"h":"הֶפְשֵׁט","r":"E00769","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּשַׁט\">פָּשַׁט</a>) <i>stripping, flaying</i>. <span class=\"citation\">Zeb. V, 4</span> <span dir=\"rtl\">טעונה ה׳ ונתוח</span> requires flaying and carving (<span class=\"citation\">Lev. I, 6</span>). Ib. 50ᵇ carving <span dir=\"rtl\">שלא בה׳</span> without previous flaying. <span class=\"citation\">Y. Pes. VI, 33ᵃ</span> bot. <a href=\"#\" data-headword=\"הֶפְשֵׁיט\">הֶפְשֵׁיטוֹ</a> the flaying of it; a. fr.</div>","alt":[]},"8223":{"h":"הַפְשָׁטָה","r":"E00770","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"הֶפְשֵׁט\">same</a>. <span class=\"citation\">Sabb. 116ᵇ</span> <span dir=\"rtl\">קודם הַפְשָׁטַת העור</span> before the hide (up to the chest) is stripped off. Sifra Vayikra, N’dabah, Par. 4, ch. VI (ref. to <span class=\"citation\">Lev. I, 6</span>) <span dir=\"rtl\">נתחים שהיו בכלל ה׳</span> such pieces as are affected by the order of flaying (to the exclusion of the head which is cut off before flaying); a. e.</div>","alt":[]},"8224":{"h":"הֶפְשֵׁיט","r":"E00771","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶפְשֵׁט\">הֶפְשֵׁט</a></div>","alt":[]},"8225":{"h":"הֶפְשֵׁר","r":"E00772","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּשַׁר I\">פָּשַר</a>) <i>making tepid, warming</i>. <span class=\"citation\">Sabb. 40ᵇ</span> <span dir=\"rtl\">הֶפְשֵׁרוֹ זהו בשולו</span> warming is to oil what cooking is to other liquids (a forbidden labor).</div>","alt":[]},"8226":{"h":"הֶפְתֵּיק","r":"E00773","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶפְתֵּק\">הֶפְתֵּק</a>, <a href=\"#\" data-headword=\"הֶפְתֵּיק\"><a href=\"#\" data-headword=\"הֶפְתֵּיק\">הֶפְתֵּקָא</a>.</a></div>","alt":["הֶפְתֵּיקָא"]},"8227":{"h":"הפתכו","r":"E00774","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Deut. 942</span>, read: <a href=\"#\" data-headword=\"הִיפָּטִיקוֹס\">הִיפָּטִיקוֹס</a>.</div>","alt":["הפתכי"]},"8228":{"h":"הֶפְתֵּק","r":"E00775","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (פתק <i>to cut, divide off;</i> Var. lect. v. infra) <i>the store-room</i> in the dwelling house out of which the daily portions of provision and work are distributed; also <i>the retailer’s shelves</i> &amp;c., contrad. to <a href=\"#\" data-headword=\"אוֹצָר\">אוצר</a> ware-house. <span class=\"citation\">Ab. Zar. II, 7</span> (<span class=\"citation\">39ᵇ</span>) <span dir=\"rtl\">הבאין מן הה׳</span> the preserved locusts which the merchant takes from the shelves, contrad. to <span dir=\"rtl\">מן הסלולה</span>, those laid out in baskets in front of the counter. <span class=\"citation\">Ab. Zar. 40ᵇ</span> <span dir=\"rtl\">מן הה׳ מן האוצר ומן הספינה</span> (not <span dir=\"rtl\">הסלולה</span>, v. Rabb. D. S. a. l. note 5); <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">V), 12</span> <span dir=\"rtl\">מן הפתק וכ׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"הֶפְתֵּיק\">הפתיק</a>, cmp. <a href=\"#\" data-headword=\"הֶמְסֵס\">הֶמְסֵס</a> for fusion of article) from the shelves, the ware-room or the ship.—<span class=\"citation\">Sabb. 50ᵃ</span>; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 19</span> <span dir=\"rtl\">גיזי צמר של ה׳</span> cut wool stored in the pantry (intended for spinning; Rashi: from the merchant’s shelves). [Ar. s. v. <span dir=\"rtl\">אפתק</span> reads: <a href=\"#\" data-headword=\"אוּפְתֵּיק\">אוּפְתֵּק</a>, noting a Var. <a href=\"#\" data-headword=\"ה׳\">ה׳</a>. One Ms. Ar., a. Mish. ed. Nap. read <a href=\"#\" data-headword=\"אפותיק\">אפותיק</a> for <a href=\"#\" data-headword=\"אוּפְתֵּיק\">אוּפְתֵּיק</a>, induced by phonetic resemblance to ἀποθήκη. V. Ar. ed. Koh. s. v. <span dir=\"rtl\">אפתק</span>, a. Rabb. D. S. to <span class=\"citation\">Ab. Zar. 39ᵇ</span> note 8.]</div>","alt":[]},"8229":{"h":"הַפְתֵּקָא","r":"E00776","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"הֶפְתֵּק\">preced.</a>) <i>treasury</i>. <span class=\"citation\">Targ. Y. Gen. XLVII, 14</span>. Ib. <span class=\"citation\">Deut. XXIII, 22</span> (constr.) <span dir=\"rtl\">בהַפְתֵּיק וכ׳</span> in the treasury of the Lord (v. <span class=\"citation\">Ḥull. 139ᵃ</span> quot. s. v. <a href=\"#\" data-headword=\"גִּזָּא\">גִּזָּא</a>).</div>","alt":["הַפְתֵּי׳","הֶיפְתֵּי׳"]},"8230":{"h":"הַפְתְּקָא","r":"E00777","html":"<div class=\"sense\"><i>ladle</i>, v. <a href=\"#\" data-headword=\"*אַפְתְּקָא\">אַפְתְּקָא</a>.</div>","alt":[]},"8231":{"h":"הפתקאות","r":"E00778","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"הִפּוֹתִּיקִי\">הִפּוֹתִּיקָאוֹת</a>; <span dir=\"rtl\">הפתקי</span>, read: <a href=\"#\" data-headword=\"הִפּוֹתִּיקִי\">הִפּוֹתִּיקִי</a>.</div>","alt":[]},"8232":{"h":"הצאתה","r":"E00779","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַצָּתָה\">הַצָּתָה</a></div>","alt":[]},"8233":{"h":"הַצָּבָה","r":"E00780","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">יצב</span>) <i>standing, use of the verb</i> <span dir=\"rtl\">יצב</span>. <span class=\"citation\">Num. R. s. 18</span>, beg.; Tanḥ. Koraḥ 3 (analogy betw. <span class=\"citation\">Num. XVI, 27</span> a. <span class=\"citation\">I Sam. XVII, 4</span>, a. <span class=\"citation\">16</span>). Pesik. Zutr. Nitsab. beg. <span dir=\"rtl\">יש ה׳ לטובה וכ׳</span> the word <span dir=\"rtl\">יצב</span> is sometimes used in a good sense (as firmness) and at times in a bad sense (as provocation); v. <a href=\"#\" data-headword=\"יְצִיבָה\">יְצִיבָה</a>.</div>","alt":[]},"8234":{"h":"הַצֶּלְבּוֹנִי","r":"E00781","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הצֶּלְפּוֹנִי\">הצֶּלְפּוֹנִי</a></div>","alt":[]},"8235":{"h":"הַצָּלָה","r":"E00782","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rescue, relief</i>. <span class=\"citation\">Meg. 16ᵇ</span> <span dir=\"rtl\">הצָּלַת נפשות</span> saving of human lives. <span class=\"citation\">Gitt. 56ᵃ</span> (in Chald. diction) <span dir=\"rtl\">אפשר דהוי ה׳ פורתא</span> may be some little relief (by royal favor) can be had; <span class=\"citation\">ib.ᵇ</span> <span dir=\"rtl\">וה׳ פורתא נמי וכ׳</span> and even a little favor will not be shown. <span class=\"citation\">Ḥull. 52ᵇ</span> <span dir=\"rtl\">הצלת עצמה</span> the animal’s own effort to save itself; <span dir=\"rtl\">ה׳ אחרים</span> the human efforts to save the animal. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">ה׳ מים</span> saving from drowning; a. fr.</div>","alt":[]},"8236":{"h":"הַצְּלֶלְפּוֹנִי","r":"E00783","html":"<div class=\"sense\"> (b. h.) pr. n. f. <i>Hazzelelponi</i>, alleged name of Samson’s mother. <span class=\"citation\">Num. R. s. 10</span>; <span class=\"citation\">B. Bath. 91ᵃ</span> <a href=\"#\" data-headword=\"צְלֶלְפּוֹנִי\">צְלֶלְפּוֹנִית</a> ed. (Ms. R. <span dir=\"rtl\">הצללפונית</span>, Ms. R. <a href=\"#\" data-headword=\"צלולפונית\">צלולפונית</a>).</div>","alt":[]},"8237":{"h":"הצֶּלְפּוֹנִי","r":"E00784","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"הַצְּלֶלְפּוֹנִי\">preced.</a>), <span dir=\"rtl\">בני ה׳</span> prob. name fo <i>a family</i> settled in Babylonia. <span class=\"citation\">M. Kat. 22ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"הַצֶּלְבּוֹנִי\">הצלבוני</a>).</div>","alt":[]},"8238":{"h":"הַצְנֵעַ","r":"E00785","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <span dir=\"rtl\">צנע</span>) <i>chastity</i>. Pesik. Sos, p. 146ᵇ; <span class=\"citation\">Yalk. Job 906</span>; (<span class=\"citation\">Yalk. Gen. 93</span> <span dir=\"rtl\">הַצְנֵיעוּת</span>).</div>","alt":[]},"8239":{"h":"הַצָּעָה","r":"E00786","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָצַע\">יָצַע</a>) <i>making a couch, laying out of mattresses, carpets</i> &amp;c. <span class=\"citation\">Keth. 4ᵇ</span>, a. e. <span dir=\"rtl\">הַצָּעַת המטה</span> making the bed (for her husband). <span class=\"citation\">Yoma 69ᵃ</span> <span dir=\"rtl\">בה׳ שרי</span> for spreading under (to sit or lie on), garments of mixed materials (<a href=\"#\" data-headword=\"כִּלְאַיִם\">כלאים</a>) are permitted.—V. <a href=\"#\" data-headword=\"מַצָּע\">מַצָּע</a>.—Trnsf. <i>arrangement, structure, construction</i>. <span class=\"citation\">Ḥull. 49ᵇ</span> <span dir=\"rtl\">כך היא ה׳ של משנה וכ׳</span> the construction of the Mishnah (Boraitha) is as you stated, but reverse the first clause. <span class=\"citation\">Snh. 51ᵃ</span>; a. e.</div>","alt":[]},"8240":{"h":"הַצָּתָה","r":"E00787","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָצַת\">יָצַת</a>) <i>kindling</i>. <span class=\"citation\">Y. Sabb. II, beg. 4ᶜ</span> <span dir=\"rtl\">צריכה הצאתה ברוב וכ׳</span> (corr. acc.) must be kindled so that the larger portion be on fire, v. <a href=\"#\" data-headword=\"דֶּלֶק\">דֶּלֶק</a>. <span class=\"citation\">Y. Yoma II, 39ᶜ</span> top; Bab. <span class=\"citation\">ib. 24ᵇ</span> <span dir=\"rtl\">הַצָּתַת וכ׳</span></div>","alt":[]},"8241":{"h":"הַקְבָּלָה","r":"E00788","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">קבל</span>, v. <a href=\"#\" data-headword=\"קַבָּלָה I\">קַבָּלָה</a>), <span dir=\"rtl\">הַקְבָּלַת פָּנִים</span> <i>reception</i>. <span class=\"citation\">Shebu. 35ᵇ</span>; <span class=\"citation\">Sabb. 127</span> (Ms. M. <a href=\"#\" data-headword=\"קבלנית\">קַבָּלַת</a>) <span dir=\"rtl\">ה׳ פני שכינה</span> receiving the Divine Presence.</div>","alt":[]},"8242":{"h":"הֶקְדֵּישׁ","r":"E00789","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">קדש</span>) </div><div class=\"sense\"><b>1)</b> <i>that which is dedicated to a sacred purpose</i>, esp. <i>sacred</i> or <i>Temple property</i>. <span class=\"citation\">Yeb. 66ᵇ</span> bot., a. fr. <span dir=\"rtl\">ה׳ וכ׳</span> a pledged animal which the debtor dedicates as a sacrifice &amp;c., v. <a href=\"#\" data-headword=\"פָּקַע\">פָּקַע</a>. <span class=\"citation\">Gen. R. s. 60</span> <span dir=\"rtl\">ה׳ דמים</span>; <span class=\"citation\">Arakh. VIII, 7</span> <span dir=\"rtl\">ה׳ עילוי</span> dedication of the value of an object; opp. <span dir=\"rtl\">ה׳ מזבח</span> dedication for the altar (allowing no redemption). <span class=\"citation\">Ib. VII, 1</span> <span dir=\"rtl\">אין מחשבין חדשים לה׳</span> months are not counted for redeeming dedicated property, i.e. fractions of a year count for a year in favor of the treasury. <span class=\"citation\">Kidd. 2ᵇ</span> <span dir=\"rtl\">דאסר לה אכ&quot;ע כה׳</span> because (by betrothing her to himself) he makes her forbidden to all other men like sacred property (v. <a href=\"#\" data-headword=\"קָדַשׁ\">קָדַשׁ</a>). <span class=\"citation\">Taan. 24ᵃ</span> <span dir=\"rtl\">הרי הן ה׳ עליך וכ׳</span> they shall be to thee sacred property (like charity funds); a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>dedication</i>. <span class=\"citation\">Arakh. 2ᵃ</span>; <span class=\"citation\">Tem. 2ᵃ</span> <span dir=\"rtl\">תחלת ה׳</span> a preliminary act of dedication, <span dir=\"rtl\">סוף ה׳</span> the final dedication (laying hands on the animal’s head prior to sacrificing it). <span class=\"citation\">Ib. 9ᵇ</span>; <span class=\"citation\">B. Mets. 54ᵇ</span> <span dir=\"rtl\">ה׳ ראשון</span> the original dedication, <span dir=\"rtl\">ה׳ שני</span> the substitution (for an animal which became defective); a. fr.—Pl. <span dir=\"rtl\">הֶקְדֵּישׁוֹת</span>, <a href=\"#\" data-headword=\"הֶקְדֵּישׁ\">הֶקְדֵּשׁ׳</a> 1) <i>sacred objects</i>. <span class=\"citation\">Lev. R. s. 5</span>; a. fr.—2) <i>laws concerning dedication</i>. Tosef. Erub. XI (VIII), 24; ib. <span class=\"citation\">Ḥag. I, 9</span> (ed. Zuck. <span dir=\"rtl\">והקרקעות</span>, corr. acc.); a. e.</div>","alt":["הֶקְדֵּשׁ"]},"8243":{"h":"הַקָּזָה","r":"E00790","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נקז</span>) <i>letting blood, opening a vein</i>. <span class=\"citation\">Ker. V, 1</span> <span dir=\"rtl\">דם ה׳ שהנפש יוצאה בו</span> the blood of arteries with which life goes out, i.e. the splashing blood; <span class=\"citation\">ib. 22ᵃ</span>. <span class=\"citation\">Nidd. 19ᵇ</span>.—<span class=\"citation\">Gitt. 70ᵃ</span> <span dir=\"rtl\">הַקָּזַת דם</span> blood-letting. <span class=\"citation\">Sabb. 29ᵃ</span> סעודת ה׳ Ms. M. (ed. <span dir=\"rtl\">ה׳ דם</span>) the meal taken after blood-letting; a. fr.</div>","alt":[]},"8244":{"h":"הֶקְטֵר","r":"E00791","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָטַר I\">קטר</a>) <i>letting rise in smoke, burning on the altar</i>. <span class=\"citation\">Ber. I, 1</span>; a. fr.</div>","alt":[]},"8245":{"h":"הַקְטָרָה","r":"E00792","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֶקְטֵר\">same</a>. <span class=\"citation\">Y. Pes. VII, 34ᶜ</span> top. <span class=\"citation\">Y. Yoma II, 39ᶜ</span>; a. e.—Pl. <span dir=\"rtl\">הַקְטָרוֹת</span>. <span class=\"citation\">Tosef. Dem. II, 7</span> <span dir=\"rtl\">הה׳</span>; <span class=\"citation\">Men. 18ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"קַפָּר\">הק׳</a>); <span class=\"citation\">Ḥull. 132ᵇ</span> <a href=\"#\" data-headword=\"קַפָּר\">הק׳</a> (v. <a href=\"#\" data-headword=\"הֶמְסֵס\">הֶמְסֵס</a> as to fusion of article).</div>","alt":[]},"8246":{"h":"הֶקֵּיף","r":"E00793","html":"<div class=\"sense\">, v. <span dir=\"rtl\">הֶיקֵּ׳</span></div>","alt":["הֶקֵּיפָא"]},"8247":{"h":"הֶקֵּישׁ","r":"E00794","html":"<div class=\"sense\">, v. <span dir=\"rtl\">הֶיקֵּ׳</span></div>","alt":["הֶקֵּישָׁא"]},"8248":{"h":"הָקֵם","r":"E00795","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"קוּם\">קוּם</a>, formed for analogy with <a href=\"#\" data-headword=\"הָפֵר\">הָפֵר</a> q. v.) <i>confirmation, the privilege of confirming a vow</i>. <span class=\"citation\">Ned. X, 7</span>; a. fr. (comment. write indiscriminately <a href=\"#\" data-headword=\"הָקֵם\">הקם</a> a. <a href=\"#\" data-headword=\"הֵיקֵם\">הֵיקֵם</a>, analogous to <a href=\"#\" data-headword=\"הֵיפֵר\">הֵיפֵר</a>).</div>","alt":[]},"8249":{"h":"הֲקָמָה","r":"E00796","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">קום</span>) </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"הָקֵם\">same</a>. <span class=\"citation\">Ned. 69ᵃ</span> <span dir=\"rtl\">ה׳ ראשונה</span> the first confirmation (when he said the first <span dir=\"rtl\">קיים ליכי</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ולא תיחול ה׳</span> but my confirmation shall not take effect; a. e.</div><div class=\"sense\"><b>—2)</b> <i>erection</i>. <span class=\"citation\">R. Hash. 2ᵇ</span> <span dir=\"rtl\">להֲקָמַת המשכן</span> dating from the erection of the Tabernacle. Y. Yoma I, 38ᶜ top; <span class=\"citation\">Num. R. s. 12</span>, a. e. <span dir=\"rtl\">ה׳ הלילה</span> the putting up (of the Tabernacle) by night; a. e.—Pl. <span dir=\"rtl\">הֲקָמוֹת</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הֲקָמוֹתָיו</span> his repeated acts of putting up.</div>","alt":[]},"8250":{"h":"הֲקְנָאָה","r":"E00797","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"אַקְנָיָיתָא\">אַקְנָיָיתָא</a></div>","alt":[]},"8251":{"h":"הֶקֵּף","r":"E00798","html":"<div class=\"sense\">, v. <span dir=\"rtl\">הֶיקֵּ׳</span></div>","alt":["הֶקֵּפָא"]},"8252":{"h":"הַקְפָּדָה","r":"E00799","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְפָּדָה\">אַקְפָּדָה</a></div>","alt":[]},"8253":{"h":"הַקָּפָה","r":"E00800","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (נָקַף II) </div><div class=\"sense\"><b>1)</b> <i>surrounding, going round</i>. <span class=\"citation\">Yoma 59ᵃ</span> <span dir=\"rtl\">ה׳ ברגל</span> the sprinkling was done in walking around; <span dir=\"rtl\">ה׳ ביד</span> by circular movements of the hand. <span class=\"citation\">Pesik. R. s. 41</span> <span dir=\"rtl\">הַקָּפַת המזבח</span> going around the altar in procession with the Lulab; a. e.</div><div class=\"sense\"><b>—2)</b>  (ref. to <span class=\"citation\">Lev. XIX, 27</span>) <i>shaving the hair of the head all around</i>. <span class=\"citation\">Naz. 29ᵃ</span> <span dir=\"rtl\">ועביד ה׳</span> and he (the Nazir) may shave &amp;c. Ib. <span dir=\"rtl\">הַקָּפַת כל הראש</span> shaving the entire head, opp. to <span dir=\"rtl\">ה׳ פאה</span> shaving the ends, v. <a href=\"#\" data-headword=\"פֵּאָה\">פֵּאָה</a>. <span class=\"citation\">Y. Sot. II, beg. 17ᵈ</span> <span dir=\"rtl\">ה׳ נזירות</span> the shaving required by Nazir laws (<span class=\"citation\">Num. VI, 18</span>); a. e.</div><div class=\"sense\"><b>—3)</b> <i>growth of hair around a limb</i>. <span class=\"citation\">Y. Yeb. X, end, 11ᶜ</span>; <span class=\"citation\">Snh. 68ᵇ</span></div><div class=\"sense\"><b>—4)</b> <i>debts for merchandise</i> payable at certain seasons (cmp. <a href=\"#\" data-headword=\"תְּקוּפָה\">תְּקוּפָה</a>). <span class=\"citation\">Shebi. X, 1</span>; <span class=\"citation\">Tosef. ib. VIII, 3</span> <span dir=\"rtl\">הקפת חנות וכ׳</span> shop-debts are not subject to the law of limitation in the Sabbatical year.—Pl. <span dir=\"rtl\">הַקָּפוֹת</span>. <span class=\"citation\">Gen. R. s. 41</span> he came back <span dir=\"rtl\">לפרוע הַקָּפוֹתָיו</span> to pay his debts; <span class=\"citation\">Yalk. ib. 69</span>.</div>","alt":[]},"8254":{"h":"הֲקָצה I","r":"E00801","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קִיץ\">קִיץ</a>) <i>waking up</i>. <span class=\"citation\">Midr. Till. to Ps. XVII, 15</span> <span dir=\"rtl\">הֲקָצַת המתים</span> resurrection of the dead.</div>","alt":[]},"8255":{"h":"הֲקָצָה II","r":"E00802","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קוּץ\">קוּץ</a>, <a href=\"#\" data-headword=\"קָצַץ\">קָצַץ</a>) <i>cutting</i>, <span dir=\"rtl\">הֲקָצַת שפתים</span> (cmp. <span class=\"citation\">Prov. XVI, 30</span>) cutting the lips, i.e. contracting the mouth for a blasphemous expression. <span class=\"citation\">Snh. 65ᵃ</span> Ar. a. Ms. K. (ed. <span dir=\"rtl\">עקימת</span>, v. <a href=\"#\" data-headword=\"עֲקִימָה I\">עֲקִימָה</a>).</div>","alt":[]},"8256":{"h":"הָקֵר","r":"E00803","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"קוֹר I\">קוּר</a>; cmp. <span class=\"citation\">Jer. VI, 7</span>) <i>welling, pouring forth</i> (cmp. <a href=\"#\" data-headword=\"מָקוֹר\">מָקוֹר</a>). (<a href=\"#\" data-headword=\"בּוּר\">בּוֹר</a>) <span dir=\"rtl\">בְּאֵר ה׳</span> <i>well</i>, opp. to cistern; esp. <i>B’er Haker</i> name of a certain well. <span class=\"citation\">Erub. X, 14</span>. <span class=\"citation\">Ib. 104ᵇ</span> כל הבורות ה׳ Ms. M. (ed. incorr. <span dir=\"rtl\">הקרות</span>); Y. ib. II, beg. 20ᵃ</div>","alt":[]},"8257":{"h":"הַקְרָבָה","r":"E00804","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרֵב\">קָרַב</a>) </div><div class=\"sense\"><b>1)</b> <i>offering</i>, use of the verb <a href=\"#\" data-headword=\"קָרֵב\">הִקְרִיב</a>. <span class=\"citation\">Men. 11ᵃ</span> <span dir=\"rtl\">בת ה׳ היא</span> it is an object which may eventually be offered. <span class=\"citation\">B. Kam. 12ᵇ</span> <span dir=\"rtl\">חזי לה׳</span> fit for offering (if the Temple existed). <span class=\"citation\">Erub. 63ᵇ</span>, a. e. <span dir=\"rtl\">גדול … מהקְרָבַת תמידין</span> study of the Law is more important than the offering of daily sacrifices. <span class=\"citation\">Lev. R. s. 2</span>, end <span dir=\"rtl\">נאמר ה׳ וכ׳</span> the term <a href=\"#\" data-headword=\"קָרֵב\">הקריב</a> is used &amp;c. <span class=\"citation\">Lev. R. s. 20</span> they died <span dir=\"rtl\">על הקריבה ועל ה׳</span> (= <span dir=\"rtl\">הַהַ׳</span>) for coming near (<span class=\"citation\">Lev. XVII, 1</span>) and for offering (<span class=\"citation\">Lev. X, 1</span>); a. fr.</div><div class=\"sense\"><b>2)</b> <i>drawing nigh for attack</i>. <span class=\"citation\">Ex. R. s. 21</span> <span dir=\"rtl\">הקרבת פרעה</span> (<span class=\"citation\">Ex. XIV, 10</span>).</div>","alt":[]},"8258":{"h":"הַקְרָיָה","r":"E00805","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (קָרָה Hif.) <i>preparation, arrangement</i>. Sifra Num. 159; Yalk. ib. 787 (interpret. <span dir=\"rtl\">הקריתם</span>, <span class=\"citation\">Num. XXXV, 11</span>).</div>","alt":["הַקְרָיָיה"]},"8259":{"h":"הֶקֵּשׁ","r":"E00806","html":"<div class=\"sense\">, v. <span dir=\"rtl\">הֶיקֵּ׳</span></div>","alt":[]},"8260":{"h":"הַקָּשָׁה","r":"E00807","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>) <i>clapping, knocking together</i>. <span class=\"citation\">Snh. 65ᵃ</span> <span dir=\"rtl\">הַקָּשַׁת זרועותיו</span> the clapping of his (the necromancer’s) arms; <span class=\"citation\">Ker. 3ᵇ</span>.—Pl. <span dir=\"rtl\">הַקָּשֹׁות</span>. <span class=\"citation\">Ib.</span> (Snh. l. c. always sing.).</div>","alt":[]},"8261":{"h":"הַר","r":"E00808","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>mound, mountain;</i> trnsf. <i>eminent person.</i> <span class=\"citation\">Midd. II, 1</span>, a. fr. <span dir=\"rtl\">הַר הבית</span> the Temple mount. <span class=\"citation\">Yeb. 17ᵃ</span> (play on <span dir=\"rtl\">ה̇ר̇פ̇נ̇יא</span>) <span dir=\"rtl\">ה̇ר̇ שהכל פ̇ונ̇ין בו</span> a hill to which all turn (whose spurious descent prevents them from getting wives elsewhere); a. v. fr.—<span class=\"citation\">Ḥull. 39ᵇ</span> (in Chald. diction) <span dir=\"rtl\">רישיך והר</span> here is thy head and here the mountain (a colloquial phrase for compelling one to give up a bargain).—<span class=\"citation\">Ex. R. s. 28</span> (ref. to <span class=\"citation\">Ex. XIX, 3</span>) <span dir=\"rtl\">בזכות הה׳</span> for the merit of the distinguished one (Abraham), <span dir=\"rtl\">ואין הה׳ אלא אבות</span> <i>har</i> means the patriarchs (ref. to <span class=\"citation\">Mic. VI, 2</span>). <span class=\"citation\">Snh. 107ᵃ</span> <span dir=\"rtl\">ה׳ שבכם</span> the most prominent of you; a. fr.—[For proper nouns composed with <a href=\"#\" data-headword=\"הַר\">הר</a>, v. respective determinants.]—Pl. <a href=\"#\" data-headword=\"רוּם\">הָרִים</a>, <a href=\"#\" data-headword=\"הֶרֶר\">הֲרָרִים</a>. <span class=\"citation\">Tam. 32ᵃ</span>, a. e. <span dir=\"rtl\">הָרֵי חושך</span>, v. <a href=\"#\" data-headword=\"חוֹשֶׁךְ\">חו̇שֶׁךְ</a>.—<span class=\"citation\">Snh. 24ᵃ</span> <span dir=\"rtl\">עוקר הרי הרים</span> uprooting the highest mountains (a figure for dialectical ingenuity). <span class=\"citation\">Y. Yeb. I, 3ᵃ</span> bot. <span dir=\"rtl\">בין שני הֶהָ׳ וכ׳</span> between the two high mountains (great scholars). <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">ואין ה׳ אלא אבות</span>, v. supra.—<span class=\"citation\">Ḥag. I, 8</span> <span dir=\"rtl\">כה׳ תלויין בשערה</span> like mountains suspended on a hair (a slender Bible text for numerous Talmudic laws); a. v. fr.</div>","alt":["(הֶרֶר)"]},"8262":{"h":"הֲרָא","r":"E00809","html":"<div class=\"sense\">, <i>Af</i>. <a href=\"#\" data-headword=\"הֲלִי\">אַהֲרֵי</a> (cmp. <a href=\"#\" data-headword=\"חרי\">חרי</a>, <span dir=\"rtl\">חרר</span>) <i>to heat, irritate</i>. <span class=\"citation\">Targ. Prov. XXV, 20</span> <span dir=\"rtl\">מַהֲרָא</span> (Var. <a href=\"#\" data-headword=\"מְהֵרָה\">מַהְרָה</a>) ed. Lag. (ed. <a href=\"#\" data-headword=\"מְחַר\">מחרא</a>, ed. Wil. <span dir=\"rtl\">מחדא</span>, corr. acc.); v. <a href=\"#\" data-headword=\"בַּרְיוּתָא\">בּרְיוּתָא</a>.—Cmp. <a href=\"#\" data-headword=\"הִרְהֵר\">הִרְהֵר</a>, <a href=\"#\" data-headword=\"חִרְחֵר\">חִרְחֵר</a>.</div>","alt":[]},"8263":{"h":"הַרְבָּה","r":"E00810","html":"<div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"רָבָה\">רָבָה</a>) <i>to increase; the numerical value of the letters</i> <span dir=\"rtl\">ה̇ר̇ב̇ה̇</span> = 212 (days). <span class=\"citation\">Gen. R. s. 20</span> (play on <span dir=\"rtl\">הרבה ארבה</span>, <span class=\"citation\">Gen. III, 16</span>) <span dir=\"rtl\">כל שהוא ה׳ ארבה וכ׳</span> if an embryo is 212 days old, I shall cause it to grow (it is vital); <span class=\"citation\">Y. Nidd. I, 49ᵇ</span> top <span dir=\"rtl\">כל שהוא בה׳ הרי הוא בארבה</span>; v. <a href=\"#\" data-headword=\"אל\">אל&quot;ף</a>.</div>","alt":[]},"8264":{"h":"הַרְבָּעָה","r":"E00811","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָבַע\">רָבַע</a>) <i>the </i>(<i>forbidden</i>)<i> coupling of heterogeneous animals</i>. <span class=\"citation\">Snh. 56ᵇ</span> <span dir=\"rtl\">הַרְבָּעַת בהמה</span>; Sifra Aḥaré Par. 9, ch. XIII. <span class=\"citation\">Ḥull. 71ᵃ</span> <span dir=\"rtl\">לה׳</span> with reference to forbidden coupling; a. e.</div>","alt":[]},"8265":{"h":"הָרַג","r":"E00812","html":"<div class=\"sense\"> (b. h.) [<i>to cut</i>, v. <a href=\"#\" data-headword=\"הֶרֶג\">הֶרֶג</a>,] <i>to kill, put to death</i>. <span class=\"citation\">Num. R. s. 21</span>, beg. <span dir=\"rtl\">בא לַהֲרָגְךָ השכם להָרְגֹּו</span> if one comes to kill thee, be the first to kill him; <span class=\"citation\">Ber. 58ᵃ</span>; <span class=\"citation\">Snh. 72ᵃ</span> <span dir=\"rtl\">להוֹרְגְּךָ … להוֹרְגוֹ</span>. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">כסבור ה׳ את עצמו</span> he (Titus) thought he had killed himself (euphem. for <i>the Lord</i>); a. v. fr.—<i>Part. pass</i>. <span dir=\"rtl\">הָרוּג</span>. <span class=\"citation\">Tosef. Gitt. V</span> (<span class=\"citation\">III), 1</span> <span dir=\"rtl\">הֲרוּגִין שנהרגו לפני מלחמה ובשעת מלחמה</span> (ed. Zuck. <span dir=\"rtl\">בשעת</span>) those executed (by the Roman government) before and during the Vespasian war; <span class=\"citation\">Y. Gitt. V, 47ᵇ</span> top [read:] <span dir=\"rtl\">הֲרוּגֵי המלחמה ולפני וכ׳</span>. <span class=\"citation\">Y. Ber. I, 3ᵈ</span>, v. <a href=\"#\" data-headword=\"בִּיתֵּר\">בִּיתֵּר</a>. <span class=\"citation\">Pes. 50ᵃ</span>; <span class=\"citation\">B. Bath. 10ᵇ</span>, a. e. <span dir=\"rtl\">הרוגי מלכות</span> martyrs under the Roman government (R. Akiba and his fellow-martyrs), v. <a href=\"#\" data-headword=\"לוּד\">לוּד</a>; a. fr.</div><div class=\"sense\"><b>Nif. נֶהֱרַג</b> <div class=\"sense\"><i>to be killed, executed</i>. <span class=\"citation\">Taan. 18ᵇ</span> <span dir=\"rtl\">נֶהֶרְגוּ</span> were put to death (by the Roman government). <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">יֵהָרֵג</span> is to be put to death. <span class=\"citation\">Snh. 74ᵃ</span> <span dir=\"rtl\">עבור ואל תֵּהָרֵג</span> transgress or thou wilt be killed; a. fr.</div></div>","alt":[]},"8266":{"h":"הָרָג","r":"E00813","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָרַג\">preced.</a>) <i>murderer, highway-man</i>, contrad. to <span dir=\"rtl\">חרם</span> the oppressor who does not threaten to kill. <span class=\"citation\">Y. B. Mets. IV, end, 9ᵈ</span>.—Pl. <span dir=\"rtl\">הָרָגִין</span>. <span class=\"citation\">Ned. III, 4</span>, v. <a href=\"#\" data-headword=\"נָדַר\">נָדַר</a>.</div>","alt":[]},"8267":{"h":"הֶרֶג","r":"E00814","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הָרָג\">preced.</a> wds.) <i>execution by decapitation with a sword</i>. <span class=\"citation\">Snh. VII, 1</span>; a. fr.</div>","alt":[]},"8268":{"h":"הַרְגֹּוז","r":"E00815","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. = <a href=\"#\" data-headword=\"אַרְגָּז\">אַרְגָּז</a> q. v.) euphem. for <i>buttocks</i> (or <i>testicles</i>). <span class=\"citation\">Bekh. VI, 6</span> הַרְגִּיזוֹ Maim., Ar. Var. <a href=\"#\" data-headword=\"הַרְגֹּוז\">הַרְגֹּוזוֹ</a>, ed. <a href=\"#\" data-headword=\"*אָכוּז\">אָכוּז</a> q. v.</div>","alt":["הַרְגֵּיז"]},"8269":{"h":"הַרְגִּינִּין","r":"E00816","html":"<div class=\"sense\">, v. <span dir=\"rtl\">חַרְגִּ׳</span></div>","alt":[]},"8270":{"h":"הֶרְגֵּל","r":"E00817","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רגל</span>, v. <a href=\"#\" data-headword=\"רָגִיל\">רָגִיל</a>) </div><div class=\"sense\"><b>1)</b> <i>habit;</i> <span dir=\"rtl\">ה׳ לשון</span> habit of the tongue, fluency acquired by memorizing. habit of the tongue, fluency acquired by memorizing. <span class=\"citation\">Koh. R. to VI, 9</span>.</div><div class=\"sense\"><b>—2)</b> <i>leading to, occasion for</i>. <span dir=\"rtl\">מפני ה׳ עבירה</span> because it offers an occasion for sin. <span class=\"citation\">Sabb. I, 3</span>; <span class=\"citation\">Pes. 30ᵃ</span>; <span class=\"citation\">36ᵃ</span>; a. e.—<span class=\"citation\">Ab. Zar. 17ᵃ</span> <span dir=\"rtl\">ה׳ דבר</span> (euphem.) preliminaries of sexual connection.</div>","alt":[]},"8271":{"h":"הרגנא","r":"E00818","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְנוֹגָא\">חַרְנוֹגָא</a></div>","alt":[]},"8272":{"h":"הַרְגִּנִּין","r":"E00819","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְגִּינִּין\">חַרְגִּינִּין</a></div>","alt":[]},"8273":{"h":"הַרְגָּשָׁה","r":"E00820","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָגַשׁ\">רָגַשׁ</a>, Hif.) <i>sensation, perception, sensuous affection</i>. <span class=\"citation\">Nidd. 43ᵃ</span> <span dir=\"rtl\">נעקרה בה׳</span> he felt the effusion coming, <span dir=\"rtl\">ויצתה שלא בה׳</span> but the discharge was not perceived. <span class=\"citation\">Ib. 57ᵇ</span> <span dir=\"rtl\">הַרְגָּשַׁת מי וכ׳</span> the sensation of discharging urin; a. fr. <span class=\"citation\">Yalk. Jud. 42</span> <span dir=\"rtl\">לכל ה׳ וה׳</span> to every <i>sense</i>.—Pl. <span dir=\"rtl\">הַרְגָּשֹׁות</span> <i>senses</i>. <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">כנגד חמש ה׳ וחמש מורגשות</span> corresponding to the five senses and the five perceptions.</div>","alt":[]},"8274":{"h":"הַרְגַּת","r":"E00821","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְגָּא\">חַרְגָּא</a></div>","alt":[]},"8275":{"h":"הִרְדַּאוְלִיס","r":"E00822","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִרְדַּוְלִיס\">הִרְדַּוְלִיס</a></div>","alt":[]},"8276":{"h":"הַרְדּוּבְלִין","r":"E00823","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ὕδραυλις) <i>water-organ</i>. <span class=\"citation\">Targ. Ps. CL, 4</span> Ms. (Regia <span dir=\"rtl\">הרדיב׳</span>, ed. <a href=\"#\" data-headword=\"חֲלִיפִים\">חֲלִילִין</a>).</div>","alt":[]},"8277":{"h":"הִרְדַּוְלִיס","r":"E00824","html":"<div class=\"sense\"> m. <a href=\"#\" data-headword=\"הַרְדּוּבְלִין\">same</a>. <span class=\"citation\">Arakh. 10ᵇ</span> (not … <span dir=\"rtl\">לים</span>); <span class=\"citation\">Tosef. ib. I, 13</span> <span dir=\"rtl\">הרדאולים לא היו וכ׳</span> ed. Zuck. (corr. acc.; ed. <span dir=\"rtl\">הִדְרַאוְלִי׳ לא היה</span>); cmp. <a href=\"#\" data-headword=\"אִדְרַבְלִיס\">אִדְרַבְלִיס</a>.</div>","alt":[]},"8278":{"h":"*הִרְדּוּס","r":"E00825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <span dir=\"rtl\">דרס</span>, v. <a href=\"#\" data-headword=\"מִדְרָא\">מִדְּרָא</a>, <a href=\"#\" data-headword=\"מִדְרוֹן\">מִדְּרוֹן</a> &amp;c.) <i>the copulation of birds;</i> מעשה ה׳ <i>unnatural gratification on a woman’s body</i>. <span class=\"citation\">Snh. 66ᵇ</span> Ar. (ed. <span dir=\"rtl\">חידודין</span>; v. <a href=\"#\" data-headword=\"*הֲרוּרִים\">הֲרוּרִים</a>). [Ar.: <i>doing of Herod</i>, ref. to <span class=\"citation\">B. Bath. 3ᵇ</span>; v. <a href=\"#\" data-headword=\"הוֹרְדוֹס\">הוֹרְדֹּוס</a>.]</div>","alt":[]},"8279":{"h":"הִרְדּוּף","r":"E00826","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִירְדּוּף\">הִירְדּוּף</a></div>","alt":[]},"8280":{"h":"הִרְדֹּופָה","r":"E00827","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*הַרְדָּפָה\">הַרדָּפָה</a></div>","alt":[]},"8281":{"h":"הַרְדֹּופַנֵּי","r":"E00828","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַרְדַּפְנֵי\">הַרְדַּפְנֵי</a></div>","alt":[]},"8282":{"h":"הַרְדֹּופַנִּין","r":"E00829","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <a href=\"#\" data-headword=\"הַר\">הר</a> = <span dir=\"rtl\">חר</span>, a. <a href=\"#\" data-headword=\"דּוֹפָן\">דֹּופָן</a>; v. <a href=\"#\" data-headword=\"חַרְחֲבִינָא\">חַרְחֲבִינָה</a>) <i>wall-ivy</i>, the leaves of which may be used for bitter herbs on the Passover night. <span class=\"citation\">Pes. 39ᵃ</span> (Ms. M. <span dir=\"rtl\">הַרְרְּפַ׳</span>). V. <a href=\"#\" data-headword=\"הַרְדַּפְנֵי\">הַרְרַּפְנֵי</a>.</div>","alt":[]},"8283":{"h":"הַרְדְּסִיאוֹת","r":"E00830","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\">, <span dir=\"rtl\">יוני ה׳</span> <i>a species of domesticated doves</i> (prob. so named from the manner of their fructification, v. <a href=\"#\" data-headword=\"*הִרְדּוּס\">הִרְדּוּס</a>). <span class=\"citation\">Ḥull. XII, 1</span>; <span class=\"citation\">Bets. 25ᵃ</span>; <span class=\"citation\">Tosef. ib. I, 10</span>; <span class=\"citation\">Tosef. Ḥull. X, 9</span> <span dir=\"rtl\">הרד׳</span> ed. Zuck. (Var. <span dir=\"rtl\">הדר׳</span>). <span class=\"citation\">Ḥull. 139ᵇ</span> <span dir=\"rtl\">חד תני הדר׳ וחד תני הרד׳ וכ׳</span> one reads <i>hadr.</i>, and one reads <i>hard.</i>, the one deriving our w. from Herod, the other from the name of a place.</div>","alt":["הַרְדְּסִיֹּות","(הַדְרְסִ־)"]},"8284":{"h":"*הַרְדָּפָה","r":"E00831","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">הדף</span>, with <a href=\"#\" data-headword=\"ר\">ר</a> inserted; cmp. <a href=\"#\" data-headword=\"הִירְדּוּף\">הִירְדּוּף</a> [<i>removal, isolation</i>,] <i>imprisonment within a narrow enclosure of reeds or poles</i>, a punishment for contempt of court (v. <a href=\"#\" data-headword=\"נִידּוּי\">נִידּוּי</a>). <span class=\"citation\">M. Kat. 16ᵃ</span> (explain. <span dir=\"rtl\">לִשְׁרוֹשִׁי</span>, <span class=\"citation\">Ezra VII, 26</span>). Ib. (a version of the Gaonim quoted by Asheri a. l., Nr. 53) <span dir=\"rtl\">מאי ה׳ א&quot;ר פפא נצבי דקני</span> what is<i> hardafah?</i> Said R. P., Poles of reeds (fastened in the ground). [In ed. a. Mss. the answer to <span dir=\"rtl\">מאי ה׳</span> is absent.] [Ar. ed. Koh. <a href=\"#\" data-headword=\"הִרְדֹּופָה\">הִרְדֹּופָה</a>.]</div>","alt":[]},"8285":{"h":"הרדפוני","r":"E00832","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַרְדַּפְנֵי\">next w.</a></div>","alt":[]},"8286":{"h":"הַרְדַּפְנֵי","r":"E00833","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Chald. form of <a href=\"#\" data-headword=\"הַרְדֹּופַנִּין\">הַרְיֹּופַנִּין</a>) <i>a creeper</i> the berries of which were known to be injurious to animals. <span class=\"citation\">Ḥull. III, 5</span> (<span class=\"citation\">58ᵇ</span>); Tosef. ib. III, 19.—Mekh. B’shall., Vayassa 1 (ref. to <span class=\"citation\">Ex. XV, 25</span>) <span dir=\"rtl\">זה עץ ה׳</span> it was the trunk of an ivy; <span class=\"citation\">Ex. R. s. 50</span>; (ib. s. 23 <a href=\"#\" data-headword=\"ירדינון\">ירדינון</a>); Yalk. ib. 256 <a href=\"#\" data-headword=\"הרדפוני\">הרדפוני</a> (corr. acc.); Tanḥ. <span class=\"citation\">B’shall. 24</span> <span dir=\"rtl\">ה׳ מר היה</span>; Tanḥ., ed. Bub., ib. 19.—[Var. <a href=\"#\" data-headword=\"הירדופני\">הירדופני</a>, v. Koh. Ar. s. v.]—<span class=\"citation\">Targ. Y. Ex. XV, 25</span> <a href=\"#\" data-headword=\"אַרְדַּפְנֵי\">אַרְדַּפְנֵי</a>.</div>","alt":["הַרְדוֹפַנֵּי"]},"8287":{"h":"הַרְדְּפַנִּין","r":"E00834","html":"<div class=\"sense\">, v. <span dir=\"rtl\">הַרְדֹּופַ׳</span></div>","alt":[]},"8288":{"h":"הָרָה","r":"E00835","html":"<div class=\"sense\"> (b. h.) <i>to conceive, be with child</i>. <span class=\"citation\">Yalk. Ex. 168</span>, end. <span class=\"citation\">Y. B. Kam. V, 5ᵃ</span> top; Bab. <span class=\"citation\">B. Kam. 49ᵃ</span></div><div class=\"sense\"><b>Hof. הוֹרָה</b> <div class=\"sense\"><i>to be conceived;</i> *(homilet.) <i>conception</i>, v. <a href=\"#\" data-headword=\"הוֹרָת\">הוֹרָת</a>. <span class=\"citation\">Gen. R. s. 64</span>; <span class=\"citation\">Yalk. Job 894</span> that she would have said to him, <span dir=\"rtl\">ה׳ גבר</span> is this a time for conception, man? (‘Rashi’).</div></div>","alt":[]},"8289":{"h":"הִרְהוּן I","r":"E00836","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"הִרְהוּר\">הִירְ׳</a></div>","alt":[]},"8290":{"h":"הרְהוּן II","r":"E00837","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>urin-soaked dung</i>, v. <a href=\"#\" data-headword=\"דָּהוֹן\">דָּהוֹן</a> a. <a href=\"#\" data-headword=\"דְּהֵין\"><a href=\"#\" data-headword=\"דְּהֵין\">דְּהֵין</a>.</a></div>","alt":[]},"8291":{"h":"הִרְהוּר","r":"E00838","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הִרְהֵר\">הִרְהֵר</a>) </div><div class=\"sense\"><b>1)</b> <i>thought, meditation</i>, opp. <a href=\"#\" data-headword=\"דִּיבּוּר\">דיבור</a> loud recitation. <span class=\"citation\">Ber. 20ᵇ</span> <span dir=\"rtl\">ה׳ כדיבור דמי</span> reviewing in mind (a Biblical passage &amp;c.) is as good as loud recitation. <span class=\"citation\">Sabb. 150ᵃ</span> (ref. to <span class=\"citation\">Is. LVIII, 13</span>) <span dir=\"rtl\">דיבור אסור ה׳ וכ׳</span> talking (business on the Sabbath) is forbidden, thinking (planning) is permitted.</div><div class=\"sense\"><b>—2)</b> <i>heated imagination</i>, esp. <i>impure fancies</i>. <span class=\"citation\">Ber. 12ᵇ</span> <span dir=\"rtl\">ה׳ עבירה</span> unchaste imagination, <span dir=\"rtl\">ה׳ ע&quot;ז</span> idolatrous fancy. <span class=\"citation\">Nidd. 13ᵇ</span> <span dir=\"rtl\">המביא עצמו לידי ה׳</span> who allows sinful fancies to take a hold of him. <span class=\"citation\">Zab. II, 2</span>; a. fr.—Pl. <span dir=\"rtl\">הִרְהוּרִים</span>. <span class=\"citation\">Yoma 29ᵃ</span> top <span dir=\"rtl\">הִרְהוּרֵי עבירה וכ׳</span> sinful (obscene) imaginations are more injurious to health than the sin itself. <span class=\"citation\">Esth. R. to III, 1</span> (play on aḥar) <span dir=\"rtl\">הרהורי דברים היו שם</span> plans (schemes) were there.</div>","alt":["הִירְ׳"]},"8292":{"h":"הַרְהוּרָא","r":"E00839","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XXIX, 18</span>. <span class=\"citation\">Targ. Y. ib. XXIII, 11</span>; a. e.—<span class=\"citation\">Snh. 45ᵃ</span> <span dir=\"rtl\">חיישי לה׳</span> take into consideration the possibility of creating impure thoughts (among the spectators); <span class=\"citation\">Sot. 8ᵃ</span>.—Pl. <span dir=\"rtl\">הַרְהוֹרִין</span>, <span dir=\"rtl\">הִרְהוּרִין</span>, <a href=\"#\" data-headword=\"הִרְהוּר\">הִירְ׳</a>. <span class=\"citation\">Targ. Y. Lev. VI, 2</span>. <span class=\"citation\">Targ. Ez. XXXVIII, 10</span>; a. fr.</div>","alt":["הִירְהוּרָא"]},"8293":{"h":"הִרְהֵר","r":"E00840","html":"<div class=\"sense\"> (Pilp. of <span dir=\"rtl\">הרר</span>; v. <a href=\"#\" data-headword=\"הָרָה\">הָרָה</a>, cmp. esp. <span class=\"citation\">Is. LIX, 13</span>) </div><div class=\"sense\"><b>1)</b> <i>to conceive in mind, to think, meditate, plan</i>. <span class=\"citation\">Ber. III, 4</span> <span dir=\"rtl\">מְהַרְהֵר בלבו</span> thinks (recites the Sh’ma) in his heart, v. <a href=\"#\" data-headword=\"הִרְהוּר\">הִרְהוּר</a>. <span class=\"citation\">Gitt. 57ᵇ</span> <span dir=\"rtl\">הי׳ תשובה בדעתיה</span> he conceived the idea of repentance.</div><div class=\"sense\"><b>—2)</b> <i>to be heated, entertain impure thoughts</i>. <span class=\"citation\">Ḥull. 37ᵇ</span> לא הִרְהַרְתִּי ביום I allowed no impure thoughts to rise in me in day-time; a. fr.</div><div class=\"sense\"><b>—3)</b>  (followed by <span dir=\"rtl\">אחר</span>) <i>to disparage, criticise, detract from</i>. <span class=\"citation\">Snh. 110ᵃ</span> <span dir=\"rtl\">המְהַרְהֵר אחר רבו</span> who speaks evil of his teacher. <span class=\"citation\">Num. R. s. 7</span> <span dir=\"rtl\">אם הִרְהַרְתָּ וכ׳</span> if thou criticisest them &amp;c. <span class=\"citation\">Ber. 19ᵃ</span> <span dir=\"rtl\">אל תְּהַרְהֵר אחריו ביום</span> do not think evil of him the day after (for he surely repented). <span class=\"citation\">Sifré Deut. 307</span> <span dir=\"rtl\">אין להַרְהֵר אחר מדותיו</span> you must not criticise His dealings with man; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to heat, make sick with fever</i>. <span class=\"citation\">Lev. R. s. 17</span> (play on <span dir=\"rtl\">ח̇ר̇צבות</span>, <span class=\"citation\">Ps. LXXIII, 4</span>; v. <a href=\"#\" data-headword=\"ה\">ה&quot;א</a>) <span dir=\"rtl\">לא הִרְהַרְתִּים בחלאים</span> (Var. <span dir=\"rtl\">חרחר׳</span>; Ar. s. v. <span dir=\"rtl\">חרצב</span>: <span dir=\"rtl\">ערער׳</span>) I did not make them hot with diseases; <span class=\"citation\">Yalk. Ps. 808</span>. [<span class=\"citation\">Ukts. III, 11</span>, v. <a href=\"#\" data-headword=\"חִרְחֵר\">חרְחֵר</a>.]</div>","alt":["הִירְ׳"]},"8294":{"h":"הַרְהֵר","r":"E00841","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Gen. VI, 2</span>.—<span class=\"citation\">Targ. Job II, 10</span> <a href=\"#\" data-headword=\"הִירְהוּר\">הַירְהֵר</a>; a. fr.</div>","alt":["הַרְהֵיר"]},"8295":{"h":"הרוגיינ׳","r":"E00842","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kil. I, 27ᵃ</span>, v. <a href=\"#\" data-headword=\"*נִיוְיָינָא\">נֵיוְיָינָא</a></div>","alt":[]},"8296":{"h":"הַרְוֵוחָא","r":"E00843","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"הַרְוָוחָה\">next w.</a>) <i>profit</i>, opp. <a href=\"#\" data-headword=\"פְּסֵיקָה\">פְּסֵידָה</a>. <span class=\"citation\">M. Kat. 2ᵃ</span></div>","alt":[]},"8297":{"h":"הַרְוָוחָה","r":"E00844","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>relief, release</i>. <span class=\"citation\">Ex. R. s. 10</span>, end; Tanḥ., ed. Bub., Vaëra 22; <span class=\"citation\">Yalk. Ex. 186</span> (cmp. <a href=\"#\" data-headword=\"הֶמְסֵס\">הֶמְסֵס</a> as to fusion of article). Tanḥ. Mikk. 10, v. <a href=\"#\" data-headword=\"בָּסַר I\"><span dir=\"rtl\">בָּסַר</span> I</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>plenty, liberal provision; comfort</i>. <span class=\"citation\">Snh. 21ᵇ</span> <span dir=\"rtl\">לא צריכא לה׳</span> the word <a href=\"#\" data-headword=\"לוֹ\">לוֹ</a> is to intimate a liberal appropriation (for the army). <span class=\"citation\">Sifré Deut. 306</span> <span dir=\"rtl\">ואין לשון פתיחה אלא לשון ה׳</span> the word ‘opening’ has the meaning of comfort, opp. <span dir=\"rtl\">לשון דוחק</span>. <span class=\"citation\">Keth. 43ᵃ</span> <span dir=\"rtl\">אלמנתו לא ניחא ליה בה׳ וכ׳</span></div>","alt":["הַרְוָחָה"]},"8298":{"h":"הרויין","r":"E00845","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Toh. VIII, 1</span>, v. <a href=\"#\" data-headword=\"*חֲדוּיִין\">חֲדוּיִין</a></div>","alt":[]},"8299":{"h":"*הֲרוּרִים","r":"E00846","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">הרר</span>, v. <a href=\"#\" data-headword=\"הִרְהֵר\">הִרְהֵר</a>) <i>heating</i>, <span dir=\"rtl\">מעשה ה׳</span> <i>unnatural gratification on a woman’s body</i>. <span class=\"citation\">Snh. 66ᵇ</span>, Resp. Gaon. ed. Cassel, p. 110; v. <a href=\"#\" data-headword=\"*הִרְדּוּס\">הִרְדּוּס</a>, a. <a href=\"#\" data-headword=\"חִידּוּד\">חִידּוּד</a>.</div>","alt":[]},"8300":{"h":"הַרְזְבוֹנִית","r":"E00847","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְזְבוֹנִית\">אַרְזְבוֹנִית</a></div>","alt":["הַרְזְבָנִ׳"]},"8301":{"h":"הַרְזִיפָּא","r":"E00848","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְזַפְתָּא II\"><span dir=\"rtl\">אַרְזַפְתָּא</span> II</a>, a. <a href=\"#\" data-headword=\"הַרְזיפּוּ\">next w.</a></div>","alt":[]},"8302":{"h":"הַרְזיפּוּ","r":"E00849","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Rashi) (v. <a href=\"#\" data-headword=\"אַרְזַפְתָּא II\"><span dir=\"rtl\">אַרְזַפְתָּא</span> II</a>) name of a <i>bitter herb</i> (not generally used as food). <span class=\"citation\">Pes. 39ᵃ</span> (Ms. M. 2 <span dir=\"rtl\">אַרְזִיפָּא</span>, Ms. O. <span dir=\"rtl\">הדרוף</span>, v. <a href=\"#\" data-headword=\"הִירְדּוּף\">הִירְדּוּף</a>; v. Rabb. D. S. a. l. note 9).</div>","alt":["הַרְזִיפֵּי"]},"8303":{"h":"הַרְזֵיק","r":"E00850","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"הֶזֵּק\">הַזֵּק</a>, v. <span dir=\"rtl\">חזק</span>) <i>to imprison</i>. <span class=\"citation\">B. Kam. 85ᵇ</span> הַרְזְקֵיה באנדרונא וכ׳ Ar. (ed. <span dir=\"rtl\">הדק׳</span>) he kept him locked up in a room and forced him to be idle.—<i>Part. pass</i>. <span dir=\"rtl\">מְהַרְזַק</span>. <span class=\"citation\">Ned. 91ᵇ</span> דהוה קא מ׳ בביתא וכ׳ Ar. (ed. <span dir=\"rtl\">מִהַרְזֵיק</span> <i>Ithpa.</i>) who was locked up in a room with a woman.</div>","alt":["הַרְזֵק"]},"8304":{"h":"הַרְזִיקֵי","r":"E00851","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הַרְזֵיק\">preced.</a>) <a href=\"#\" data-headword=\"*אֶבְיוֹנֵי\">בֵּי ה׳</a> <i>guard-house, a gate house</i> with one door opening to the court and another leading to the entrance to the inner rooms or buildings; cmp. <a href=\"#\" data-headword=\"כְּלָאֵי\">כְּלָאֵי</a>. <span class=\"citation\">Men. 33ᵇ</span></div>","alt":[]},"8305":{"h":"הַרְזֵק","r":"E00852","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַרְזֵיק\">הַרְזִיק</a></div>","alt":[]},"8306":{"h":"הַרְחָצָה","r":"E00853","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַץ\">רָחַץ</a>) <i>washing, bathing</i>. <span class=\"citation\">Sabb. 134ᵇ</span> <span dir=\"rtl\">הַרְחָצַת כל גופו</span> bathing the child’s entire body; <span dir=\"rtl\">ה׳ מילה</span> bathing the wound of circumcision. <span class=\"citation\">Keth. 96ᵃ</span></div>","alt":[]},"8307":{"h":"הַרְחֵק","r":"E00854","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַק\">רָחַק</a>) </div><div class=\"sense\"><b>1)</b> <i>distance</i>.—<span dir=\"rtl\">ה׳ עדות</span> a) <i>an unlawful space between a deed and the signatures of the witnesses</i>. <span class=\"citation\">Y. Gitt. I, 43ᶜ</span> bot. <span dir=\"rtl\">עדים פסולין אינן נעשין כה׳ ע׳</span> the signatures of disqualified witnesses, between qualified ones, are not to be looked upon as if they were a blank creating an unlawful distance; ib. IX, 50ᶜ; ib. VIII, end, 49ᵈ (insert: <span dir=\"rtl\">עדים פסולים אינן</span>).—b) <i>distance of relationship</i>, i.e. <i>testimony not objectionable on account of kinship</i>. <span class=\"citation\">Y. Keth. II, 26ᵈ</span> top [read:] <span dir=\"rtl\">ואם אין את מאמינו שהוא בנו יעשה כה׳ ע׳ וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>a precautionary measure, a preventive law</i>. <span class=\"citation\">Y. Maasr. I, 49ᵇ</span> top.</div>","alt":["הֶרְחֵק"]},"8308":{"h":"הַרְחָקה","r":"E00855","html":"<div class=\"sense\"> f. as <a href=\"#\" data-headword=\"הַרְחֵק\">preced.</a> 2. <span class=\"citation\">Pes. 2ᵇ</span>. <span class=\"citation\">Ab. Zar. 31ᵇ</span> <span dir=\"rtl\">ה׳ יתירתא</span> an extraordinary precaution.</div>","alt":[]},"8309":{"h":"הַרְטָבָה׳","r":"E00856","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְטִיבָה\">רְטִיבָה</a></div>","alt":[]},"8310":{"h":"הֲרֵי I","r":"E00857","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">הראי</span>; <a href=\"#\" data-headword=\"ראי\">ראה</a>) <i>aspect, characteristic points, case</i>. <span class=\"citation\">B. Kam. I, 1</span> (ref. to the four cases of damage <span class=\"citation\">Ex. XXI, 28</span>; <span class=\"citation\">XXI, 33</span>; <span class=\"citation\">XXII, 4</span>; <span class=\"citation\">XXII, 5</span>) <span dir=\"rtl\">לא ה׳ השור כה׳ וכ׳</span> (Y. ed. <span dir=\"rtl\">לא השור כה׳ וכ׳</span>) the case of the goring ox is not analogous to that of the eating animal, nor are the cases of both of them which are animated beings, analogous to the case of damage through fire which is inanimate &amp;c. (i.e. the four cases had to be specified in the Biblical text); yet the points common to all are that they are liable to do damage &amp;c. Mekh. Mishp., N’zikin, s. 5 <span dir=\"rtl\">לא ה׳ הדיין כה׳ וכ׳</span> the case of (cursing) the judge is not analogous to that of (cursing) the prince, yet the point common to both &amp;c. [In G’marah <a href=\"#\" data-headword=\"ראי\">רְאִי</a>, v. <span class=\"citation\">B. Kam. 4ᵃ</span>.]</div>","alt":["הֲרִי"]},"8311":{"h":"הֲרֵי II","r":"E00858","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"הֲרֵי I\">preced.</a>, = b. h. <a href=\"#\" data-headword=\"הֵן\">הֵן</a>, <a href=\"#\" data-headword=\"הִנֵּה\">הִנֵּה</a>) </div><div class=\"sense\"><b>1)</b> <i>behold, here is</i>. <span class=\"citation\">Gen. R. s. 91</span>, end <span dir=\"rtl\">ה׳ הכסף וכ׳</span> here is the silver &amp;c.—<span class=\"citation\">Ab. III, 4</span>, a. fr. <span dir=\"rtl\">ה׳ זה וכ׳</span> such a person is &amp;c. <span class=\"citation\">Bets. V, 3</span>, a. fr. <span dir=\"rtl\">ה׳ אלו וכ׳</span> in this case they are &amp;c. <span class=\"citation\">B. Kam. IX, 2</span> <span dir=\"rtl\">ה׳ שלך לפניך</span> here is thy property before thee (take it in the condition in which it is); a. v. fr.—<span dir=\"rtl\">הֲרֵינִי</span> = <span dir=\"rtl\">ה׳ אני</span> behold, I am, will be &amp;c. <span class=\"citation\">Naz. I, 1</span> ה׳ נזיר I will be a Nazir. <span class=\"citation\">Kidd. 31ᵇ</span> <span dir=\"rtl\">ה׳ כפרת וכ׳</span> may I be the atonement for his rest (a blessing formula for a deceased father); a. fr.</div><div class=\"sense\"><b>—2)</b>  ה׳ ש׳־ <i>here is a case of one, if</i>. <span class=\"citation\">Meg. 3ᵇ</span> <span dir=\"rtl\">ה׳ שהיה וכ׳</span> if one is going to slaughter &amp;c.; a. fr.</div>","alt":[]},"8312":{"h":"הֲרִיגָה","r":"E00859","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָרַג\">הָרַג</a>) <i>killing</i>. <span class=\"citation\">Sabb. 107ᵇ</span>.—Esp. <i>execution of capital punishment, decapitation</i>. <span class=\"citation\">Y. Keth. II, 26ᵈ</span> <span dir=\"rtl\">נגמר דינה לה׳</span> if she has been sentenced to death. <span class=\"citation\">Y. Snh. VII, 24ᵇ</span> <a href=\"#\" data-headword=\"ה׳\">ה׳</a> decapitation, v. <a href=\"#\" data-headword=\"הֶרֶג\">הֶרֶג</a>. <span class=\"citation\">Ex. R. s. 1</span>; a. fr.</div>","alt":[]},"8313":{"h":"הֲרֵידוֹס","r":"E00860","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Hăredos</i> (Herod), one of Haman’s ancestry. Targ. II Esth. III, 1 (ed. Lag. <span dir=\"rtl\">הדירוס</span>).</div>","alt":[]},"8314":{"h":"הֵרָיוֹן","r":"E00861","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>conception, coition</i>. <span class=\"citation\">Nidd. 16ᵇ</span>. <span class=\"citation\">Gen. R. s. 64</span>. <span class=\"citation\">Y. B. Kam. V, 5ᵃ</span> top <span dir=\"rtl\">בעל ה׳</span> the natural father (not step-father); a. e.—<span class=\"citation\">B. Kam. 49ᵃ</span> <span dir=\"rtl\">בית הה׳</span> womb, abdomen.</div>","alt":[]},"8315":{"h":"הריוסן","r":"E00862","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ter. XI, 48ᵃ</span>, v. <a href=\"#\" data-headword=\"חַרְסָן\">חַרְסָן</a></div>","alt":[]},"8316":{"h":"הריית","r":"E00863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַדְיָית\">חַדְיָית</a></div>","alt":[]},"8317":{"h":"הָרִיס","r":"E00864","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָרִיץ\">חָרִיץ</a></div>","alt":[]},"8318":{"h":"הֲרִיעָה","r":"E00865","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּעַ I\">רוּעַ</a>) <i>shouting</i> for joy. Pesik. Ronni, p. 141ᵇ one of the expressions for rejoicing (<span class=\"citation\">Cant. R. to I, 4</span>, reads <a href=\"#\" data-headword=\"תְּרוּעָה\">תְּרוּעָה</a>). Cmp. <a href=\"#\" data-headword=\"הֲרָעָה II\"><span dir=\"rtl\">הֲרָעָה</span> II</a>.</div>","alt":[]},"8319":{"h":"הֲרִיפָה","r":"E00866","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רפף</span>, <a href=\"#\" data-headword=\"רוּף\">רוף</a>) <i>trembling</i>, only in <span dir=\"rtl\">הֲרִיפַת עין</span> <i>wink of the eye</i>, <span dir=\"rtl\">בה׳ ע׳</span> in a wink. <span class=\"citation\">Koh. R. to XI, 1</span> (ed. Wil. <span dir=\"rtl\">כה׳</span>).</div>","alt":[]},"8320":{"h":"הֲרִיפוֹת","r":"E00867","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>grits, polenta</i>. <span class=\"citation\">Sot. 42ᵇ</span> (homiletical play on <i>Harafah</i>, <span class=\"citation\">II Sam. XXI, 16</span>, a. <i>Orpah</i>, <span class=\"citation\">Ruth I, 4</span>) why was she called Harafah? <span dir=\"rtl\">שהכל דשין אותה כה׳</span> because all pounded (used) her like grits, v. <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a>. [Cmp. <span class=\"citation\">Y. Kidd. I, 59ᵃ</span> top a. <span class=\"citation\">Kerith. 11ᵃ</span> where <span dir=\"rtl\">חרף</span> is taken as the equivalent of <span dir=\"rtl\">כתש</span>, with reference to <a href=\"#\" data-headword=\"הֲרִיפוֹת\">הריפות</a> <span class=\"citation\">Prov. XXVII, 22</span>. Cmp. <a href=\"#\" data-headword=\"*הַלְטָאָה\">הַלְטָאָה</a> for obliteration of radical <a href=\"#\" data-headword=\"ה\">ה</a>.—<span class=\"citation\">Targ. I Chr. XX, 4</span>; <span class=\"citation\">6</span>; <span class=\"citation\">8</span> reads <a href=\"#\" data-headword=\"עָרְפָּה\">ערפה</a> for h. text <span dir=\"rtl\">הרפאים</span>, <a href=\"#\" data-headword=\"רפי\">הרפא</a>.]</div>","alt":["הָרִי׳"]},"8321":{"h":"הֲרִיקָא","r":"E00868","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲרִיקָא\">חֲרִיקָא</a></div>","alt":[]},"8322":{"h":"הרך","r":"E00869","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲרָךְ I\">חֲרָךְ</a></div>","alt":[]},"8323":{"h":"הֶרְכֵּב","r":"E00870","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָכב\">רָכַב</a>) <i>carrying</i> (<i>a lamb</i>) <i>on one’s shoulder</i>. <span class=\"citation\">Pes. VI, 1</span> הֶרְכֵּבוֹ Y. ed., Ms. M. a. Mish. Nap. <a href=\"#\" data-headword=\"הֶרְכֵּיב\">הֶרְכֵּיבוֹ</a> (ed. <span dir=\"rtl\">הַרְכָּבָתוֹ</span>) the carrying of the Passover lamb to the Temple. Y. ib. 33ᵇ top.</div>","alt":[]},"8324":{"h":"הַרְכָּבָה","r":"E00871","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"הֶרְכֵּב\">same</a>, v. preced.—2) <i>grafting.</i> <span class=\"citation\">Shebi. II, 6</span>; a. fr.</div>","alt":[]},"8325":{"h":"הרכיא","r":"E00872","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲרָכַיָּיא\">חֲרָכַיָּיא</a></div>","alt":[]},"8326":{"h":"הֶרְכֵּיב","r":"E00873","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֶרְכֵּב\">הֶרְכֵּב</a></div>","alt":[]},"8327":{"h":"הַרְכִּינָס","r":"E00874","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Ἀρχῖνος) <i>Harkinas</i>, father of R. Dosa. <span class=\"citation\">R. Hash. II, 8</span> (<span class=\"citation\">25ᵃ</span>) <span dir=\"rtl\">הר׳</span> Mish. a. Ms. M. (ed. <span dir=\"rtl\">הוֹרְ׳</span>); Mish. Pes. a. Y. ed. <span dir=\"rtl\">ארכינס</span>, v. Rabb. D. S. a. l. note). <span class=\"citation\">Tosef. Neg. I, 6</span> <span dir=\"rtl\">הרכ׳</span>; (ib. Kel. <span class=\"citation\">B. Bath. IV, 14</span> <span dir=\"rtl\">הורקינס</span>). <span class=\"citation\">Yeb. 16ᵃ</span>; a. fr.</div>","alt":[]},"8328":{"h":"הַרְכָּנָה","r":"E00875","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָכַן I\">רָכַן</a>) <i>inclination</i>, <span dir=\"rtl\">הַרְכָּנַת הָרֹאשׁ</span> <i>nodding assent</i>. <span class=\"citation\">Y. Gitt. VII, 48ᶜ</span> bot.; <span class=\"citation\">Y. Ter. I, 40ᵇ</span> top.</div>","alt":[]},"8329":{"h":"הֲרָמָה","r":"E00876","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּם\">רוּם</a>) </div><div class=\"sense\"><b>1)</b> <i>lifting, removal</i>. <span class=\"citation\">Y. Yoma II, beg. 39ᵇ</span> <span dir=\"rtl\">יצא זה שהוא בה׳</span> this (service) is excluded, since it consists only of removing (the ashes). Ib. 39ᶜ; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>separating the priest’s gift</i> &amp;c. <span class=\"citation\">Bets. I, 6</span> (<span class=\"citation\">12ᵇ</span>) <span dir=\"rtl\">אינו זכאי בהֲרָמָתָהּ</span> (v. Rabb. D. S. a. l.) nobody obtains a privilege by its being set apart; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>lifting up, elevation</i>. <span class=\"citation\">Yalk. Ps. 624</span> (ref. to <span dir=\"rtl\">ומרים</span>, <span class=\"citation\">Ps. III, 4</span>) <span dir=\"rtl\">תחת שהייתי … תלוי ראש נתת לי הֲרָמַת ראש וכ׳</span> while I deserved hanging down the head (in the consciousness of guilt), thou hast granted me a lifting up of the head (forgiveness, <span class=\"citation\">II Sam. XII, 13</span>); ib. (ref. to <span dir=\"rtl\">תשא</span> <span class=\"citation\">Ex. XXX, 12</span>) … <span dir=\"rtl\">תחת שהיינו תלוי ראש … ה׳ ראש</span>; Pesik. Shek. 10ᵇ, sq. (corr. acc.); Midr. Till. to Ps. l. c.; <span class=\"citation\">Yalk. Ex. 365</span> (corr. acc.). Tanḥ. Emor 16.</div>","alt":[]},"8330":{"h":"הַרְמוּצָא","r":"E00877","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְמוּצָא\">רְמוּצָה</a>, s. v. <a href=\"#\" data-headword=\"רָמַץ\">רָמַץ</a>.</div>","alt":[]},"8331":{"h":"הַרְמֵיךְ","r":"E00878","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (<i>Be</i>) <i>Harmekh</i> in Babylonia. <span class=\"citation\">Gitt. 60ᵇ</span> בי ה Ar. (ed. <a href=\"#\" data-headword=\"חוֹזָאֵי\">בי ח׳</a>). <span class=\"citation\">M. Kat. 4ᵇ</span> הרמיך Ms. M. (ed. <span dir=\"rtl\">בר המדך</span>). <span class=\"citation\">Zeb. 2ᵇ</span> <a href=\"#\" data-headword=\"חוֹזָאֵי\">בי ח׳</a> (v. Rabb. D. S. a. l. note 6).</div>","alt":["הַרְמֵךְ"]},"8332":{"h":"הַרְמִינֵי","r":"E00879","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Harmine</i> (<i>Hurmini</i>), prob. a province of Armenia. <span class=\"citation\">Targ. Jer. LI, 27</span> <span dir=\"rtl\">הור׳</span> ed. Lag. a. oth. (h. text <a href=\"#\" data-headword=\"מִנִּי\">מִנִּי</a>). <span class=\"citation\">Targ. Am. IV, 3</span> <span dir=\"rtl\">הר׳</span> (ed. Lag. <span dir=\"rtl\">הור׳</span>; h. text <span dir=\"rtl\">הרמונה</span>). <span class=\"citation\">Targ. Mic. VII, 12</span> <span dir=\"rtl\">חור׳ רבתא</span> (Var. ed. Lag. <span dir=\"rtl\">הור׳</span>) <i>Armenia Major</i>(?).</div>","alt":["(הוּרְמִינִי)"]},"8333":{"h":"הַרְמֵךְ","r":"E00880","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַרְמֵיךְ\">הַרְמֵיךְ</a></div>","alt":[]},"8334":{"h":"הַרְמָנָא","r":"E00881","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מני\">מני</a>, with preform. <a href=\"#\" data-headword=\"הַר\">הר</a>, cmp. <a href=\"#\" data-headword=\"הַרְפַּתְקָא\">הרפתקי</a>) <i>appointment to office, authority, royal patent</i>. <span class=\"citation\">Targ. Job I, 12</span>; <span class=\"citation\">II, 7</span>. <span class=\"citation\">Targ. Y. Num. XVII, 11</span>.—<span class=\"citation\">Ber. 58ᵃ</span> holding court <span dir=\"rtl\">בלא ה׳ דמלכא</span> without royal appointment. <span class=\"citation\">B. Mets. 84ᵃ</span> <span dir=\"rtl\">ה׳ דמלכא הוא</span> (Ms. R. 2 <span dir=\"rtl\">הור׳</span>) it is a royal appointment (which I cannot decline). <span class=\"citation\">Ḥull. 57ᵇ</span> <span dir=\"rtl\">ה׳ דמלכא לא ליבעו</span> would they not have asked for royal authority? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ה׳ דמלכא הוו נקיטי</span> they were in possession &amp;c.; (Ar. ed. Koh. the king was among them <span dir=\"rtl\">ומה׳ דמלכא עבוד</span> and they did it by royal authority). <span class=\"citation\">B. Bath. 46ᵇ</span>, v. next w.—<i>Trnsf.</i> (cmp. <a href=\"#\" data-headword=\"רָשׁוּת I\">רָשׁוּת</a>) <i>office, bureau</i>, esp. <i>Resh Galutha’s office</i>. <span class=\"citation\">Erub. 59ᵃ</span> <span dir=\"rtl\">משום דשכיחי רבנן גבי ה׳</span> (v. Rabb. D. S. a. l. note 300) because scholars are accustomed to meet at the Resh Galutha’s office (Ar. <a href=\"#\" data-headword=\"קָהַרְמָנָא\">קהרמנא</a>).</div>","alt":[]},"8335":{"h":"הַרְמַנְיָא","r":"E00882","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"הַרְמָנָא\">same</a>. <span class=\"citation\">B. Bath. 46ᵇ</span> <span dir=\"rtl\">ה׳ בעלמא שויוה</span> they (the owners) considered it (the transmission of the land to subtenants) merely an appointment (agency); (Asheri <span dir=\"rtl\">הרמנא שׁוְיָהּ</span>; Ar. <a href=\"#\" data-headword=\"הַרְמָנָא\">הרמנא</a>; v. Rabb. D. S. a. l. note 90).</div>","alt":[]},"8336":{"h":"הרנגול","r":"E00883","html":"<div class=\"sense\">, a clerical slip in Ar. s. v. <a href=\"#\" data-headword=\"הַרְנוֹגָא\">הרְנוֹגָא</a></div>","alt":[]},"8337":{"h":"הַרְנוֹגָא","r":"E00884","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>harnoga</i>, name of a bird, one of eight about which there is a doubt as to being clean. <span class=\"citation\">Ḥull. 62ᵇ</span></div><div class=\"sense\"><b>—2)</b> <i>a thorn</i>, v. <a href=\"#\" data-headword=\"חַרְנוֹגָא\">חַרְנוֹגָא</a>.</div>","alt":[]},"8338":{"h":"הרני","r":"E00885","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲרוֹנֵי\">אֲרוֹנֵי</a></div>","alt":[]},"8339":{"h":"הרנירק","r":"E00886","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אנדכתרי\">אנדכתרי</a></div>","alt":[]},"8340":{"h":"הָרַס","r":"E00887","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to break, to destroy, demolish</i>. <span class=\"citation\">Midr. Till. to Ps. IX, 7</span> הוא הוֹרֵס את וכ׳ He destroys your plans; <span class=\"citation\">Yalk. Mal. 587</span>.—<i>Part. pass</i>. <span dir=\"rtl\">הָרוּס</span>; f. <span dir=\"rtl\">הֲרוּסָה</span>. <span class=\"citation\">Gen. R. s. 45</span>; a. e.—Y. Ber. IV, 8ᵃ; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to break through, rush</i>. <span class=\"citation\">Yalk. Ex. 284</span> (expl. <span dir=\"rtl\">פן יהרסו</span>, <span class=\"citation\">Ex. XIX, 21</span>) <span dir=\"rtl\">שמא ידחקו</span>, v. <a href=\"#\" data-headword=\"דָּחַק\">דָּחַק</a>; Mekh. Yithro, Baḥod., s. 4.</div>","alt":[]},"8341":{"h":"הֶרֶס","r":"E00888","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הָרַס\">preced.</a>) <i>destruction</i>. <span class=\"citation\">Men. 110ᵃ</span> (interpret. <span dir=\"rtl\">עִיר הַהֶרֶס</span>, <span class=\"citation\">Is. XIX, 18</span>) <span dir=\"rtl\">קרתא … דעתידא למיחרב</span> (v. Rabb. D. S. a. l.) the town of Beth Shemesh which is doomed to destruction; v. <a href=\"#\" data-headword=\"חֲרַס\">חֶרֶס</a>.</div>","alt":[]},"8342":{"h":"הַרְסָן","r":"E00889","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְסָן\">חַרְסָן</a></div>","alt":[]},"8343":{"h":"הַרְסָנָא","r":"E00890","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">הרס</span>; cmp. Arab. <span dir=\"rtl\">הריסת</span>, Fl. to Levy Talm. Dict. I, p. 559ᵇ; cmp. <a href=\"#\" data-headword=\"חֲרוֹסֶת\">חֲרוֹסֶת</a>) <i>fish-hash</i>. <span class=\"citation\">B. Bath. 144ᵃ</span>, v. <a href=\"#\" data-headword=\"אֲצִיצָא\">אֲצִיצָא</a>.—<span dir=\"rtl\">כַּסָּא דה׳</span> a pie of fish-hash and flour. <span class=\"citation\">Bets. 16ᵃ</span>, sq.; <span class=\"citation\">Ab. Zar. 38ᵃ</span>; a. fr.</div>","alt":[]},"8344":{"h":"הֲרָעָה I","r":"E00891","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָעַע\">רָעַע</a>, Hif. <a href=\"#\" data-headword=\"רָעַע\">הֵרֵעַ</a>) <i>doing harm</i>) to one’s self or others); <i>self-abnegation; vow to injure;</i> v. <a href=\"#\" data-headword=\"הֲטָבָה\">הֲטָבָה</a>. <span class=\"citation\">Shebu. III, 5</span>; a. fr.</div>","alt":[]},"8345":{"h":"הֲרָעָה II","r":"E00892","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּעַ I\">רוּעַ</a>) <i>sounding the trumpet, a certain note</i> or <i>signal</i>. <span class=\"citation\">Y. R. Hash. IV, 59ᶜ</span> bot., v. <a href=\"#\" data-headword=\"*טרימוטה\">טרימוטה</a>.—Cmp. <a href=\"#\" data-headword=\"הֲרִיעָה\">הֲרִיעָה</a>, <a href=\"#\" data-headword=\"תְּרוּעָה\">תְּרוּעָה</a>.</div>","alt":[]},"8346":{"h":"הֶרֶף","r":"E00893","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רפף</span>, v. <a href=\"#\" data-headword=\"הֲרִיפָה\">הֲרִיפָה</a>) <i>trembling;</i> ה׳ עַיִן <i>wink, an indefinable portion of time</i>. <span class=\"citation\">Y. Ber. I, 2ᵇ</span> bot. <span dir=\"rtl\">בין השמשות כה׳ ע׳</span> the time called <i>ben-hash-sh’mashoth</i> is really like a wink of the eye. Ib.ᶜ top. Ib.ᵈ top; <span class=\"citation\">Lam. R. to II, 19</span>; v. <a href=\"#\" data-headword=\"רֶגַע\">רֶגַע</a>. <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">בה׳ ע׳</span> (not <span dir=\"rtl\">כה׳</span>) instantaneously; a. fr.</div>","alt":[]},"8347":{"h":"הָרָפָה","r":"E00894","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>Harafah</i>. <span class=\"citation\">Sot. 42ᵇ</span>, v. <a href=\"#\" data-headword=\"הֲרִיפוֹת\">הֲרִיפוֹת</a>.</div>","alt":[]},"8348":{"h":"הרפותיא","r":"E00895","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּרְסְפִיתָא\">חַרְסְפִיתָא</a></div>","alt":[]},"8349":{"h":"הרפיא","r":"E00896","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲרָפַיָּיא\">חֲרָפַיָּיא</a></div>","alt":[]},"8350":{"h":"הַרְפַּנְיָא","r":"E00897","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Harpania</i> (<i>Hipparenum</i>, Neub. Géogr. p. 335; p. 352) in Babylonia, a rich industrial town with a Jewish population of spurious descent. <span class=\"citation\">Yeb. 17ᵃ</span> what a great man, <span dir=\"rtl\">אי לאו דה׳ מאתיה</span> were not H. his native town! <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי ה׳</span>, v. <a href=\"#\" data-headword=\"הַר\">הַר</a>. <span class=\"citation\">Sabb. 127ᵃ</span> (Ms. M. <span dir=\"rtl\">הרדפנאי</span>, read <span dir=\"rtl\">הַרְפְּנָאֵי</span> <i>Harpanians</i>); <span class=\"citation\">B. Mets. 84ᵃ</span> דה׳ Ms. M. (ed. <span dir=\"rtl\">דהַרְפְּנָאֵי</span>) v. <a href=\"#\" data-headword=\"דְּקוּרָא\">דְּקוּרָא</a>. <span class=\"citation\">Ab. Zar. 74ᵇ</span>. <span class=\"citation\">Snh. 48ᵇ</span> (Ms. M. <span dir=\"rtl\">נהר פניא</span>) [<span class=\"citation\">Kidd. 72ᵇ</span> Ms. O. <span dir=\"rtl\">הפרניא והימניא</span>, ed. only <a href=\"#\" data-headword=\"הוּמַנְיָא\">הומניא</a>.]—Denom. <span dir=\"rtl\">הַרְפְּנָאָה</span> m. <i>of H</i>. <span class=\"citation\">Erub. 59ᵇ</span> (v. Rabb. D. S. a. l. note 90).—Pl. <span dir=\"rtl\">הַרְפְּנָאֵי</span>, v. supra.</div>","alt":[]},"8351":{"h":"הַרְפַּתְקָא","r":"E00898","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּתַק I\">פתק</a> with preform. <a href=\"#\" data-headword=\"הַר\">הר</a>, cmp. <a href=\"#\" data-headword=\"הַרְמָנָא\">הַרְמָנָא</a>; v. <a href=\"#\" data-headword=\"פִּיתַק\">פִּיתְקָא</a>) [<i>portions, allotments</i>,] </div><div class=\"sense\"><b>1)</b> <i>measure, limitation</i>. <span class=\"citation\">Targ. Job XVIII, 2</span> (h. text <span dir=\"rtl\">קִנְצֵי</span>).</div><div class=\"sense\"><b>—2)</b> <i>destinies, reverses, experiences</i> (cmp. <a href=\"#\" data-headword=\"גְּזֵרָה\">גְּזֵרָה</a>). Ib. XII, 5 <span dir=\"rtl\">ה׳ זמנא</span> the changes of time (h. text <span dir=\"rtl\">מועדי רגל</span>; cmp. <a href=\"#\" data-headword=\"רֶגֶל\">רֶגֶל</a>).—<span class=\"citation\">R. Hash. 16ᵃ</span> <span dir=\"rtl\">כל הני ה׳ דעדו וכ׳</span> all those preordained changes that passed over the standing crop (up to Passover).</div>","alt":["הַרְפַּתְקֵי"]},"8352":{"h":"הַרְצָאָה","r":"E00899","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצָה\">רָצָה</a>) </div><div class=\"sense\"><b>1)</b>  (v. <span class=\"citation\">Lev. I, 4</span>) <i>acceptability of a sacrifice, gracious reception, qualification for offering, atonement</i>. <span class=\"citation\">Ḥull. 81ᵃ</span> <span dir=\"rtl\">לילה לקדושה יום לה׳</span> the eve of the eighth day qualifies it for dedication, the morning for an acceptable offering. <span class=\"citation\">Zeb. 28ᵇ</span>, a. e. (ref. to <span class=\"citation\">Lev. XXII, 27</span> a. <span class=\"citation\">XIX, 7</span>) <span dir=\"rtl\">כהַרְצָאת כשר וכ׳</span> the same ceremonies which are needed for the atoning efficacy of the legally performed offering, are required for making it an unfit offering (the eating of which is punishable with extinction). <span class=\"citation\">Ker. 9ᵃ</span> <span dir=\"rtl\">הַרְצָאַת דם</span> (<a href=\"#\" data-headword=\"דָּמִים\">דמים</a>)) reception into the covenant through the sprinkling of blood (<span class=\"citation\">Ex. XXIV, 5</span> sq.).—Sifra Vayikra, N’dabah, Par. 5, ch. VII <span dir=\"rtl\">לאחר הרציה</span> after the sprinkling of the blood. <span class=\"citation\">Zeb. 45ᵇ</span> <span dir=\"rtl\">בני ה׳</span> those for whom a sacrifice may effect atonement. Sifra Emor ch. III, Par. 4 <span dir=\"rtl\">מה חילול … ה׳</span> as the desecration <i>there</i> refers to a sacrifice which has an atoning effect; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>making willing, conciliation</i>. <span class=\"citation\">Men. 27ᵃ</span> <span dir=\"rtl\">וכן ישראל בה׳ … באגודה אחת</span> (Ms. M. <span dir=\"rtl\">ובן ישׁראל עד … בה׳ אחת</span>) and so is it with Israel’s conciliation (with God), which can be achieved only when they are all one brotherhood; (<span class=\"citation\">Yalk. Lev. 651</span>: <span dir=\"rtl\">וכן ישראל לא ישובו לארצם עד וכ׳</span>). <span class=\"citation\">Kidd. 14ᵇ</span> <span dir=\"rtl\">להרצאת אדון</span> to make the master willing to dismiss his slave (<span class=\"citation\">Deut. XV, 18</span>).</div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"רָצָה\">רָצָה</a><i>Hif.</i>) <i>discourse</i> (on theosophy).—Pl. <span dir=\"rtl\">הַרְצָאוֹת</span>. <span class=\"citation\">Ḥag. 14ᵇ</span></div>","alt":["הַרְצָיָה"]},"8353":{"h":"הַרְקָדָה","r":"E00900","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָקַד\">רָקַד</a>) <i>shaking</i> (in the sieve), <i>sifting</i>. <span class=\"citation\">Pes. 11ᵃ</span> <span dir=\"rtl\">טחינה וה׳ מא&quot;ל</span> in grinding and sifting (the flour) what change from the ordinary process can he make? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ה׳ ע&quot;ג נפה</span> he does the sifting on the back of the sieve. <span class=\"citation\">Y. Sabb. VII, 10ᵇ</span> bot.; a. e.—<span class=\"citation\">Tosef. Men. XI, 4</span> <span dir=\"rtl\">הֶרְקֵידָן</span>.</div>","alt":[]},"8354":{"h":"הרקיא","r":"E00901","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲרָקַיָּיא\">חֲרָקַיָּיא</a></div>","alt":["הרקיה"]},"8355":{"h":"הֶרְקֵיד","r":"E00902","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sifting</i>, v. <a href=\"#\" data-headword=\"הַרְקָדָה\">הַרְקָדָה</a>.</div>","alt":[]},"8356":{"h":"*הֱרַקְלִיאוֹפּוֹלִיס","r":"E00903","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Heracleopolis</i>, in Middle Egypt. Pesik. Vayhi, p. 63ᵇ <span dir=\"rtl\">עיר ההרס זה חדאקנו</span> (corr. acc.) <i>Ir Haheres</i> (<span class=\"citation\">Is. XIX, 18</span>) is Heracleopolis; <span class=\"citation\">Pesik. R. s. 17</span> <span dir=\"rtl\">סרק אני</span> (corr. acc.). [V., however, <span class=\"citation\">Men. 100ᵃ</span>.]</div>","alt":[]},"8357":{"h":"הֶרֶר","r":"E00904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַר\">הַר</a></div>","alt":["הֲרָרִים"]},"8358":{"h":"הַרְשָׁאָה","r":"E00905","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָשָׁה\">רָשָׁה</a>, <i>Hif.</i>) <i>authorization, authority, power of attorney</i>. <span class=\"citation\">Keth. 95ᵃ</span> <span dir=\"rtl\">נכתבו ה׳ להדדי</span> let the two purchasers of the same property write out a power of attorney to one another (to sue the seller). <span class=\"citation\">Shebu. 31ᵃ</span> <span dir=\"rtl\">הבא בה׳</span> he who comes before court with a power of attorney (not in his own case). <span class=\"citation\">Bekh. 47ᵇ</span>; a. fr.</div>","alt":[]},"8359":{"h":"*הֶרֶת","r":"E00906","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <span class=\"citation\">Jer. XX</span>, <i>womb</i> of an animal. <span class=\"citation\">Ber. 44ᵇ</span>; <span class=\"citation\">57ᵇ</span>; <span class=\"citation\">Ab. Zar. 29ᵃ</span>. [Oth. opin. <i>sweet-bread, pancreas;</i> v. <a href=\"#\" data-headword=\"רֶתֶת\">רֶתֶת</a>.]</div>","alt":[]},"8360":{"h":"הַרְתָּא","r":"E00907","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"חַרְתָּא I\">חַרְתָּא</a></div>","alt":[]},"8361":{"h":"הרתת","r":"E00908","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֶתֶת\">רֶתֶת</a></div>","alt":[]},"8362":{"h":"הָשֵׁב","r":"E00909","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"שׁוּב I\">שׁוּב</a>) <i>restoring, giving back</i>. <span class=\"citation\">B. Mets. III, 6</span> (<span class=\"citation\">38ᵃ</span>) <span dir=\"rtl\">מפני ה׳ אבידה</span> Ms. M. a. Y. ed. (ed. <span dir=\"rtl\">מפני שהוא כמשיב</span>) because the taking care of a trust comes under the duty of restoring a neighbor’s lost property; Y. Yeb. II, end, 4ᵇ; a. e.; v. <a href=\"#\" data-headword=\"הֲשָׁבָה\">next w.</a></div>","alt":[]},"8363":{"h":"הֲשָׁבָה","r":"E00910","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הָשֵׁב\">same</a>, <span dir=\"rtl\">הֲשָׁבַת אבידה</span> the duty of restoring a neighbor’s lost property. <span class=\"citation\">B. Kam. V, 7</span> (<span class=\"citation\">54ᵇ</span>) <span dir=\"rtl\">לה׳ א׳</span> (Ms. M. a. Y. ed. <span dir=\"rtl\">להָשֵׁיב</span>; Y. ib. V, end, 5ᵃ <span dir=\"rtl\">להָשֵׁב</span>, v. <a href=\"#\" data-headword=\"הָשֵׁב\">preced.</a>); <span class=\"citation\">Yalk. Ex. 281</span>; a. fr.—Pl. <span dir=\"rtl\">הֲשָׁבוֹת</span>. <span class=\"citation\">B. Kam. 57ᵃ</span>; <span class=\"citation\">B. Mets. 31ᵃ</span> <span dir=\"rtl\">מפני … ריבתה ה׳ הרבה</span> because the Biblical text speaks frequently of restoration (but does nos intimate that the owner must be notified of the restoration).</div>","alt":[]},"8364":{"h":"הֵשָׁבוֹן","r":"E00911","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הֲשָׁבָה\">preced.</a>) <i>making amends for robbery, fraud</i> &amp;c. (according to <span class=\"citation\">Lev. V, 20—26</span>). <span class=\"citation\">Yeb. 47ᵇ</span> <span dir=\"rtl\">לא ניתן לה׳</span> has not the privilege of making amends (and being atoned for); <span class=\"citation\">Ab. Zar. 71ᵇ</span>. <span class=\"citation\">B. Bath. 35ᵇ</span> <span dir=\"rtl\">לא ניתן לה׳</span> has no opportunity of &amp;c.—<span class=\"citation\">B. Mets. 48ᵃ</span> <span dir=\"rtl\">להי׳</span></div>","alt":["הֵישָׁ׳"]},"8365":{"h":"הַשְׁבָּתָה","r":"E00912","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (שָׁבַת <i>Hif.</i>) <i>removal</i> (v. <span class=\"citation\">Ex. XII, 15</span>). <span class=\"citation\">Pes. 5ᵃ</span> <span dir=\"rtl\">הַשְׁבָּתַת שאור</span>.—Pl. <span dir=\"rtl\">הַשְׁבָּתוֹת</span>. <span class=\"citation\">Ib. 10ᵇ</span> <span dir=\"rtl\">שלש ה׳ בתורה</span> the three injunctions in the Torah concerning the removal of leavened things.</div>","alt":[]},"8366":{"h":"הֶשֵּׂג","r":"E00913","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נָשַׂג</span>) <i>reaching</i>, <span dir=\"rtl\">ה׳ יד</span> <i>regard to one’s wealth, the law regulating the payment of certain vows according to one’s means</i> (<span class=\"citation\">Lev. XXVII, 8</span>). <span class=\"citation\">Arakh. 5ᵃ</span> <span dir=\"rtl\">נידין בה׳ יד</span> does he come under the law of &amp;c.?—<span class=\"citation\">Ib. IV, 1</span> <span dir=\"rtl\">ה׳ יד בנודר</span> the law of <i>hesseg yad</i> is regulated by the means of him who makes the vow; a. e.</div>","alt":[]},"8367":{"h":"הַשָּׂגָה","r":"E00914","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"הֶשֵּׂג\">same</a>, <span dir=\"rtl\">הַשָּׂגַת יד</span> (<span class=\"citation\">Lev. XXV, 26</span>) <i>having</i> or <i>obtaining the necessary means</i>. <span class=\"citation\">Y. Kidd. I, 59ᵇ</span> top <span dir=\"rtl\">ה׳ יד של עצמו</span> his own obtaining the means of redemption; <span dir=\"rtl\">ה׳ ידי אחרים</span> the furnishing the means by others.</div>","alt":[]},"8368":{"h":"הַשְׁגָּרָה","r":"E00915","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַשְׁגָּרָה\">אשְׁגָּרָה</a></div>","alt":[]},"8369":{"h":"הַשְׁחָרָה","r":"E00916","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שַׁחַר\">שַׁחַר</a>) <i>getting up early; early work, study</i>. <span class=\"citation\">Lev. R. s. 19</span>, beg., v. <a href=\"#\" data-headword=\"הַעֲרָבָה\">הַעֲרָבָה</a>.</div>","alt":[]},"8370":{"h":"הַשְׁחֵת","r":"E00917","html":"<div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"שָׁחַת\">שָׁחַת</a>) pr. n. <i>Hashḥeth</i> (<i>Destruction</i>), allegorical name of an angel of justice. <span class=\"citation\">Ex. R. s. 41</span>, end (ref. to <span class=\"citation\">Ps. CVI, 23</span>); ib. s. 44; (<span class=\"citation\">Deut. R. s. 3</span>, a. e. <a href=\"#\" data-headword=\"מַשְׁחִית\">מַשְׁחִית</a>).</div>","alt":[]},"8371":{"h":"הַשְׁחָתָה","r":"E00918","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁחַת\">שָׁחַת</a>) l) <i>destruction</i>. <span class=\"citation\">Y. Shek. I, 45ᵈ</span> bot. (ref. to <span class=\"citation\">Zeph. III, 7</span>) <span dir=\"rtl\">כל ה׳ … בהשכמה וכ׳</span> whatever destructive work the Israelites undertook, they did with early rising (eagerly). <span class=\"citation\">Ex. R. 10</span>, end <span dir=\"rtl\">הַשְׁחָתַת הצפרדעים</span> the injury (to their bodies) caused by the frogs (<span class=\"citation\">Ps. LXXVIII, 45</span>); a e.—2) (with ref. to <span class=\"citation\">Lev. XIX, 27</span>) <i>shaving with a razor</i>. <span class=\"citation\">Naz. 57ᵇ</span>; <span class=\"citation\">Kidd. 35ᵇ</span> <span dir=\"rtl\">כל שישנו בה׳ וכ׳</span> he to whom the law, ‘Thou shalt not destroy’ (Lev. l. c.) applies, is subject to the law, ‘Ye shall not take off all around &amp;c.’, v. <a href=\"#\" data-headword=\"הַקָּפָה\">הַקָּפָה</a>. Ib. <span dir=\"rtl\">גילוח שיש בו ה׳</span>, v. <a href=\"#\" data-headword=\"גִּילּוּחַ\">גִּילּוּח</a>; a. fr.</div>","alt":[]},"8372":{"h":"הֶשֵּׂיאָה","r":"E00919","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>, Hif.) = <a href=\"#\" data-headword=\"הֶסֵּיעַ\">הֶסֵּיעַ</a>, <i>diverting the mind</i> from a question which must not be answered, a <i>Biblical puzzle of interpretation</i> used for diverting the mind.—Pl. <span dir=\"rtl\">הֶשֵּׂיאוֹת</span>. <span class=\"citation\">Y. Ab. Zar. II, 41ᶜ</span> bot. (ref. to <span dir=\"rtl\">השיאו</span>, Mish. <span class=\"citation\">Ab. Zar. II, 8</span>) he ought to have diverted his mind by means of one <span dir=\"rtl\">מחמש ה׳ בתורה</span> of the five puzzles &amp;c., v. <a href=\"#\" data-headword=\"הַכְרָעָה\">הַכְרָעָה</a>.</div>","alt":[]},"8373":{"h":"הָשֵׁיב","r":"E00920","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲשָׁבָה\">הְשָׁבָה</a></div>","alt":[]},"8374":{"h":"הַשְׂכֵּל","r":"E00921","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>reflection, wisdom</i>. <span class=\"citation\">Lev. R. s. 3</span>, end; a. e.—Esp. <i>haskel</i>, one of the expressions for hymns (ref. to <span dir=\"rtl\">מַשְׂכִּיל</span> in Psalm inscriptions). Y. Succ. II, 54ᵃ top; <span class=\"citation\">Y. Meg. I, 72ᵃ</span> top; (<span class=\"citation\">Pes. 117ᵃ</span> <span dir=\"rtl\">מַשְׂכִּיל</span>).</div>","alt":[]},"8375":{"h":"הַשְׂכָּלָה","r":"E00922","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הַשְׂכֵּל\">preced.</a>) <i>wise reflection, thoughtfulness</i>. <span class=\"citation\">Gen. R. s. 60</span> (ref. to <span class=\"citation\">Prov. XVII, 2</span>) <span dir=\"rtl\">ומהו הַשְׂכָּלָתוֹ</span> and what was his (Eliezer’s) reflection?; <span class=\"citation\">Yalk. Prov. 956</span>.</div>","alt":[]},"8376":{"h":"הַשְׁכָּמָה","r":"E00923","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁכֶם I\">שכם</a>, <i>Hif.</i>) </div><div class=\"sense\"><b>1)</b> <i>early rising, early morning hour</i>. <span class=\"citation\">Sabb. 86ᵃ</span> <span dir=\"rtl\">בה׳ עלה</span> he went up early in the morning. Sifra K’dosh. ch. III, Par. 2 <span dir=\"rtl\">צא בה׳</span> start early.—<span class=\"citation\">Sabb. 127ᵃ</span> <span dir=\"rtl\">הַשְׁכָּמַת בה&quot;מ</span> coming in good time to college; a. fr.—Trnsf. <i>eagerness</i>. <span class=\"citation\">Y. Shek. I, 45ᵈ</span> bot., v. <a href=\"#\" data-headword=\"הַשְׁחָתָה\">הַשְׁחָתָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>going to labor in the morning</i>. Y. B. Mets. VII, beg. 11ᵇ <span dir=\"rtl\">שתהא השלמה</span> (corr. acc.), v. <a href=\"#\" data-headword=\"הַעֲרָבָה\">הַעֲרָבָה</a>.</div>","alt":[]},"8377":{"h":"הַשְׁלָחָה","r":"E00924","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שָׁלַח\">(שָׁלַח</a>), <span dir=\"rtl\">הַשְׁלָחַת יד</span> <i>stretching forth of hand, Divine punishment</i>. <span class=\"citation\">Lev. R. s. 20</span>; <span class=\"citation\">Num. R. s. 2</span> (ref. to <span class=\"citation\">Ex. XXIV, 11</span>) <span dir=\"rtl\">מכאן שהיו ראויין לה׳ יד</span> from here we learn that they would have deserved punishment at that time. V. <a href=\"#\" data-headword=\"הִשְׁתַּלַּחַת\">הִשְׁתַּלַּחַת</a></div>","alt":[]},"8378":{"h":"הַשְׁלָכָה","r":"E00925","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁלַךְ\">שָׁלַךְ</a>, <i>Hif.</i>) <i>casting away</i> by the side of the altar (<span class=\"citation\">Lev. I, 16</span></div>","alt":[]},"8379":{"h":"הַשְׁלָמָה","r":"E00926","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁלֵם\">שָׁלַם</a>) <i>completion</i>. <span class=\"citation\">Naz. 8ᵇ</span> <span dir=\"rtl\">מי הוי ה׳ כלל</span> how could he ever have finished the days of vowed nazirate?—<span class=\"citation\">Esth. R. to III, 7</span> <span dir=\"rtl\">הַשְׁלָמַת החומה וכ׳</span> the completion of the wall of Jerusalem.—Y. B. Mets. VII, beg. 11ᵇ, v. <a href=\"#\" data-headword=\"הַשְׁכָּמָה\">הַשְׁכָּמָה</a>.</div>","alt":[]},"8380":{"h":"הַשְׁמֵד","r":"E00927","html":"<div class=\"sense\"> (Infin. Hif. of <a href=\"#\" data-headword=\"שָׁמַד\">שָׁמַד</a>) [<i>extermination</i>,] <i>Hashmed</i>, allegorical name of an angel of justice. <span class=\"citation\">Ex. R. s. 41</span>, end; s. 44; <span class=\"citation\">Midr. Till. to Ps. VII</span>; a. fr.; (<span class=\"citation\">Deut. R. s. 3</span> <a href=\"#\" data-headword=\"מְכַלֶּה\">(מְכַלֶּה</a>).</div>","alt":[]},"8381":{"h":"הַשְׁמָדָה","r":"E00928","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"הַשְׁמֵד\">preced.</a>) <i>extermination, use of the verb</i> <span dir=\"rtl\">שמד</span>. <span class=\"citation\">Lev. R. s. 7</span>; s. 10.</div>","alt":[]},"8382":{"h":"הֲשָׂמָה","r":"E00929","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שׂוּם\">שׂוּם</a>, Hif.), <span dir=\"rtl\">הֲשָׂמַת עַיִן</span> <i>putting an eye upon, paying kind attention to</i> <span class=\"citation\">Gen. R. s. 93</span> [read:] <span dir=\"rtl\">זו היא ה׳ ע׳ שאמרת נהפך הדבר לסמיות עינים</span> is this the kindness thou hast promised (<span class=\"citation\">Gen. XLIV, 21</span>)? This is blindness; (<span class=\"citation\">Yalk. Gen. 150</span> <span dir=\"rtl\">שִׂימַת</span>).</div>","alt":[]},"8383":{"h":"הַשְׁמֵט","r":"E00930","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"שָׁמַט\">שָׁמַט</a>, v. <span class=\"citation\">Deut. XV, 3</span>) <i>cancelling</i>, esp. <span dir=\"rtl\">ה׳ כספים</span> <i>cancelling of</i> (<i>cash</i>) <i>debts in the Sabbatical year</i>. <span class=\"citation\">Y. Shebi. X, 39ᶜ</span> bot.; <span class=\"citation\">Y. Gitt. IV, 45ᶜ</span> bot., sq. Y. Macc. I, 31ᵃ bot. <span dir=\"rtl\">כה׳ כספים הוא</span> it is, like a cash debt, forfeited by limitation.</div>","alt":[]},"8384":{"h":"הַשְׁמָטָה","r":"E00931","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"הַשְׁמֵט\">same</a>. Y. R. Hash. III, 58ᵈ bot. <span dir=\"rtl\">הַשְׁמָטַת כספים</span>. <span class=\"citation\">Arakh. 4ᵃ</span> <span dir=\"rtl\">ה׳ קרקע</span> the return of landed property to the seller in the year of the jubilee. <span class=\"citation\">Kidd. 38ᵇ</span> <span dir=\"rtl\">ה׳ כ׳ חובת הגוף הוא</span> the remission of cash debts is a personal obligation (not dependent on the land of Palestine); a. fr.</div>","alt":[]},"8385":{"h":"*הֲשָׁפָה","r":"E00932","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שׁוּף\">שוף</a>) <i>smoothing, rubbing, finishing by rubbing</i>. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 1</span> ed. (ed. Zuck. <a href=\"#\" data-headword=\"הַטָּפָה\">הטפה</a>, v. <a href=\"#\" data-headword=\"חֲטִיפָה\">חֲטִיפָה</a>).</div>","alt":[]},"8386":{"h":"הַשְׁפָּלָה","r":"E00933","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁפֵל I\">שָׁפַל</a>) <i>lowering, removal from office</i>. <span class=\"citation\">Gen. R. s. 96</span> <span dir=\"rtl\">ואין מות אלא לשון ה׳</span> death (<span class=\"citation\">Koh. VIII, 8</span>) means removal &amp;c. <span class=\"citation\">Ex. R. s. 45</span> <span dir=\"rtl\">הַשְׁפָּלָתִי</span>, v. <a href=\"#\" data-headword=\"הַגְבָּהָה\">הַגְבָּהָה</a>; <span class=\"citation\">Lev. R. s. 1</span>; a. e.</div>","alt":[]},"8387":{"h":"הַשְׁפִּעַ","r":"E00934","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Inf. Hif. of <a href=\"#\" data-headword=\"שָׁפַע\">שָׁפַע</a>) <i>plenty, liberality</i>. <span class=\"citation\">Esth. R. to X</span>, end.</div>","alt":[]},"8388":{"h":"הַשְׁקָאָה","r":"E00935","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַשְׁקָיָה\">השְׁקָיָה</a></div>","alt":[]},"8389":{"h":"הַשָּׁקָה","r":"E00936","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשַׁק\">נָשַׁק</a>, <i>Hif.</i>) [<i>causing contact</i>,] <i>dipping of a vessel, filled with an unclean water, so as to make its surface level with the surface of the water into which it is dipped</i>, a ceremony of levitical purification, contrad. to <a href=\"#\" data-headword=\"הַטְבָּלַה\">הטבלה</a>, immersion. <span class=\"citation\">Bets. 18ᵃ</span> <span dir=\"rtl\">נגזור ה׳ אטו הטבלה</span> let us prohibit levelling as a precaution against immersion (on the Holy Days). <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">קשיא ה׳</span> the Mishnah permitting <i>hashshakah</i> is contradictory (to what Rabbi said in the Boraitha). <span class=\"citation\">Ḥull. 26ᵇ</span> <span dir=\"rtl\">לא סלקא להו ה׳ למיא</span> the <i>hash</i>. will not affect the liquid (in the vessel).</div>","alt":[]},"8390":{"h":"הַשְׁקָיָה","r":"E00937","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁקָה\">שָׁקָה</a>, <i>Hif.</i>) <i>giving to drink</i>, esp. (<span dir=\"rtl\">הַשְׁקָיַית סוֹטָה</span>) <i>handing the bitter water to the suspected wife</i> (<span class=\"citation\">Num. V, 24</span>). <span class=\"citation\">Meg. II, 7</span> (<span class=\"citation\">20ᵇ</span>) <span dir=\"rtl\">ולהשקיית וכ׳</span> (Ms. M. <span dir=\"rtl\">ולהַשְׁקוֹת</span>, Ms. L. <span dir=\"rtl\">להַשְׁקָאַת</span>, v. Rabb. D. S. a. l. note). <span class=\"citation\">Y. Sot. III, 18ᵈ</span> top <span dir=\"rtl\">מחיקה סמוכה לה׳</span> the blotting out must be immediately followed by the giving to drink. <span class=\"citation\">Snh. 87ᵃ</span> <span dir=\"rtl\">השקאת</span>; a. fr.</div>","alt":["הַשְׁקָיָיה","הַשְׁקָאָה"]},"8391":{"h":"הַשְׁקָפָה","r":"E00938","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁקַף I\">שָׁקַף</a>, <i>Hif.</i>) <i>the looking down, the use of the verb</i> <a href=\"#\" data-headword=\"שָׁקַף I\">הִשְׁקִיף</a>. Y. Maas. Sh. V, 56ᶜ bot. <span dir=\"rtl\">כל ה׳ … ארירה וכ׳</span> (not <span dir=\"rtl\">ארורה</span>) wherever in the Torah <i>hishkif</i> is used, it means curse (punishment), but this (<span class=\"citation\">Deut. XXVI, 15</span>) means blessing. Tosef. ib. V, 25 ‘from thy holy dwelling’ <span dir=\"rtl\">זו מקום ה׳ וכ׳</span> ed. (ed. Zuck. <span dir=\"rtl\">ממעון קדשך השקיפה</span>) that is the place of looking down, i.e. <i>hashkifah</i> (Deut. l. c.) refers only to ‘thy holy dwelling’, ‘and bless’ to ‘from (the store of) the heavens’.</div>","alt":[]},"8392":{"h":"הַשְׁרָשָׁה","r":"E00939","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁרַשׁ\">שָרַשׁ</a>, <i>Hif.</i>) <i>taking root</i>. <span class=\"citation\">Pes. 55ᵃ</span> <span dir=\"rtl\">ובה׳</span> and as to counting the third day after planting for taking root. <span class=\"citation\">Y. Shebi. II, 34ᵃ</span> top <span dir=\"rtl\">אחר ה׳</span> we go by the date of taking root. <span class=\"citation\">Y. Kil. I, 27ᵇ</span> <span dir=\"rtl\">אינו רוצה בהַשְׁרָשָׁתָן</span> he has no interest in their taking root; <span class=\"citation\">Y. Maasr. V, 51ᵈ</span> top. <span class=\"citation\">Men. 69ᵃ</span>; a. fr.</div>","alt":[]},"8393":{"h":"הַשְׁתָּא","r":"E00940","html":"<div class=\"sense\"> (= <span dir=\"rtl\">הָא שַׁעְתָּא</span>) l) <i>now</i>. <span class=\"citation\">Targ. Prov. VII, 24</span>; a. fr.—<span class=\"citation\">Sabb. 91ᵃ</span>, a. fr. <span dir=\"rtl\">בתר ה׳ אזלינן</span> we go by the present condition. <span class=\"citation\">Pes. 4ᵃ</span> <span dir=\"rtl\">וה׳ דקי&quot;ל</span> and now that it is established that &amp;c. <span class=\"citation\">Ḥull. 97ᵃ</span> <span dir=\"rtl\">ה׳ דאמר וכ׳</span> now that R. … says &amp;c.; a. v. fr.—הכי ה׳ <i>so now!, indeed</i>, i.e. <i>how can you compare these two cases?</i> <span class=\"citation\">Snh. 41ᵇ</span>; a. fr.—2) (introducing an argument) <i>since, when, if</i>. <span class=\"citation\">Ḥull. 5ᵇ</span>, a. fr. <span dir=\"rtl\">ה׳ בהמתן … לא כל שכן</span> since the Lord does not allow any evil to come through a beast belonging to the righteous, how much less through the righteous themselves? <span class=\"citation\">Ib. 6ᵇ</span> <span dir=\"rtl\">ה׳ מיגזל גזלה חלופי מיבעיא</span> if she would take what is not her own, is there any question that she would eventually exchange her own for what belongs to her neighbor?; a. fr.</div>","alt":[]},"8394":{"h":"הִשְׁתַּחֲוָאָה","r":"E00941","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שָׁחָה\">(שָׁחָה</a>), <i>Hithpa.</i>) <i>prostration</i> for prayer. <span class=\"citation\">Ber. 34ᵇ</span>; <span class=\"citation\">Meg. 22ᵇ</span> <span dir=\"rtl\">ה׳ זו פישוט וכ׳</span> prostration means spreading out hands and feet. <span class=\"citation\">Y. Ber. I, 3ᵈ</span> top <span dir=\"rtl\">לך ה׳</span> before Thee prostration is due; a. fr.—[<span class=\"citation\">Y. Ab. Zar. IV, 43ᵈ</span> top <a href=\"#\" data-headword=\"שְׁתַחְוָיָה\">שְׁתַּחְוָיָה</a>.]—Pl. <span dir=\"rtl\">הִשְׁתַּחֲוָויוֹת</span>, <a href=\"#\" data-headword=\"הִשְׁתַּחֲוָאָה\">הִשְׁתַּחֲיָ׳</a>. <span class=\"citation\">Shek. VI, 1</span>. <span class=\"citation\">Ber. 31ᵃ</span> <span dir=\"rtl\">מפני כריעות וה׳</span> in consequence of his repeated kneelings and prostrations.</div>","alt":["הִשְׁתַּחֲוָיָה","וָיָיה","הִשְׁתַּחֲוָו׳"]},"8395":{"h":"הִשְׁתַּלֵּחַ","r":"E00942","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"הִשְׁתַּלַּחַת\">next w.</a></div>","alt":[]},"8396":{"h":"הִשְׁתַּלַּחַת","r":"E00943","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁלַח\">שָׁלַח</a>, <i>Hithpa.</i>) <span dir=\"rtl\">ה׳ יָד</span> <i>being stricken by divine hand, divine visitation</i>, v. <a href=\"#\" data-headword=\"הַשְׁלָמָה\">הַשְׁלָהָה</a>. <span class=\"citation\">Num. R. s. 15</span> Var. (ed. <a href=\"#\" data-headword=\"הִשְׁתַּלֵּחַ\">הִשְׁתַּלֵּחַ</a>); Tanḥ. B’haăl. 16 <span dir=\"rtl\">להשתלח</span>; (ib. ed. Bub. 27 <span dir=\"rtl\">לשִׁילּוּחַ</span>).</div>","alt":[]},"8397":{"h":"השתק","r":"E00944","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to I, 5</span> <span dir=\"rtl\">מערטלו ומהשתקו ומנרתקו</span>, read: <span dir=\"rtl\">מערטלו מנַרְתֵּיקוֹ</span>, or <span dir=\"rtl\">מנַשְׁתֵּיקוֹ</span>; v. <a href=\"#\" data-headword=\"נַרְתֵּק\">נַרְתֵּק</a> a. <a href=\"#\" data-headword=\"נַשְׁתֵּק\"><a href=\"#\" data-headword=\"נַשְׁתֵּק\">נַשְׁתֵּק</a>.</a></div>","alt":[]},"8398":{"h":"*הֲתוֹבְתָּא","r":"E00945","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (תּוּב <i>Af</i>.) <i>argument, objection</i>.—Pl. <span dir=\"rtl\">הֲתוֹבָתָה</span>. <span class=\"citation\">Y. Peah IV, 18ᵇ</span> top <span dir=\"rtl\">כל אילין ה׳ וכ׳</span> all objections which R. Z. brought forth. V. <a href=\"#\" data-headword=\"תְּיוּמְתָּא\">תְּיוּבְתָּא</a>.</div>","alt":[]},"8399":{"h":"הַתָּזָה","r":"E00946","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָתַז\">נָתַז</a>) <i>knocking off, cutting off</i>. <span class=\"citation\">Y. Snh. VII, 24ᵇ</span> bot. <span dir=\"rtl\">הַתָּזַת הראש</span> decapitation.</div>","alt":[]}};
